INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022301', 'AN1977', '皆川素子', 'モトコはとても執着心が強く、ロマンチックで、意志が固い。欲しいもの（あるいは人）を手に入れるためなら、どんな手段も厭わないが、必ずしも成功するとは限らない。 モトコは、片思いの相手である草摩ユキについて、よく愛の詩を綴っている。彼女は常にユキのことを考え、その話題で持ちきりだ。また、海原高校の「プリンス・ユキファンクラブ」の会長も務めている。彼女は主に遠くからユキを慕っており、実際に彼と話すことはめったにない。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b3874-N631hTrXB2Kg.jpg', NULL, NULL, '市道真央', NULL, 3874, 'SUPPORTING', 40) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022302', 'AN1977', '草摩楝', '草摩楝はアキトの母親である。レンはもともと草摩家の使用人だったが、当時の草摩家当主であるアキラの深い孤独に唯一気づき、単なる当主としてではなく、親切に接したことで、彼の心を掴んだのである。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b9755-9sOqyxC89M7D.png', NULL, NULL, '折笠愛', NULL, 9755, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022303', 'AN1977', '草摩紅野', '干支：酉　クレノは物静かで従順な男だ。', 26, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b4644-s7NSkE6KYFhe.jpg', NULL, NULL, '梅原裕一郎', NULL, 4644, 'SUPPORTING', 385) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022304', 'AN1977', '倉伎真知', '倉伎真知は、漫画『フルーツバスケット』に登場する架空の人物で、海原高校の生徒会会計を務めている。真知は物静かで内気な性格で、繊細でやや孤立しているように見える。彼女は漫画『フルーツバスケット』およびドラマCDに登場し、声優は海田由紀が担当している。    マチは真鍋翔の異母妹である。真鍋は彼女を非常に大切にしており、兄弟としての優越感というよりは、兄としての愛情から、よく彼女に指図をしている姿が見られる。    マチはとても物静かな', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b6571-H6JruBvnORjl.jpg', NULL, NULL, '加隈亜衣', NULL, 6571, 'SUPPORTING', 620) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022305', 'AN1977', '神様', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b231889-SHd6QPgXna62.png', NULL, NULL, '神谷浩史', NULL, 231889, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022306', 'AN1977', '草摩晶', '草摩晶は、かつて草摩家の当主だった。彼は草摩慊人の父であり、草摩楝の夫でもある。アキラは、アキトに「あなたは選ばれた子、愛されるために生まれた子だ」と告げた人物だった。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b212557-443D3jIpFm96.png', NULL, NULL, '石田彰', NULL, 212557, 'SUPPORTING', 18) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022307', 'AN1977', '草摩利津', '干支：申　彼が物心ついた頃から、自分のしたことは何でも両親が謝らなければならなかったため、彼は自分に自信が持てない。毎日、呼吸をするたびに、世界から空気を奪っているような気がしている。  女の子のような格好をしていると、いつも気持ちが楽になることに気づいたが、それは両親に謝る理由をさらに増やすだけだった。彼は女の子にそっくりなので、トオルも初めて彼を見たときはそう思っていたが、彼がうっかり変身してしまうまでは。どういうわけか、トオルは彼を説得して……', 21, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b373-2hzWde5fNiwk.png', NULL, NULL, '河西健吾', NULL, 373, 'SUPPORTING', 197) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022308', 'AN1977', '魚谷ありさ', 'アリサは元ギャング（*ヤンキー*：アメリカの「ギャング」イメージを日本風にアレンジしたもの）で、トオルが「レディース」というギャングから抜け出したいと願っていた際、トオルの母親が彼女を助けて以来、トオルの最も親しい友人の一人となっている。  アリサはタフで、奔放、時には暴力的だが、友人に関することになるとすぐに涙を流してしまう。彼女はロングスカートをはき、鉛パイプを持ち歩き、よく男のような話し方をする（日本語では、言葉の選び方によって話し手が男性か女性かと判断されることがある）。アリサは', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b375-RYqdBrPJL06c.jpg', NULL, NULL, '種﨑敦美', NULL, 375, 'SUPPORTING', 1246) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022309', 'AN1977', '草摩楽羅', '干支：猪　彼女は幼い頃から京に想いを寄せていたが、京が彼女の友人である本田透に想いを寄せていることは知らない。 幼い頃、猫の呪いを背負って一人ぼっちだった彼を「気の毒に」思った彼女は、彼と遊んだり世話をしたりしていた。 やがて、その気持ちは彼に対する、ほとんど執着に近い愛へと発展していった。彼女は、彼と結婚すると確信している。その主な理由は、彼を脅してプロポーズさせたからである（漫画では7歳の時にナイフを突きつけて、あるいは…）。', 19, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b366-5iIIhczrc3Qr.jpg', '7月6日', 'B', '釘宮理恵', NULL, 366, 'SUPPORTING', 315) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022310', 'AN1977', '草摩依鈴', '干支：馬　彼女は意志が強く、頑固で、独立心旺盛な女性であり、一族の他のメンバーがアキトに従う姿を嫌悪している。背が高く、当初は腰までの長さの黒髪をしている。 彼女は孤立しがちだが、時折ヒロと一緒にいる姿が見られる。ヒロは、初春、カグラ、そしてカグラの母親と共に、凛が病院に入院していた間、彼女を訪ねてきた唯一の人々だった。 リンは初春を愛しているが、彼を解放する方法が見つかるまで、彼を守るために別れを告げる。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b3892-Cv49n98SjFIE.png', NULL, 'B', '豊崎愛生', NULL, 3892, 'SUPPORTING', 1870) ON CONFLICT DO NOTHING;
