INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022312', 'AN1978', '小戸川宏', '職業：タクシー運転手　小川は、人に対して心を開かない、風変わりで物静かな人物だ。真面目で思いやりのある一面も持っている。趣味は、寝る前に落語を聴くことと、仕事中にラジオを聴くことだ。', 41, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b204522-tiKCzn4Wxpys.png', '5月25日', NULL, '花江夏樹', NULL, 204522, 'MAIN', 1331) ON CONFLICT DO NOTHING;
