INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022320', 'AN1978', '剛力', '職業：医師　「剛力クリニック」の院長であり、小土川のかかりつけ医。患者であり友人でもある小土川のことを常に気にかけている。穏やかで、聡明、そして真面目な人物。妻と子供がいる。', 41, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b204524-AL7cVYW1v9kB.jpg', NULL, NULL, '木村良平', NULL, 204524, 'SUPPORTING', 66) ON CONFLICT DO NOTHING;
