INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022339', 'AN1979', '300年前のナタリー', '300年前のナタリー・シニアは、かつてフラッタの冒険者ギルドでしばらくの間、受付係を務めていた。  あずさが冒険者ギルドに到着すると、300年前のナタリーは彼女を出迎え、彼女が持ち込んだスライムクリスタルで得た報酬額を概算した後、ギルドへの登録手続きを行った。 驚いたことに、300年前のナタリーは、彼女の「不死」の能力が素晴らしいと評した。（出典：スライムとして300年 ファンダムWiki）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b217736-Brn5hNLKz2Ej.png', NULL, NULL, '幸村恵理', NULL, 217736, 'SUPPORTING', 15) ON CONFLICT DO NOTHING;
