INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022343', 'AN1979', 'クク', 'デスメタルを演奏するのが好きな、半人半兎のキャラクター。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b225114-mpJBEPapyXov.png', NULL, NULL, '小岩井ことり', NULL, 225114, 'SUPPORTING', 75) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022344', 'AN1980', 'レム・ガレウ', 'レム・ガレウは、このシリーズの女性主人公の一人である。彼女はパンテリアンであり、インヴォーカーとなった後、魔王クレブスクルムを討伐することを目標に掲げ、その力を示し続けるため、やむを得ず冒険者となる道を選んだ。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126795-YJDrBD9Rvmiu.png', NULL, NULL, '和氣あず未', NULL, 126795, 'MAIN', 1218) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022345', 'AN1980', 'ディアヴロ', '坂本拓馬（サカモト・タクマ）、別名ディアヴロ（ゲーマータグ：「ディアヴロ-13」）は、本シリーズの男性主人公である。彼は『クロス・レヴェリー』のプレイヤーであり、「真の魔王」として知られるキャラクター「ディアヴロ」を操作していた。 彼は、自分より優れた装備や圧倒的なスキルを持つプレイヤーを常に打ち負かしていたが、強すぎることを気にして常に力を抑えていた。しかしある日、彼は異世界に召喚され、自身のキャラクターである「ディアヴロ」の体に転生し、自分を召喚したと主張するパンテリアンとエルフの2人の少女と出会うことになる。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126793-vBdTPhopqVB1.png', NULL, NULL, '水中雅章', NULL, 126793, 'MAIN', 847) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022346', 'AN1980', 'シェラ・L・グリーンウッド', 'シェラ・L・グリーンウッドは、このシリーズの女性主人公の一人である。彼女はエルフであり、ディアブロを召喚した二人の召喚士の一人だ。彼女がディアブロを召喚したのは、自由に生きるための力を得るためだった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126791-9AfKK44xRloo.png', NULL, NULL, '芹澤優', NULL, 126791, 'MAIN', 835) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022347', 'AN1980', 'ルマキーナ・ウエスエリア', 'ルマキーナ・ウエスエリアは、神々の教会の大祭司である。彼女は、神々の教会からの詐欺や汚職、その他の不祥事に関する苦情を敢えて調査したため、パラディンであるゲイバルトに暗殺の標的として追われているという設定で登場する。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b184003-9FeZa4FI53hn.png', NULL, NULL, '伊藤美来', NULL, 184003, 'MAIN', 177) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022348', 'AN1980', 'シルヴィ', 'グラスウォーカーである彼女は、小柄な体つきで、ウサギのような耳と尾を持っている。彼女は冒険者ギルドのリーダーである。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/127046-qHV2pjCl0B38.jpg', NULL, NULL, '大久保瑠美', NULL, 127046, 'SUPPORTING', 211) ON CONFLICT DO NOTHING;
