INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022352', 'AN1980', 'エミール・ビュシェルベルジェール', '冒険者ギルドで最強と称される人間。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/127051-h3Csiyi3Md3q.jpg', NULL, NULL, '置鮎龍太郎', NULL, 127051, 'SUPPORTING', 35) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022353', 'AN1980', 'サンロ', '王都セブンウォールの教区に住む、敬虔な教会の信者。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b228924-xC5EizaIUgTL.png', NULL, NULL, '村瀬歩', NULL, 228924, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022354', 'AN1980', 'ロゼ', 'ロゼはディアヴロの「マジマティック・メイド」である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b184001-GBLuhulPuDt4.png', NULL, NULL, '古賀葵', 165, 184001, 'SUPPORTING', 227) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022355', 'AN1980', 'メイ', '彼女は「ピース・オブ・マインド・イン」のアイドル的存在だ。客との接し方では、エネルギッシュで楽天的な一面を見せるが、手に負えない客に対しては、威圧的な態度で一喝することもある。 彼女が相手にするのが料金を支払う客である限り、人種や出身地は一切気にしない。人間であれ、パンテランであれ、悪魔であれ、あるいはフォールンであれ、彼女にとってはどうでもいいことだ。さらに、隣室の客に迷惑をかけたり、施設に損害を与えたりしない限り、客が部屋の中で何をしていようとも、彼女は一切気にしない。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/127048-TD9gwjFKcMHB.jpg', NULL, NULL, '森嶋優花', NULL, 127048, 'SUPPORTING', 38) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022356', 'AN1980', 'ビジョス', '教会内で絶大な権力を握る最高位の大司教。ルマチーナが教会の権威に異議を唱えていることを理由に、彼女を殺害しようと暗殺者を雇う。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b228925-0KAQ7kZFMWnP.png', NULL, NULL, '鳥海浩輔', NULL, 228925, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022357', 'AN1980', 'セレステイーヌ・ボードレール', 'セレステイン・ボードレールは、ファルトラ市の「メイド協会」の代表を務めている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/127050-PPbPZsJTrq49.jpg', NULL, NULL, '千本木彩花', NULL, 127050, 'SUPPORTING', 51) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022358', 'AN1980', 'エデルガルト', '彼女は小柄で美しい悪魔の少女で、褐色の肌（肌表面は鱗のように見える）を持ち、腰まで届く長い銀色の髪と、爬虫類のように縦に裂けた瞳孔を持つ大きな金色の瞳をしている。その瞳からは、どこか子供っぽい雰囲気が漂っている。（出典：『魔王を召喚しない方法』Wiki）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n127045-WUgI2ODodES5.png', NULL, NULL, '加藤英美里', NULL, 127045, 'SUPPORTING', 301) ON CONFLICT DO NOTHING;
