INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022360', 'AN1980', 'アリシア・クリステラ', 'アリシア・クリステラはインペリアル・ナイトである。彼女は公爵家の娘として生まれた。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n127047-R7k6vPVC0uwb.png', NULL, NULL, '原由実', NULL, 127047, 'SUPPORTING', 121) ON CONFLICT DO NOTHING;
