INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022362', 'AN1980', 'クレブスクルム', '『ソルの魔王、クレブスクルム』は、堕ちた者たち（悪魔たち）の支配者である。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b127423-SpNvQlBwRyrY.png', NULL, NULL, '種﨑敦美', NULL, 127423, 'SUPPORTING', 293) ON CONFLICT DO NOTHING;
