INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022364', 'AN1981', 'キサラギ＝アリス', 'キサラギ社が誇る最新技術を用いて開発された高性能アンドロイド。過度の暴力にさらされると、内蔵のリアクターがメルトダウンを起こし、自爆する。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155191-zoVESmqPgyS6.png', NULL, NULL, '富田美憂', NULL, 155191, 'MAIN', 646) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022365', 'AN1981', 'スノウ', 'スラム街から這い上がり、王室近衛隊の隊長にまで上り詰めた勤勉な女性。非常に野心的で、功績を自分の手柄にしようと熱心に振る舞う。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b155192-dBrThduLWwjK.png', NULL, NULL, '菊池紗矢香', NULL, 155192, 'MAIN', 330) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022366', 'AN1981', 'ロゼ', 'カービィのように、食べたモンスターの能力をコピーできるキメラ。彼女は、年老いた生みの親の最期の言葉を絶対的な真理として受け止めているため、その結果……かなり安っぽいセリフを口にしてしまう。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b155195-YFFAhsk6SLPm.png', NULL, NULL, '村上奈津実', NULL, 155195, 'MAIN', 316) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022367', 'AN1981', 'グリム', '彼女は大司教です。彼女は、誤って自分自身にかけた「靴を履いてはいけない」という呪いのせいで、車椅子での生活を送っています。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155194-OO2HJKa4hKOI.png', NULL, NULL, '髙橋ミナミ', NULL, 155194, 'MAIN', 380) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022368', 'AN1981', '戦闘員六号', '「コンバット・エージェント・シックス」として知られるこの男は、高校1年生の時、つまり物語の始まりの約3～4年前に、キサラギ社に入社した。19歳の時に同社のアルバイトとして働き始めた。  シックスは組織内で最年長のメンバーの一人であり、将軍たちを除けば組織に残っている最年長者である。そのため、同社が世界征服の瀬戸際にあった際、シックスは地球に似た別世界を征服するためにその探索を行う候補者の一人に選ばれた。  S', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b155193-VcVxKqogXn5E.png', NULL, NULL, '白井悠介', NULL, 155193, 'MAIN', 361) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022369', 'AN1981', 'ティリス', '彼女はグレース王国の王女であり、現在、グレース王国を統治している。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b216644-7UrZAEbmV4BX.png', NULL, NULL, '前田佳織里', NULL, 216644, 'SUPPORTING', 55) ON CONFLICT DO NOTHING;
