INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022371', 'AN1981', 'Heine', '魔王の精鋭部隊の一員であり、「炎のハイネ」としても知られる。彼女は巨大なバストの持ち主だ。色黒の半人種が好きなら、この魔女は間違いなくあなたのタイプだろう。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155196-OcCVRwifzHLY.png', NULL, NULL, '瀬戸麻沙美', NULL, 155196, 'SUPPORTING', 186) ON CONFLICT DO NOTHING;
