INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022378', 'AN1981', 'アスタロト', 'フリージング・アスタロトは、キサラギの最高指導者である。キサラギ・コングロマリット会長の娘であり、「大いなる炎」ベリアルや「闇」リリスと共に悪の組織「キサラギ」を設立し、リリスによる手術を受けて氷を操る能力を得た。 アスタロトは、シックスから「自分の夫になる」といった支離滅裂な懇願を受けつつ、組織への加入を懇願された。アスタロトは、悪の組織「キサラギ・コングロマリット」の三将軍の一人である。彼女と彼女の同僚は', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b215442-UwEDOGHjMmOR.png', NULL, NULL, '渡部紗弓', NULL, 215442, 'SUPPORTING', 167) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022379', 'AN1981', 'ラッセル', '悪魔の指揮官の一人であるラッセルは、（ロゼと同様に）古代文明によって人類を滅ぼすために生み出された戦闘用キメラだが、自身の記憶は残っている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b233316-ptKTFKBuIhRy.jpg', NULL, NULL, '伊藤美来', NULL, 233316, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022380', 'AN1981', 'ベリアル', '「大いなる炎」ベリアルは、キサラギの最高指導者である。由緒あるカゾク家の娘であるベリアルは、友人のアスタロトがキサラギを設立するのを助け、闇のリリスと共に戦闘部門のトップに就いた。  ベリアルは、シックスを異世界への偵察任務に派遣した将軍の一人である。彼女は自らその任務に行きたかったと公言しているが、サイコロの出が悪かったため、選ばれなかった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b215441-Zv33sxlHKANy.png', NULL, NULL, '日高里菜', NULL, 215441, 'SUPPORTING', 95) ON CONFLICT DO NOTHING;
