INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022405', 'AN1982', 'マエマロ', 'マエマロは、魔界にあるウォルター・パークの正社員です。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b157338-AK1EUFePeAoi.png', NULL, NULL, '佐久間元輝', NULL, 157338, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022406', 'AN1982', '鬼・エイコ', 'エikoはバビルス・デーモン・スクールに通う新入生だ。鈴木入間に助けられて以来、彼女は常に彼と会話をしようと試みているが、シリーズを通じてその試みはすべて失敗に終わっている。 彼女は比較的社交的で、普段は名前のない脇役たちと気軽に話している姿が見られるが、主に親しい友人グループと行動を共にしている。尊敬する相手と話すときは恥ずかしがり屋で、例えば入間に助けてもらったお礼を何度も伝えようとする場面などが見られる。このように、彼女は', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b148550-pNULk2kNF9KW.png', NULL, NULL, '浅見春那', NULL, 148550, 'SUPPORTING', 103) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022407', 'AN1982', 'バルス・ロビン', '継承された魔法：ブルズアイ・ショット　ロビンはバビルスに新しく赴任した教師で、生徒たちに使い魔との絆を築く方法を教えている。', 22, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b154372-R2Z0ow4FIf8V.png', '8月31日', NULL, '吉永拓斗', NULL, 154372, 'SUPPORTING', 89) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022408', 'AN1982', 'ウァラク・ウララ', 'ウララはヴァラック家の長男である。彼は非常に真面目で礼儀正しく、他の家族のような風変わりな性格は持ち合わせていない。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155692-J1QrmvvYKBz6.png', NULL, NULL, '朝井彩加', NULL, 155692, 'SUPPORTING', 16) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022409', 'AN1982', 'バール', 'バールは『13の王冠』に登場する悪魔の英雄の一人であり、「雷の王」としても知られている。彼はバビルス悪魔学園の「魔法装置バトル」の創設者であるが、その一方で、テロ組織「シックス・フィンガーズ」の創設者でもある。  影で暗躍する彼は、「悪魔改革」の黒幕であり、悪魔界の現行体制をその起源へと遡らせようとしている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155683-4bRpLoXWpaTF.png', '4月1日', NULL, '諏訪部順一', 190, 155683, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
