INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022416', 'AN1982', 'バディン・バラキ', '彼はバビルスの学生であり、「ブロードキャスティング・バトラー」の会長を務めている。', 18, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b162690-dAa1Bu7qP1rV.png', '1月8日', NULL, '八代拓', NULL, 162690, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022417', 'AN1982', 'ダンダリオン・ダリ', 'バビルスで名高い教授の一人。現在、バビルスで知られている中で最も古参の教授であり、アカデミーの教育監督を務めている。また、「悪魔史」を教え、エイコのクラスのホメロム担任も務めている。 ストラス・スージーと共に、学園のイベントコーディネーターや司会者としてよくその姿を見かける。彼の家族はバビルスに常駐する任務を負っている。「ダリ」という名の教師の役割は、彼の家系において代々受け継がれてきたものである。その前任者は、カ時代にも教師を務めていた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b162684-w0ZDtG99c0Wm.png', '7月17日', NULL, '石井マーク', NULL, 162684, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022418', 'AN1982', 'ウァラク・ランラン', 'ラン・ラン・ヴァラックは、クララの末の妹です。彼女はヴァラック家の三女であり、6人目の子供です。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b155686-n95VVtb2zw3a.jpg', NULL, NULL, '朝井彩加', NULL, 155686, 'SUPPORTING', 14) ON CONFLICT DO NOTHING;
