INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022421', 'AN1982', 'オリアス・オズワール', '受け継がれた魔法：星の配列   オスワールはバビルスで占星術を教えている。彼の能力は「ラッキー・ハッピー」で、これにより物事がすべて思い通りに進む。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b172532-TOYmH1ynGnYM.png', '5月9日', NULL, '梶原岳人', NULL, 172532, 'SUPPORTING', 23) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022422', 'AN1982', 'マミー', 'マミーは、クララ、ウララ、コンチー、キーボウ、シンシン、ランラン・ヴァラックの母親です。彼女は子供たちに対してとても愛情深く、ウララと、その存在がほのめかされるだけの父親を除く全員と一緒に、よく歌を歌い出す姿が見られます。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b155688-BGCRyzlfRF3d.jpg', NULL, NULL, '朝井彩加', NULL, 155688, 'SUPPORTING', 46) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022423', 'AN1982', 'ドドド', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b292970-KRteHADmA6gH.jpg', NULL, NULL, '中村大志', NULL, 292970, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022424', 'AN1983', 'ケイト', 'ケイトは、貴族であるシャドウ家の若い娘です。彼女の「リビング・ドール」はエミリコです。シャドウ家の他の者たちと同様、ケイトもまた「影」です。髪を含め、全身が黒いです。彼女は、下に白いフリルがついた赤いドレスを着ています。とても穏やかで知的な若い娘です。   シーズン1のネタバレ', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/127319-YrQfLMfAcJHw.png', NULL, NULL, '鬼頭明里', NULL, 127319, 'MAIN', 1103) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022425', 'AN1983', 'エミリコ', 'エミリコは『シャドーハウス』シリーズの主人公であり、一部の章では語り手も務めている。彼女はシャドーハウスでメイドとして働き、ケイト・シャドウの「顔」としての役割も担う「生ける人形」である。  エミリコは明るく、働き者だ。彼女にとって最優先事項は、友人でもある主人であるケイト・シャドウの世話をすることだ。彼女は友達を作るのが好きで、一緒に過ごす時間を大切にしている。経験が浅く、時々不器用な面もあるが、頼りになる存在でもある。彼女は常に前向きな姿勢を保ち、他人のために立ち上がる。エミ', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b127318-JTyhIyNHR2Be.png', '2月23日', NULL, '篠原侑', NULL, 127318, 'MAIN', 1046) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022426', 'AN1983', 'バービー', '子供部門のリーダーを務めるバーバラの「顔」。他の「生きた人形」たちは、彼女の厳しい口調や性格を恐れている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b200344-3wB60RQMtqFN.png', NULL, NULL, '釘宮理恵', NULL, 200344, 'SUPPORTING', 95) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022427', 'AN1983', 'バーバラ', 'バーバラは、その屋敷に住み、「リビング・ドール」ことバービーの世話を受けているシャドウである。また、スター・ベアラーズのリーダーでもあり、子供たちの育成を担当している。 漫画のネタバレ：', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b200345-etW6BYyjtMYX.png', NULL, NULL, '釘宮理恵', NULL, 200345, 'SUPPORTING', 69) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022428', 'AN1983', 'ベル', '彼女の双子の姉であるベルと混同しないでください。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b200388-uzvSONHL7H07.jpg', NULL, NULL, '大久保瑠美', NULL, 200388, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022429', 'AN1983', 'ミア', '彼女は「サラ」の「顔」的存在だ。エミリコと一緒に掃除をする際、彼女を先輩として接し、「顔」としての役割を非常に真剣に受け止めている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b200342-CQyMbQoD1j3z.png', NULL, NULL, '大西沙織', NULL, 200342, 'SUPPORTING', 39) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022430', 'AN1983', 'ライアン', '『シャドーハウス』に登場する、傲慢でサディスティックな大人', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b200408-Xo1P14vHL9YR.jpg', NULL, NULL, '岸尾だいすけ', NULL, 200408, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
