INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022432', 'AN1983', 'ショーン', 'ショーンは、『シャドーハウス』シリーズのサブ主人公の一人である。彼はシャドーハウスで使用人として働き、ジョン・シャドウの「顔」としての役割も担う「リビング・ドール」である。彼は仕事を完璧にこなし、密かに予知能力を持っている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b197306-P0WWoptWyEZl.png', NULL, NULL, '酒井広大', NULL, 197306, 'SUPPORTING', 332) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022433', 'AN1983', 'リッキー', 'リッキーは、『シャドーハウス』シリーズのサブ主人公の一人である。彼はシャドーハウスで使用人として働き、パトリック・シャドウの「顔」としての役割も担うリビング・ドールだ。リッキーは、主人のパトリック以上に、非常に自信家かつ自己中心的な人物として知られている。 彼は他のリビング・ドールたちともうまくやっており、特にルウを気に入っている。彼とパトリックは仲が良く、互いに信頼し合っているようだ。しかし、パトリックと同様に、リッキーもまた、傲慢な態度を装って……', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b200247-CKElkBHpQxin.png', NULL, NULL, '川島零士', NULL, 200247, 'SUPPORTING', 87) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022434', 'AN1983', 'ソフィ', '煤が大量に付着したシャドウホースの成体', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b200407-7C8oPyaxzfHU.jpg', NULL, NULL, '花守ゆみり', NULL, 200407, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022435', 'AN1983', 'ダグ', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b200394-6YcEDi8hFruK.png', NULL, NULL, NULL, NULL, 200394, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022436', 'AN1983', 'ジョン', 'ジョンは『シャドーハウス』シリーズのサブ主人公の一人で、「リビング・フェイス」ことショーンの世話を受けているシャドウである。ジョンは誰に対しても非常に親しみやすく、とても寛容な性格として知られている。 多くのシャドウとは異なり、彼はショーンを敬意を持って接しており、ショーンが眼鏡をかけている間も、自分も眼鏡をかけることを申し出るほどだ。 ケイトやエミリコと同様、ジョンとショーンは正反対の性格だ。ジョンは筋肉バカで外向的であるのに対し、ショーンは思慮深く内向的である。それにもかかわらず、二人は非常に仲が良く……', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b197307-Iaz5bsfhqWSu.jpg', NULL, NULL, '酒井広大', NULL, 197307, 'SUPPORTING', 381) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022437', 'AN1983', 'ルウ', 'ルウは『シャドーハウス』シリーズのサブ主人公の一人である。彼女はリビングドールであり、屋敷でメイドとして働き、ルイーズ・シャドウの「顔」としての役割も担っている。ルウは、主人のあらゆる命令に耳を傾ける、物静かで従順な少女だ。 彼女の最優先事項は、ルイーズの世話と自身の安全を守ることです。自分の「顔」が傷つくことをよく心配し、他人のパーソナルスペースに踏み込んでしまうこともあることで知られています。一度何かを決めると、それを成し遂げるために非常に粘り強く取り組む性格で、特にそれが', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b197877-9lXL9UFH9pgV.png', NULL, NULL, '佐倉綾音', NULL, 197877, 'SUPPORTING', 206) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022438', 'AN1983', 'ジョゼフ', '落ち着きがあり、威厳のある大人で、助言者としての役割を果たしている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b200409-Qb1R0hsudUGF.jpg', NULL, NULL, '三宅健太', NULL, 200409, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022439', 'AN1983', 'ダグラス', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b200395-amXkUxW8oFkF.jpg', NULL, NULL, NULL, NULL, 200395, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022440', 'AN1983', 'ルイーズ', 'ルウiseは『シャドーハウス』シリーズのサブ主人公の一人で、「リビング・ドール」であるルウの世話を受けているシャドウである。ルウiseは生意気で自信に満ちている。 彼女は自分のフェイスであるルウを自慢するのが大好きで、ルウを心から信頼している。自分の部屋の壁には、ルウの絵がいくつも貼ってある。真面目な話は退屈だと感じており、ただ楽しみたいだけだという面もある。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b198188-dlogAdwwQZd8.jpg', NULL, NULL, '佐倉綾音', NULL, 198188, 'SUPPORTING', 55) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022441', 'AN1983', 'パトリック', 'パトリックは『シャドーハウス』シリーズのサブ主人公の一人で、「リビング・ドール」ことリッキーの世話を受けているシャドウである。パトリックは傲慢で自信家であり、忠実な性格だ。強い責任感を持っており、自分を助けてくれた者には恩返しをする。 彼の「顔」であるリッキーほど自惚れてはいないが、時折うっとうしい面もある。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b200311-NduxAgGY2tK8.png', NULL, NULL, '川島零士', NULL, 200311, 'SUPPORTING', 107) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022442', 'AN1983', 'ドロシー', '退屈を嫌い、快楽を求める、シャドーハウスの美しい女性であり大人', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b200410-ASh0Tze9UJZ8.png', NULL, NULL, '日笠陽子', NULL, 200410, 'SUPPORTING', 14) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022443', 'AN1983', 'ラム', 'ラムは『シャドーハウス』シリーズのサブ主人公の一人です。彼女はシャドーハウスでメイドとして働く「リビング・ドール」であり、シャーリーの「顔」としての役割を果たしています。  ラムはとても内気で孤独な少女だ。主人に「おやすみ」のキスをすることはないだけでなく、自分の名前も自分で名付けた。彼女は非常に自信がなく、自分を落ち着かせるために指に話しかける癖がある。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b200340-KXUARJZsBkHK.png', NULL, NULL, '下地紫野', NULL, 200340, 'SUPPORTING', 86) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022444', 'AN1983', 'シャーリー', 'シャーリーは『シャドーハウス』シリーズのサブ主人公の一人で、「リビング・フェイス」であるラムの世話を受けているシャドウである。ラムはマスターとほとんど時間を過ごさないため、シャーリーの人柄についてはあまり描かれていない。 彼女を最もよく表す言葉といえば、彼女の「フェイス」と同様に、物静かで内気だということだろう。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b200341-skRI7QIlA8Xs.jpg', NULL, NULL, '下地紫野', NULL, 200341, 'SUPPORTING', 28) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022445', 'AN1983', 'アイリーン', '彼女はエドワードのチームの一員であり、ソットでできた生き物を操る能力を持っている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b200404-Z59nXs5OlTBy.png', NULL, NULL, '堀江由衣', NULL, 200404, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022446', 'AN1983', 'サラ', '彼女は「生ける人形」ミアと共に暮らすシャドウであり、ミアに対して厳しい体罰を加えている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b200343-FAmtjSJc90DV.png', NULL, NULL, '大西沙織', NULL, 200343, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022447', 'AN1983', 'エドワード', 'ホースの小児病棟の責任者。彼の目標は、メインのホースの3階に昇進することだ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b200406-TPH6pIGsuxUX.png', NULL, NULL, '羽多野渉', NULL, 200406, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022448', 'AN1983', 'ジェラルド', '彼はエドワードのチームの一員であり、サポート役を務めている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b200405-3M1WbD0uRbuK.png', NULL, NULL, '大塚剛央', NULL, 200405, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022449', 'AN1983', 'ローズマリー', 'エミリコと共に分隊長を務めるマリーローズの「顔」。誰に対しても親切だが、のんびりしていて不器用なところもある。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b200346-YsiTW7BWCkZy.png', NULL, NULL, '中原麻衣', NULL, 200346, 'SUPPORTING', 65) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022450', 'AN1983', 'マリーローズ', '彼女は「生ける人形」ローズマリーの影の分身であり、児童棟で最年長の人物である。陽気な性格で、踊ることが大好きだ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b200347-nQKcuAvXtjgH.jpg', NULL, NULL, '中原麻衣', NULL, 200347, 'SUPPORTING', 92) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022451', 'AN1983', '偉大なるおじい', 'シャドウ・ホーズの総主教', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b200411-48A1pS0jsqaS.jpg', NULL, NULL, '土師孝也', NULL, 200411, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022452', 'AN1984', 'リリナ', 'リリナは、リムルがドワーゴンへ出かけている間に、リムルのゴブリン村へ移住してきた400体のゴブリンのうちの1体である。リムルから名前を授かった後、ゴブリーナへと進化した。彼女はリムルから、テンペストの生産業務を監督者として管理するよう任されている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b219458-KAl6eFCkh0Eh.jpg', NULL, NULL, '近藤玲奈', NULL, 219458, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022453', 'AN1984', 'アピト	', '迷宮の80階の守護者。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b188669-jZScqdIsznBO.png', NULL, NULL, '上田麗奈', NULL, 188669, 'SUPPORTING', 16) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022454', 'AN1984', 'フューズ', '彼はブルムンド王国の「自由協会」のギルドマスターである。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b134580-1UuyTDv0rPDg.jpg', NULL, NULL, '成田剣', NULL, 134580, 'SUPPORTING', 21) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022455', 'AN1984', 'ゼギオン', 'リムル・テンペストが指名した9番目の部下グループの一人。元々は、日本のカブトムシに似た姿をした負傷したモンスターだったが、リムルが「かっこいい」と思い、彼を引き取り、迷宮の中で保護した。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b188666-CpC59dlsjaBN.png', NULL, NULL, '梅原裕一郎', NULL, 188666, 'SUPPORTING', 56) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022456', 'AN1985', 'シキ・グランベル', '物語の主人公であるシキは、人懐っこいものの社交が苦手な少年で、ロボットたちが暮らす惑星グランベルにあるファンタジーテーマパーク「グランベル王国」で、唯一の人間として暮らしている。 彼は、パークのアニマトロニクス製の魔王から受け継いだ「エーテルギア」という能力を持っており、これにより機械のような力を発揮することができる。シキは「サタン・グラビティ」と呼ばれるその能力の一種を使い、自身の重力を変化させたり方向を変えたりすることができる。人工の家族に励まされながら……', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126469-0qKVqlbEj9JG.png', NULL, NULL, '寺島拓篤', NULL, 126469, 'MAIN', 705) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022457', 'AN1985', 'レベッカ・ブルーガーデン', 'ヒロインのレベッカ・ブルーガーデンは、惑星ブルーガーデン出身の親切で元気な少女。チャンネル登録者数100万人を目標に、さまざまな惑星を旅して動画を撮影し、動画共有サイト「アオネコ」の自身のチャンネルにアップロードしている。彼女は「アクア・ウィング」という宇宙船を操縦しており、この宇宙船は海上船としても機能する。  レベッカの能力「リーパー」は、ジャンプ能力を強化するエーテルギアであり、彼女に驚異的なスピードと敏捷性を与えてくれる。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126467-y4nX1uDjZ2VZ.png', NULL, NULL, '小松未可子', NULL, 126467, 'MAIN', 624) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022458', 'AN1985', 'ハーミット・ミオ', 'ハーミット・ミオは、「フォー・シャイニング・スターズ」のメンバーであるアンドロイドだ。彼女の能力「マスターコード」は、プログラムハッキングの一種である。ハーミットは服やビデオゲームが好きで、以前は人間が嫌いだったが、今はもうそうではない。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b154652-cI8zW1FoUVxP.jpg', NULL, NULL, '高尾奏音', NULL, 154652, 'MAIN', 285) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022459', 'AN1985', 'ハッピー', 'ハッピーは、エクシード星出身の機械猫であり、レベッカ・ブルーガーデンの相棒であり、『エデンズ・ゼロ』のクルーの一員である。彼の能力「ハッピー・ブラスターズ」により、エーテルの弾丸を発射する一対の銃へと変身することができる。この弾丸は、標的を無力化させるほどの威力を持つが、殺すことはできない。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b203889-ncXC9xRe9s8a.jpg', NULL, NULL, '釘宮理恵', NULL, 203889, 'MAIN', 153) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022460', 'AN1985', 'シスター・イヴリィ', 'シスター・イヴリーは「フォー・シャイニング・スターズ」に所属する機械生命体である。彼女の能力「ヒール・アトマイザー」は、ヒーリング・エーテルの能力であり、傷を癒やし、負のステータス効果を解除し、生体機械を修復することができる。 シスターは短気で、からかうのが好きで、のんびりとした性格だが、責任感が強く、味方に対しては親しみやすい一面もある。サディスティックな一面もあり、拷問を楽しむ。治癒できないものを嫌う。  シスターは、機械にとって死が最終的な結末であることを受け入れられない人物であることが示されており、', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b154653-JRXVBIFjAOTz.jpg', NULL, NULL, '藤井ゆきよ', NULL, 154653, 'MAIN', 252) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022461', 'AN1985', 'ワイズ・シュタイナー', 'ヴァイスは『エデンズ・ゼロ』のメンバーであり、惑星ノルマ出身の元泥棒である。彼の能力は、機械を操るエーテルギア「マキナ・メイカー」だ。ヴァイスは利己的で頑固、虚栄心が強く、変態的な一面も持つ男だ。しかし、友人たちを大切にしており、彼なりのやり方で他者を気遣う面もある。 ワイズはお金とバニーガールが好きで、勉強が嫌いだ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b139877-iS3Gk1VaIwrf.png', NULL, NULL, '手塚ヒロミチ', NULL, 139877, 'MAIN', 273) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022462', 'AN1985', 'ウィッチ・リグレット', 'ウィッチ・リグレットは、「フォー・シャイニング・スターズ」に所属する機械生命体である。彼女は「エデンズ・ゼロ」の防衛を担当している。彼女の能力「シールド・エーテル」により、エーテルでできたバリアを生成することができる。   ウィッチは非常に忠実で、ジギーとその養孫であるシキに対して深い敬意を抱いている。普段は感情を表に出さないが、ウィッチも感情を示すことはできる。ただ、他人に自分の顔を見せることを恥ずかしく思っている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b154254-62DER4tnyGed.png', NULL, NULL, '安野希世乃', NULL, 154254, 'MAIN', 215) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022463', 'AN1985', 'EMピーノ', 'ピノは、「エデンズ・ゼロ」のクルーに加わった小型のボット対策マシンだ。彼女はEMP（電磁パルス）を放出することができ、これにより電子機器を数秒間機能停止させたり、使用中のエーテルギアの効果を無効化したりすることができる。  彼女のデジタルアバターは、ウサギのような耳を持つ若い少女の姿をしている。首には、大きなハートが一つあしらわれたネクタイを締めている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b154655-mzkGhnSyV52y.png', NULL, NULL, '井澤詩織', NULL, 154655, 'MAIN', 143) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022464', 'AN1985', 'コウゲツホムラ', 'コウゲツ・ホムラは、『エデンズ・ゼロ』に登場する魔王の一味の一員であり、自らを「プラネット・ブルーガーデン出身の騎士」と称している。彼女の能力「ソル・ブレード」は、エーテルギアの一種であり、エーテルでできた刃物を作り出すことができる。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b134910-s5J23uA2Jkow.png', NULL, NULL, '青木志貴', NULL, 134910, 'MAIN', 608) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022465', 'AN1985', 'マザー', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b139880-85yM6yUIRpYE.png', NULL, NULL, '井上喜久子', NULL, 139880, 'SUPPORTING', 30) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022466', 'AN1985', 'ジェシー', '彼は銀河情報局のエージェントであり、エルシー・クリムゾンの乗組員に潜入していた。その後、エルシーは彼の正体を知っていたことを認め、彼を船から追い出した。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b191297-HtPutBSZOkOM.png', NULL, NULL, '村井雄治', NULL, 191297, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022467', 'AN1985', 'ジャスティス', '彼は星間連合軍の隊員である。また、コマンドー・キャリア「エンジェル・フェザー」の指揮官であり、「オラシオン・セイス・インターステラー」の一員でもある。彼の主な目的は、エルシー・クリムゾンを捕らえることである。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b191305-iuQmf5L3BjiA.png', NULL, NULL, '浪川大輔', NULL, 191305, 'SUPPORTING', 36) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022468', 'AN1985', 'ニパ', 'ニパは、ブルー・ガーデンで活動するチンピラ集団のリーダーだ。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b226281-wjEnP8LmmTbJ.png', NULL, NULL, '村上裕哉', NULL, 226281, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022469', 'AN1985', 'コパ', 'レベッカ・ブルーガーデンと共に拉致されたB-Cuber。自身のB-Cubeチャンネルでは、巨大なコアラと共演している。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b230783-QIGopigLMnta.png', NULL, NULL, '禰覇夏生', NULL, 230783, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022470', 'AN1985', 'コナー', '彼は「エデンズ・ワン」の船長であり、ジギーの命令に従っている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b191282-14qdpmAHEnaJ.jpg', NULL, NULL, '佐々健太', NULL, 191282, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022471', 'AN1985', 'マイクル', 'マイクルは、非常にシンプルなデザインの小さな機械です。頭は茶色で、大きくて卵形をしています。目が見える部分はなく、その代わりに2つのくぼんだ穴があり、首や手足は細く棒状です。先のとがった帽子と、金色の縞模様が入った緑色のマントを身に着けており、手には白い布製の手袋をはめています。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b171655-u9p2Jo5pmC7K.jpg', NULL, NULL, '山口智広', NULL, 171655, 'SUPPORTING', 27) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022472', 'AN1985', 'ベルマン', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b221265-WLysqQ8gmSyj.png', NULL, NULL, '梶川翔平', NULL, 221265, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022473', 'AN1985', 'ジン', 'ジンは、かつて「ローグ・オット」というチームに所属していたサイボーグである。彼の能力「ウィンド・レイジ」は、タイフォンのように風を操るエーテルギアの一種だ。ジンは妹のクリーネを大切に思っており、彼女に近づこうとする男は誰であれ嫌っている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b191286-ebRH6YSjrZO1.png', NULL, NULL, '新祐樹', NULL, 191286, 'SUPPORTING', 52) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022474', 'AN1985', 'ミトラ', 'ミトラは、グランベルにある数多くの機械のうちの1体だった。彼女はグランベル王国でバーを経営していた。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b226282-UxlUs3Chcj0t.png', NULL, NULL, '佐藤はな', NULL, 226282, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022475', 'AN1985', 'ノア・グレンフィールド', '彼はサクラ・コスモスの銀河情報局の局長である。現在は「ショーティング・スターライト」のギルドマスターとして潜入活動を行っている。彼のエーテルギアは「神の眼」と呼ばれ、それを使って人々の居場所を把握することができる。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b191298-xWsU3FW4QG75.jpg', NULL, NULL, '岡本信彦', NULL, 191298, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022476', 'AN1985', 'クラリス・レイヤ', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b139876-xPdng9muqE2P.png', NULL, NULL, '田村奈央', NULL, 139876, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022477', 'AN1985', 'シャオメイ', 'シャオメイは、予知能力を持つことから、冷静で真面目な性格であると同時に、知識も豊富であることが示されている。  彼女の予知能力では単一の結果を予測できないため、シャオメイは人々の戦いを観察することに興味を持っており、その興味は、彼女が明らかに興奮し、高揚するほどに高まっていることが示されている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b154654-qs8J69oXReZO.jpg', NULL, NULL, '井上ほの花', NULL, 154654, 'SUPPORTING', 83) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022478', 'AN1985', 'アニー', 'アニーはグランベルの機械の一体だった。彼女は王国内でレストランを経営していた。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b226283-AaiDhHjIk8Gx.png', NULL, NULL, '柴田芽衣', NULL, 226283, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022479', 'AN1985', 'スパイダー', '彼はサクラ・コスモスで悪名高いハッカーだった。また、オラシオン・セイス・ギャラクティカの「ドラッケン・ジョー」とも関係があった。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b191287-5dvFpMHNIquK.png', NULL, NULL, '橘龍丸', NULL, 191287, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022480', 'AN1985', 'マリア・スライム', '彼女は「ドラッケン・ジョー・クルー」の一員で、その名の通り、スペーススライムです。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b191290-onKjNVczADEj.jpg', NULL, NULL, '小坂井祐莉絵', NULL, 191290, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
