INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022482', 'AN1985', 'ラビリア・クリスティ', 'ラビリア・クリスティは、「シューティング・スターライト」ギルドに所属する冒険者であり、B-キューバーでもある。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b134911-SbUNoom8ipOR.png', NULL, NULL, '綾乃あゆみ', NULL, 134911, 'SUPPORTING', 53) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022483', 'AN1985', 'シビル', '彼はX442年に惑星ノーマで活動していた犯罪組織のリーダーである。後に、老いた姿や、X442年のシビルの年老いた姿として登場する。彼はドラッケン・ジョーのもとで、借金で身柄を差し出された奴隷として働いている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b191296-BJFHo53YrJqs.jpg', NULL, NULL, '青山穣', NULL, 191296, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022484', 'AN1985', 'ビクトリー', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b229592-jevuH6nJMnd6.png', NULL, NULL, '三瓶雄樹', NULL, 229592, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022485', 'AN1985', 'セス・アンダーソン', 'ロボットの体に収められた知性を持つコンピュータプログラムで、ドラッケン・ジョーのチームの一員として活動していた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b242732-w01A0wSPI96i.png', NULL, NULL, '中野泰佑', NULL, 242732, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022486', 'AN1985', 'ニノ', '彼は、あるドイツのYouTuberに影響を受けた人気のB-Cuberです。また、「Zaiten Three」の元メンバーでもあります。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b191279-M9RNRjrMsxEg.jpg', NULL, NULL, '後藤ヒロキ', NULL, 191279, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022487', 'AN1985', 'モスコ', 'モスコは、「エデンズ・ゼロ」号の船内での雑用を担当する機械であり、かつては「ローグ・オット」というチームに所属していた傭兵である。彼は相撲の名手で、相撲の技を駆使して戦う。シスターや小動物が好きだが、幽霊は嫌いだ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b170569-kADfZyUIep1k.jpg', NULL, NULL, '岩田光央', NULL, 170569, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022488', 'AN1985', 'Miyako', '彼女には自分の動画チャンネルがある', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b198022-ciKqTScc4EaC.png', NULL, NULL, '鎌倉有那', NULL, 198022, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022489', 'AN1985', 'アミラ', '彼女は銀河情報局のエージェントであり、誰かの姿に変身する能力を持っている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b191294-wKOZ787BSxyd.png', NULL, NULL, '佐藤恵', NULL, 191294, 'SUPPORTING', 19) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022490', 'AN1985', 'ジャガー', 'ジャガーは、星間連合軍の大佐であり、「オラシオン・セイス・インターステラー」の一員である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b242733-f4W8Kf4NSc9F.png', NULL, NULL, '斧アツシ', NULL, 242733, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
