INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022493', 'AN1985', 'バーナデッド', 'バーナデッドは、ノーマの薄暗い裏社会でウェイトレスとして働く、異星人のウサギの女性だ。彼女には、クロノファージに飲み込まれた後のノーマの外で暮らす、年上の同類がいる。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b226279-Qq1DGeIw5dFu.png', NULL, NULL, '櫻井浩美', NULL, 226279, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022494', 'AN1985', 'ガノフ', '「ローグ」チームに所属する傭兵が、プラネット・ブルーガーデンでB-キューバーたちを拉致する任務を任された。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b230779-NBi1PRDu9jS7.png', NULL, NULL, '田村真', NULL, 230779, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022495', 'AN1985', 'ドラッケン・ジョー', '彼は「オラシオン・セイス・ガラクティカ」の一員であり、「ベリアル・ゴア」の元所有者、そしてサクラ・コスモスの裏社会で最も悪名高い人物である。エレメント4は彼の指揮下にある。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b191301-3PFrJhM3PxxZ.jpg', NULL, NULL, '楠大典', NULL, 191301, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022496', 'AN1985', 'ディエゴ・レイエス', 'ディエゴ・レイエスはアンドロイドであり、かつてドラッケン・ジョーのチームに所属していた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b242734-uTTSiWd2s56q.png', NULL, NULL, '山口令悟', NULL, 242734, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022497', 'AN1985', 'ジョニー', 'ジョニーは、シキに気に入られていたロボットの一体で、シビルによっておもちゃのように扱われた末に捨てられた。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b248769-ayVGRBMPSvpS.jpg', NULL, NULL, '山口智広', NULL, 248769, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022498', 'AN1985', 'エルシー・クリムゾン', '「オラシオン・セイス・ガラクティカ」の一員であり、海賊船「スカル・フェアリー」の船長。自身の海賊団だけでなく、宇宙海賊の艦隊をも率いる。ジギーの旧友である。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b139878-9SgaJmFD18Gu.jpg', NULL, NULL, '大原さやか', NULL, 139878, 'SUPPORTING', 143) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022499', 'AN1985', 'イリーガ', '彼は、ギルストでB-キューバーたちを捕まえている犯罪者だ。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b191299-0T7PvCM11IXu.png', NULL, NULL, '木村雅史', NULL, 191299, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022500', 'AN1985', '城主', 'カステランは、年老いた王にそっくりな姿をした機械だった。彼は、背中にグランベル王国の紋章が刺繍された、毛皮の縁取りが施された濃い色のローブを身にまとっていた。 頭には、色とりどりの縞模様の王冠を戴いていた。彼は濃い口ひげとあごひげを生やし、両目の周りには歯車のような装飾が施されていた。戦闘に入ると、カステランはローブを脱ぎ捨て、中世の騎士の鎧に似たロボットの体を露わにした。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b171656-aTtQjxzN1boS.png', NULL, NULL, '辻親八', NULL, 171656, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022501', 'AN1985', 'カウチポ', 'レベッカ・ブルーガーデンと共に拉致されたB-Cubeのユーザー。彼女はB-Cubeで「フード」をテーマにした『モグモグチャンネル』を運営しており、そのコンテンツは食事を中心に展開されている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b230780-Vj3ygnUbvWXW.png', NULL, NULL, '新井里美', NULL, 230780, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022502', 'AN1985', 'ミュラー', 'ミュラーは、惑星ニュートン出身の反体制科学者であり、かつてミュラー王立研究所の所長を務めていた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b241774-8f3azwD3GaCo.png', NULL, NULL, '多田野曜平 ', NULL, 241774, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022503', 'AN1985', 'ヴァルキリー・ユナ', 'ヴァルキリーは、色黒でスレンダーな体型の女性で、長い赤色の髪をポニーテールに結んでいた。 彼女は非常に背が高く、他のシャイニング・スターたちよりも頭一つ抜けていた。身に着けていたのは、淡い色の体にぴったりとフィットした装甲バトルスーツで、緑色のガントレットとショルダーガード、そして胸元に「E1」と記された翼付きのボットを装着していた。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b170570-QmyPRLME5a6R.jpg', NULL, NULL, '沢城みゆき', NULL, 170570, 'SUPPORTING', 48) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022504', 'AN1985', 'ジギー', 'かつて「魔王」と呼ばれていたアンドロイド。彼はシキを育て上げ、友を作る大切さを教えた。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b139879-hMeEdrO2hTu1.jpg', NULL, NULL, '大塚芳忠', NULL, 139879, 'SUPPORTING', 55) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022505', 'AN1985', 'シスター', '彼女は傭兵部隊「ローグ・オット」を率いる機械であり、「フォー・シャイニング・スターズ」の一員であるシスター・アイヴリーになりすましていた。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b191289-EUABVSBrKAIA.jpg', NULL, NULL, '前田玲奈', NULL, 191289, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022506', 'AN1985', 'ジョン', 'ジョンはグランベルにある数多くの機械のうちの1台だった。彼はグランベル王国で仕立て屋を営んでいた。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b226280-lG3SxLqsOvVM.png', NULL, NULL, '佐久間元輝', NULL, 226280, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022507', 'AN1985', 'ミロン', 'レベッカ・ブルーガーデンと共に拉致されたB-Cuberの一人。彼女はB-Cubeのチャンネル「トッコTV」を運営しており、そこで自ら危険な状況に身を投じ、そこから脱出する様子を、完全に台本通りに撮影したサスペンス動画を制作している。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b230782-LPBakIXYoaUU.png', NULL, NULL, '佐藤恵', NULL, 230782, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022508', 'AN1985', 'クレナイ・コウゲツ', '彼女は「サン・ジュエル」の元リーダーであり、小月ほむらの母親である。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b191283-gMU8UWSoFy9r.jpg', NULL, NULL, '園崎未恵', NULL, 191283, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022509', 'AN1986', '志田黒羽', 'スエハルの幼なじみ。スエハルの隣に住んでおり、4人姉妹の長女である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b190905-6Vxdf5eThmiL.png', NULL, NULL, '水瀬いのり', NULL, 190905, 'MAIN', 428) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022510', 'AN1986', '桃坂真理愛', 'かつてスエハルと共演した有名な子役。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b190906-fXQVE6077Ip2.png', NULL, NULL, '大西沙織', NULL, 190906, 'MAIN', 118) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022511', 'AN1986', '丸末晴', '丸末晴はもともと非常に有名な子役であり、母親もまた子役だった。 しかし、母親は感情表現が苦手だったため、あまり有名にはなれなかった。彼女は、息子自身が自分と息子自身の両方のために素晴らしい俳優になれるよう、彼を支え続けた。彼は可知白草が好きで、彼女のファンでもある。志田黒羽は、末晴の幼なじみである。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b190907-kbVakJ7svLeT.png', NULL, NULL, '松岡禎丞', NULL, 190907, 'MAIN', 80) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022512', 'AN1986', '可知白草', 'その驚くべき作品により、ごく若い年齢で著名な賞を受賞した児童文学作家。彼女はスエハルの初恋の相手である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b190908-DCdudmFwwvuD.png', NULL, NULL, '佐倉綾音', NULL, 190908, 'MAIN', 370) ON CONFLICT DO NOTHING;
