INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022523', 'AN1987', 'ルイス・ジェームズ・モリアーティ', '出身地：イースト・エンド。ウィリアムの弟。幼い頃は病気がちだったが、モリアーティ家に引き取られてから治療を受けた。ロイスは貴族であるにもかかわらず、しばしば一家の執事役を務めている。', 23, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b151488-73KDsEi7BJGl.png', NULL, NULL, '小林千晃', 183, 151488, 'MAIN', 784) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022524', 'AN1987', 'アルバート・ジェームズ・モリアーティ', '出身地：ロンドン　モリアーティ家の長男。', 27, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b151489-luCWYq86nKc2.png', NULL, NULL, '佐藤拓也', 188, 151489, 'MAIN', 938) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022525', 'AN1987', 'シャーロック・ホームズ', '出身地：ヨークシャー州ノース・ライディング。彼はモリアーティの敵役であり、モリアーティの計画の中心となる人物でもある。 パズルを好み、バイオリンを弾き、並外れた観察力を持ち、白兵戦にも精通しており、欲しいものがあればマキャベリ的な態度をとる。彼は探偵コンサルタントであり、モリアーティ本人と知的に互角のライバルと見なすことができる。', 24, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b151495-MQz2Bntpg1sO.png', '1月6日', NULL, '古川慎', 185, 151495, 'MAIN', 2296) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022526', 'AN1987', 'ウィリアム・ジェームズ・モリアーティ', '出身地：イースト・エンド　貴族であり、数学の教授であり、この漫画のアンチヒーロー的な主人公。彼は天才であり、悪しき貴族たちを打倒し、民衆に苦しみと痛みをもたらしてきた階級制度を打ち壊そうとしている。', 24, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b151486-rAFZZZm0Byu0.png', '4月1日', NULL, '斉藤壮馬', 185, 151486, 'MAIN', 4923) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022527', 'AN1987', 'ハドソン', 'ホームズとワトソンが住んでいる221Bの女主人。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b151487-t2SS10P0l5GT.png', NULL, NULL, '阿澄佳奈', NULL, 151487, 'SUPPORTING', 64) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022528', 'AN1987', 'アータートン', 'スコットランド・ヤードの警視総監', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b203383-Zf3RiVAbVkgM.png', NULL, NULL, '山路和弘', NULL, 203383, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022529', 'AN1987', 'Gosling', '彼はミルバートン社に勤めている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b208351-GzZ8XgPfisbr.png', NULL, NULL, '虎島貴明', NULL, 208351, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022530', 'AN1987', 'グレゴリー レストレード', 'グレゴリー・レストレードは新宿警察の警部であり、シャーロックの捜査をしばしば支援している。 シャーロック・ホームズの無謀な行動にしばしば苛立ちを覚えるものの、彼はシャーロックを深く信頼しており、状況が絶望的に見えても彼を信じ続けることが多い。同僚の警察官たちは人命を軽視しがちだが、彼は他者の安全を何よりも重視する、はるかに高い道徳観を持っている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b196059-qoGSKnuATk6X.jpg', NULL, NULL, '小松史法', NULL, 196059, 'SUPPORTING', 21) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022531', 'AN1987', 'チャールズ・オーガスタス・ミルヴァートン', 'チャールズ・オーガスタス・ミルバートンは、ロンドンで対立を煽ろうとするメディア王であり、ウィリアム・ジェームズ・モリアーティとシャーロック・ホームズの双方から敵視されている。彼は人々を脅迫することで知られている。（出典：Moriarty the Patriot Wikia）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b203142-lcerGiYopdSq.png', NULL, NULL, '野島健児', NULL, 203142, 'SUPPORTING', 25) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022532', 'AN1987', 'マイクロフト・ホームズ', 'マイクロフトはロンドン軍事局の局長であり、シャーロック・ホームズの兄である。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b151492-JHwmy6E995na.png', NULL, NULL, '安元洋貴', NULL, 151492, 'SUPPORTING', 157) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022533', 'AN1987', 'セバスチャン・モラン', 'アフガニスタン戦争中に戦死（KIA）と認定された元陸軍兵士だが、現在はモリアーティ兄弟と行動を共にしている。 彼は卓越した狙撃手で、しばしば単独行動をとる。外見は自信満々で魅力的な人物だが、軍務経験による深刻な心的外傷に密かに苦しんでいる。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b151490-cxIe19kBnHcs.png', NULL, NULL, '日野聡', NULL, 151490, 'SUPPORTING', 709) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022534', 'AN1987', 'フレッド・ポーロック', 'モリアーティ兄弟の一員である、物静かだが腕の立つ武術家。自ら話しかけられない限りほとんど口を開かないが、心根は優しく、スパイ活動や変装にも長けている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b151491-ND6O87myBETP.png', NULL, NULL, '上村祐翔', NULL, 151491, 'SUPPORTING', 286) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022535', 'AN1987', 'ジャック・レンフィールド', 'アフガニスタン戦争での戦闘中に多くの命を奪ったことから、かつて「ジャック・ザ・リッパー」として知られていた。その後、モリアーティ兄弟やセバスチャン、フレッドから依頼を受け、自身の卓越した戦闘技術を彼らに伝授した。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b151493-ZWe0dXiamoPn.png', NULL, NULL, '内田直哉', NULL, 151493, 'SUPPORTING', 49) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022536', 'AN1987', 'バクスター', '彼は子爵だ。ウィリアム・ヨンが訴訟を起こした貴族のことだ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b206289-RmYV3caTykv2.png', NULL, NULL, '松風雅也', NULL, 206289, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022537', 'AN1987', 'ザック・パターソン', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b196874-FFAPXRBu7ptC.jpg', NULL, NULL, '川島得愛', NULL, 196874, 'SUPPORTING', 16) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022538', 'AN1987', 'アダム・ホワイトリー', '彼は下院に所属する国会議員である。強い正義感を持ち、平等を信条としている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b207595-n7cQjRPP1ESt.jpg', NULL, NULL, '武内駿輔', NULL, 207595, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022539', 'AN1987', 'ジョン・H・ワトソン', 'ジョン・H・ワトソンは医師であり、シャーロック・ホームズの新しいルームメイトでもある。彼はアフガニスタンから帰還した元軍人だ。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b151496-1aCcxynt5xoU.png', NULL, NULL, '小野友樹', NULL, 151496, 'SUPPORTING', 179) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022540', 'AN1987', 'フォン・ヘルダー', '彼は武器の専門家だ。', 33, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b196268-UZ08tuHY5AaK.png', '6月30日', NULL, '鳥海浩輔', NULL, 196268, 'SUPPORTING', 114) ON CONFLICT DO NOTHING;
