INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022543', 'AN1987', 'アイリーン・アドラー', 'アイリーン・アドラーは、かつて舞台女優でありプリマドンナだったが、後に引退した。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b151494-Dk4hwJqilsw6.png', '9月3日', NULL, '日笠陽子', NULL, 151494, 'SUPPORTING', 454) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022544', 'AN1987', 'ウィギンズ', 'ウィギンズは、ストリートチルドレンのリーダー的存在である、抜け目のない少年だ。彼はしばしば、シャーロック・ホームズの頼もしい味方となる。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b196062-7e11JSHWOuSa.png', NULL, NULL, '榊原優希', NULL, 196062, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022545', 'AN1987', 'Harry', '彼はミルバートン社に勤めている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b208350-1pbE3ED821sD.png', NULL, NULL, '長谷川芳明', NULL, 208350, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022546', 'AN1988', '如月玲於奈', 'レオナは、閑古鳥が鳴くゲームショップ「キサラギ」の店長だ。透き通るような銀色の髪と抜群のファッションセンスを持つ美しい女性だが、結城宏にVRMMORPG『キワメクエスト』を強引に売りつけている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b198454-1d3NK3g0jWZh.jpg', NULL, NULL, '竹達彩奈', NULL, 198454, 'MAIN', 303) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022547', 'AN1988', '結城宏', 'プレイヤー名「Hiro」こと結城宏は、VR MMORPGをこよなく愛する高校生だ。ゲームショップの店長・如月玲於奈に無理やり『キワメクエスト』というゲームを買わされた彼は、やがてそのゲームが表向きとは全く異なるものであることに気づく。 普通のゲームとは異なり、このゲームは狂信的なほどリアリズムを追求している。そのため、ヒロシは自分の居場所を見つけるのに苦労する。その過程で、彼は自分から何かを求めようとする多くの少女たちと出会うことになる。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b198451-xSOZGoB5eLzL.png', NULL, NULL, '山下大輝', NULL, 198451, 'MAIN', 70) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022548', 'AN1988', 'アリシア', '彼女は『キワメ・クエスト』に登場するマーチンの妹であり、ヒロの幼なじみだった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b198453-oRRHTFmAknum.png', NULL, NULL, 'ファイルーズあい', NULL, 198453, 'SUPPORTING', 112) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022549', 'AN1988', '神居宗一郎', 'Soichirou is a young city councilor with a promising future. He used to be an extremely skilled full-dive RPG gamer and he is the only player to have conquered the "Kiwame Quest". His player name is Kamui (カムイ).', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b210905-z1ZBSiTiuMgn.png', NULL, NULL, '松岡禎丞', NULL, 210905, 'SUPPORTING', 33) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022550', 'AN1988', 'ガバン', '『キワメ・クエスト』に登場するテッド市の女王兼摂政。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b228677-mnOCHkJSnHXL.png', NULL, NULL, '伊藤静', NULL, 228677, 'SUPPORTING', 14) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022551', 'AN1988', '結城楓', '現実の世界では、カエデはヒロシの妹です。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b198456-N5eHRlJYjDGd.png', NULL, NULL, '古賀葵', NULL, 198456, 'SUPPORTING', 50) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022552', 'AN1988', 'ボブ', 'ボブはテッド市の兵士です。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b276410-EQFkhpkjFxsl.jpg', NULL, NULL, '梶原岳人', NULL, 276410, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022553', 'AN1988', 'マーチン', '彼は『キワメ・クエスト』でヒロシの親友であり、リンゴ農園で農家として働いていた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b198452-fAdSIGPpqs7d.png', NULL, NULL, '石谷春貴', NULL, 198452, 'SUPPORTING', 22) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022554', 'AN1988', 'ミザリサ', '彼女はテッド市で審問官として働いている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b198455-fetOhrgr5JBk.png', NULL, NULL, '井澤詩織', NULL, 198455, 'SUPPORTING', 146) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022555', 'AN1988', 'ギンジ', 'ギンジは、「キワメクエスト」において数少ない本物のプレイヤーの一人だ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b210903-dKpSkUDpd63H.png', NULL, NULL, '小西克幸', NULL, 210903, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022556', 'AN1988', 'テスラ', 'Tesla is one of the most powerful NPCs in "Kiwame Quest". He is the captain of the town guard in Ted and his nickname is "Thunder Tesla" (雷鳴のテスラ, Raimei no Tesura).', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b210904-xXmRQkCZa0M6.png', NULL, NULL, '日野聡', NULL, 210904, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022557', 'AN1989', 'リゼルグ・ダイゼル', '種族：人間／シャーマン　ハオによって両親を殺された、イギリス出身のシャーマンであり、伝統的な「ダウザー」でもある。ライザーグは、いずれかの時点で主要な登場人物全員と劇的な関わりを持つことになり、彼らと長い間行動を共にするものの、物語の展開の中でヨウのチームと何度も対立することになる。    ライザーグは知的な天才だが、家族の殺害に対する復讐の念に目がくらんでいる。基本的には優しい心を持っているが、ややアンチヒーロー的な側面も持ち合わせている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b1529-bN2Nwx3VnePH.png', '5月17日', 'AB', '沢海陽子', NULL, 1529, 'MAIN', 80) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022558', 'AN1989', 'チョコラブ・マクダネル', 'ジョコは若い頃、雪の降るある夜、師匠であるオロナと出会った。オロナは、強盗に遭っている被害者の周りに集まった人だかりの中にいた。警察は強盗を包囲していたが、強盗は被害者を殺すと脅して周囲の人々を威嚇していた。 オロナは群衆の中から一歩踏み出し、警察に「彼にチャンスをくれ」と頼んだ。ジョコはそれをじっと見ていたが、気がつくと、強盗は腹を抱えて笑い転げ、警察に連行されていた。    漫画では、オロナと', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/15349.jpg', NULL, NULL, 'くまいもとこ', NULL, 15349, 'MAIN', 54) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022559', 'AN1989', 'ファウストⅧ世', 'ファウストは、悪魔と契約を結んだ初代ファウストの子孫である。『シャーマンキング』に登場する第8代ファウストは、エリザというたった一人の友人しかいない孤独な少年だった。しかし、エリザは不治の病を患っていたため、ファウストは治療法を見つけることに人生を捧げ、ついにそれを成し遂げた。 彼は医師となり、エリザの命を救い、彼女と結婚した。二人はドイツにある診療所で共に暮らしていたが、ある夜、強盗が押し入り、エリザを射殺してしまった。打ちひしがれたファウストは、先祖の黒魔術に手を染め、', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b3262-AKmdJOeUr3IJ.png', '4月8日', 'A', '子安武人', NULL, 3262, 'MAIN', 163) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022560', 'AN1989', 'ニクロム', 'ニクロムはパッチ族の第10代司祭であり、アニメでは第50話で初登場した。ニクロムは、前任の第10代司祭である兄のクロムがレンに殺された後、第10代司祭となった。 漫画版では、ニクロムはレンを倒すことに成功したが、レンは後にアイアン・メイデン・ジャンヌによって蘇生された。また、ニクロムはハオと手を組むことになる。多くのファンを驚かせたのはニクロムの年齢であり、パッチ族に加わったのは8歳の時だったと明かされている。 彼の精霊は（名前は明かされていない）サソリで、', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b20881-yQDgFXPeYmhb.jpg', '6月6日', NULL, '観世智顕', NULL, 20881, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022561', 'AN1989', 'ゾリャー・ガガーリク', '本名を持たないロシア人女性シャーマン（ロシアの女神にちなんで名付けられたと思われる）。ソ連崩壊前に実施された超能力実験によってその能力が目覚めた。彼女の守護霊はヴォディャノイであり、その力によって標的に水を放つことができるが、通常はその水はピノによって凍結される。 ズリアという名は、スラブ神話のゾリャ、アイスキャンディーの「ガリガリくん」、そしてユーリ・ガガーリンに由来している。（出典：ウィキペディア）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b35349-g7tVerM1Kn8P.png', '1月13日', NULL, '寺崎裕香', NULL, 35349, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022562', 'AN1989', '杉本良', '彼は「The BoZ Brothers」の一員である。彼らはハオの信奉者であり、ロック僧の集団である。彼は「土組」の一員だ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b231316-pOKc9rXEZpgM.png', NULL, NULL, '鈴木達央', NULL, 231316, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022563', 'AN1989', 'ピノ・グレアム', 'ピノ・グレアムは、アイルランド出身の「アイスマン」のリーダーである。彼が操る精霊はバドブというアイルランドのカラスの女神で、その力によって彼はあらゆるものを凍結させることができる。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b29629-mZpWtW8K07w3.png', NULL, NULL, '阪口周平', NULL, 29629, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022564', 'AN1989', 'ハンス・ライハイト', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b211862-YsLdLyR7uMjP.png', '3月13日', NULL, '佐久間元輝', NULL, 211862, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022565', 'AN1989', '乙破千代', '乙破千代は、後に朝倉ハオとして知られることになる孤児の朝羽童子をかつて世話していた、ウサギのような小さな妖怪である。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b289803-gJzq6dIc2QIa.jpg', NULL, NULL, '関智一', NULL, 289803, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022566', 'AN1989', '道潤', 'ジュンはタオ・レンの姉である。彼女は死体を蘇らせることのできる道士だ。 彼女の「jiangshi（守護ゾンビ、日本語では「キョンシー」）」は、17年前に亡くなったブルース・リーに似た有名なカンフー映画スター、リー・バイロン（アニメ版ではリー・パイロン）である。 以前は「賦符」を使ってリー・バイロンを操っていたが、麻倉葉や阿弥陀丸との戦いに敗れた後、霊にも心があり、単に操るだけではいけないことに気づく。ジュンは、バイロンに自分の命令に従わせることを許すのは、ただ', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b4327-9TUTipbSrMj5.png', '10月10日', 'A', '根谷美智子', NULL, 4327, 'SUPPORTING', 96) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022567', 'AN1989', 'ボリス・ツエペシユ・ドラキユラ', '彼は自分が吸血鬼だと主張しており、その祖先たちも吸血鬼と見なされ、そのせいで狩られていた。ハオに救われた彼は、人類への復讐を誓い、ハオの仲間に加わることを決意する。彼は自身のオーバーソル「ブラムロ」に血を注ぎ込み、翼の生えたマントを作り出す。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b20883-t72Smn9yeBxT.png', NULL, NULL, '置鮎龍太郎', NULL, 20883, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022568', 'AN1989', 'オパチョ', 'ハオの最も忠実な味方。ハオが彼女を見つけたとき、彼女は南アフリカで栄養失調の赤ん坊だった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b7147-iT879rQmJ3gC.png', '2月20日', NULL, '林原めぐみ', NULL, 7147, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022569', 'AN1989', 'ジョン・デンバット', 'X-Lawsの一員。イギリスのオックスフォード生まれで、かつてS.A.S.に所属していた。守護霊は大天使ラファエルである。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b20694-0YRCtKRckvcq.png', '9月4日', NULL, '小西克幸', NULL, 20694, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022570', 'AN1989', '米田善', '彼は「The BoZ Brothers」の一員である。彼らはハオの信奉者であり、ロック僧の集団である。彼は「土組」の一員だ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b231317-HyQU60b2lzZY.png', NULL, NULL, '谷山紀章', NULL, 231317, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022571', 'AN1989', 'トナ・パピク・カジマヒデ', '彼はアイスランドのアクラネス出身のシャーマンであり、「ザ・アイスマン」のメンバーである。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b220235-WWqJNBr7xikN.png', '4月26日', NULL, '石井康嗣', NULL, 220235, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022572', 'AN1989', 'バッファロー・リン', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b264934-nfyyhAwc8k2J.png', NULL, NULL, '観世智顕', NULL, 264934, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022573', 'AN1989', 'エリザ', 'エリザはファウストにとって最初で、唯一、そして真の愛でした。    彼女は幼少期から不治の病を患っていました。ファウスト8世の世話をした唯一の女性として、彼はその見返りとして、彼女を治すための治療法を見つけるべく、研究に没頭しました。 彼女が回復した後、二人は結婚し、共に診療所を開いた。彼女とファウストは、共に暮らす日々をとても幸せに過ごしていた……しかし、ある時、自宅に侵入者が現れ、銃を持ったその侵入者が、当時診療所に一人きりだったエリザを殺害してしまった。今、彼女はファウストの主たる精霊となっている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b18342-px8ldvBZYtKl.png', '6月29日', 'AB', '竹内佳菜子', NULL, 18342, 'SUPPORTING', 26) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022574', 'AN1989', 'マルコ・ラッソ', '彼はX-Lawsの実質的なリーダーであり、アイアン・メイデン・ジャンヌにのみ決定を覆される。出身はイタリアのシチリア島である。 幼くして両親を亡くしたマルコは、カトリック教会の孤児院で司祭に育てられた。ジャンヌやリゼルグ・ダイゼルと共に、チーム「X-I」の一員である。  他のX-Lawsのメンバーと同様、マルコはジャンヌに対して極めて忠実であり、腐敗や悪のない世界というジャンヌの理想を実現するためなら、いかなる手段も厭わない。ジャンヌと同様、彼は物事を', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b7144-8Ln6amzy2F6X.png', '11月17日', NULL, '中村悠一', NULL, 7144, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022575', 'AN1989', '碓氷ピリカ', 'ホロホロの妹で、アンナがヨウを鍛えたのと同じような方法で彼を鍛えている。漫画やアニメでは描かれていないが、作者によれば、ピリカのパートナー精霊は「トラーラ」であり、アイヌ語で「マリモ」または「トラーサンペ」と呼ばれるものである。 トララは幼い頃、ピリカが溺れそうになったところを救ったと言われており、それ以来、二人はパートナーとなった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b15558-Y4VFe3VLXi91.png', '2月9日', NULL, '日高里菜', NULL, 15558, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022576', 'AN1989', 'ケビン・メンデル', 'スピリット：レミエル（300SL コープ） フューリョク：9,700 出身：オーストリア    コブラ部隊の元メンバーで、ハオへの復讐を誓っている。シャーマンファイトの10年前にハオに「火の精霊」で焼かれ、顔に傷を負ったため、その傷を隠すために仮面を被っている。 セビンは、人間の前腕に似た特製の銃でレミエルを攻撃する。その名は、タバコブランド「キャビン」とグレゴール・メンデルに由来する。趣味は合唱団での歌唱で、好きな食べ物はザッハトルテである。   (出典：ウィキペディア)', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b20696-cPmZ4Y9BEwZi.jpg', '9月18日', NULL, '高木渉', NULL, 20696, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022577', 'AN1989', 'ダマヤジ', 'ハオの信者の一人。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b236245-2PZakHi8x0pE.png', '10月31日', NULL, '高口公介', NULL, 236245, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
