INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022579', 'AN1989', 'マグナ', 'マグナは「テン・パッチ・プリースト」の一人であり、「ハナ組」、「ホシ組」、「マジカル・プリンセス」の各チームを統括するパッチ・オフィシアンです。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b289802-qu7W4hP41a47.jpg', NULL, NULL, '山口恵', NULL, 289802, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022580', 'AN1989', 'ナクト・ピトラ', 'ナクトは「ナイルズ」チームの一員です。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b289806-AuMiMw3QqxkC.jpg', NULL, NULL, '坂田将吾', NULL, 289806, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022581', 'AN1989', 'ミイネ・モンゴメリー', 'カナダ特殊部隊の元隊員であり、アイアン・メイデン・ジャンヌを除けば、そのグループで唯一の女性メンバーである。 アニメ版では、彼女は見た目以上に繊細な一面を見せ、幻滅したライゼルグに「モルフイン」を返還する。これは、生き残ったX-Lawsのメンバーたちがハオを倒そうとする中、彼がそのグループを離れ、他のメンバーのように破滅することのないよう願ってのことだった。 しかし、漫画版では、彼女はチームX-IIIのメンバーの中で最初にハオに殺害される。ミーネはガブリエルをルガーP08拳銃の中に封じ込めている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b20409-z5mSfRV8NJaC.png', '1月26日', 'A', '永井真里子', NULL, 20409, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022582', 'AN1989', 'マタムネ', 'マタムネは、漫画『シャーマンキング』に登場するキャラクターです。第19巻と第20巻に登場するマタムネは、アニメ版『シャーマンキング』には登場しません。 マタムネは、二本の尾を持つ猫の精霊「ネコマタ」であり、常にパイプを持ち歩き、3本の熊の爪がついたネックレスを身につけている（このネックレスは後に麻倉葉が所有することになる）。 彼は千年もの間、朝倉家に仕えてきたが、その時間の多くは世界を旅して過ごしている。彼は「あらゆるものを見てきた」と公言しており、ほぼ常に本を読んでいる。    fro', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b19120-Q2R9JdA8tGiC.png', NULL, NULL, '田中秀幸', NULL, 19120, 'SUPPORTING', 68) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022583', 'AN1989', 'ラジム', 'ラジムは、このトーナメントの司会者に選ばれた審判員である。他のほとんどの審判員とは異なり、彼は中立を保つよう最善を尽くしているが、時にはハオの「シャーマンだけの王国」を認めていないことを公然と認めることもある（X-IIIとの戦いでは、ハオの「フューリョク」評価まで入手するほどである）。彼の精霊はオーストラリア産のペリカンである。（X-IIIとの戦いの最中には、ハオの「フューリョク」のランクを調べてしまうほどだった）。彼の精霊は「プラチナ・ソード」という名のオーストラリアのペリカンで、媒体はマイクである。彼の「植物」は湖である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/21129.jpg', '2月25日', NULL, '間宮康弘', NULL, 21129, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022584', 'AN1989', 'ブロッケン・マイヤー', '理由は明かされていないが、彼は体の大部分を失い、今や残された体はフード付きのローブをまとったレゴのような姿となっている。このため、彼の「気力」は大幅に上昇し、数々の戦いを生き延びている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b20880-O4gnAaEJmIim.png', '8月30日', NULL, '吉野裕行', NULL, 20880, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022585', 'AN1989', '道円', 'タオ・ユアンはタオ・レンの父である。彼は、屍（ジャンシー）の軍団を率いる強力なシャーマンだ。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/20884.jpg', '11月30日', 'A', '手塚秀彰', NULL, 20884, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022586', 'AN1989', 'Mr.リトル・レイク', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b232587-dBqeGWxKjZ8Z.png', NULL, NULL, '坂田将吾', NULL, 232587, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022587', 'AN1989', 'サティ・サイガン', 'サティ・サイガンは、「シャーマン・ファイト」の三大勢力の一つであるガンダーラ・グループのリーダーである。また、チーム「ニョライ」のチームリーダーでもある。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b230800-KuQWXV7Sa6sF.jpg', '12月31日', NULL, '三石琴乃', NULL, 230800, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022588', 'AN1989', 'アナテル・ポッキ', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b264936-symgW5Gi0Vi8.png', NULL, NULL, '遊佐浩二', NULL, 264936, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022589', 'AN1989', 'ブロン', 'ブロンは「テン・パッチ・プリースト」の一人であり、リゼルグ・ダイゼルを統括し、X-Lawsチームを監督する司式者である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b289805-0PkzPcSez0gk.png', NULL, NULL, '斉藤次郎', NULL, 289805, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022590', 'AN1989', 'ハン・ザンチン', 'ハン・ザンチン 彼に関する情報はあまりなく、若い頃はポップアイドルを志していたこと、そして爆発物の専門家であることくらいしかわかっていない。数々の戦闘に何度も登場し、ペヨーテの反乱によって最初に殺されたが、後にハナグミと共に蘇生した。 フューリョク：7,000 1966年3月16日生まれ 出身地：中国・上海  ハン・ザンチン・スピリット ハン・ザンチンのスピリットは「シオン・シオン」という名だ。 彼のオーバーソルにより、シオン・シオンは中国風の鑼（ゴング）へと姿を変え、「オーバーソル・ドクラマネコ」を形成する。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b20879-F9k3xOz6bere.png', '3月16日', NULL, '最上嗣生', NULL, 20879, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022591', 'AN1989', 'ラキスト・ラッソ', '出身：イタリア・シチリア島　X-lawsの創設者であり元リーダーであるルチストは、ハオの下で活動するシャーマンの中でも群を抜いて強力な一人である。ルチストはマルコの最大のライバルとして振る舞っている。どうやら、二人は前世では親しい友人だったようで、かつては共に自動車販売業者だった。 しかし、ハオが介入したことで、この仲間たちの人生は永遠に変わってしまうこととなった。  ルチストの精霊  「堕天使」ルシファー。他の大天使たちと同様、ソルを粉砕することができ、どうやら検知されない速度で移動することも可能なようだ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/20855.jpg', '6月1日', NULL, '松田健一郎', NULL, 20855, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022592', 'AN1989', 'ターバイン', 'ターバイン（Turbine）はアラビア風の衣装を身にまとっている。彼は高位の配下の一人のようで、非常に忠実であるようだ。通常、ヨウの仲間たちに対して度重なる攻撃を仕掛ける際には、同輩たちのリーダーを務めている。 その後、ペヨーテとの戦いの最中に、田村崎緑（小山田万純の主要な手下）によって殺害される。彼とペヨーテは、ハオの手下の中で、遺体が修復不可能なほど損傷していたため、復活さえも叶わなかった唯一の二人であった。 戦闘力：6,500　出身：イラク　タービンの', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b20857-UYYwSC9jTWft.png', NULL, NULL, '勝杏里', NULL, 20857, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022593', 'AN1989', 'ミック', 'チョコラブの精霊の仲間であるジャガーの精霊。かつてはチョコラブの師匠のもとにいた。チョコラブによると、彼は鼻ですべての匂いを嗅ぎ分け、目ですべてを見通し、爪ですべてを捕らえることができるという。    『シャーマンキング』ウィキより', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/20406.jpg', NULL, NULL, NULL, NULL, 20406, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022594', 'AN1989', 'コロロ', 'Kororo (Corey in the english anime) is the spirit ally of Usui Horokeu, nicknamed Horohoro.   Kororo is a Koropokkoru (which means "little people under butterbur leaves" in Ainu, and is surprisingly cute. (Known as Minutians in the English anime), and Horohoro''s spirit ally. She has a crush on Manta Oyamada, even though he is human. Her name in the English anime version sounds similar to "Kōri" (氷), which is the Japanese word for ice and also the element that Horohoro''s attacks are based on.  (S', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b20242-5dmroZvjGhMe.png', NULL, NULL, '中島愛', NULL, 20242, 'SUPPORTING', 19) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022595', 'AN1989', 'クリス・ブンスター', '彼はX-Lawsのメンバーであり、チーム「X-III」の一員であると同時に、そのチームリーダーも務めている。かつては軍に所属し、中東でテロリストと戦っていた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b243192-fgtizVQRW5Zh.png', '5月6日', NULL, '最上嗣生', NULL, 243192, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022596', 'AN1989', 'オロナ', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b264939-cC9RkAlWcYj1.png', NULL, NULL, '土師孝也', NULL, 264939, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022597', 'AN1989', '李白竜', '『ホワイト・ドラゴン』：リー・パイロンは、タオ一族によって殺害され、ジュンの Jiang-si 護衛となったカンフー映画スターである。彼は、不審な状況下で亡くなったブルース・リーをほのめかした存在である。 厳密に言えば、彼は霊ではなく、タオ・ジュンの「御札」によって蘇生させられた生ける屍である。 しかし、彼はタオ・ジュンに仕え、常に彼女のそばに付き添っているため、同様の役割を果たしていると言える。英語版のアニメでは、リー・パイロンとして知られている。パイロンはNで生まれた。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b20240-nEEEQcCdoqE9.png', NULL, NULL, '櫻井トオル', NULL, 20240, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022598', 'AN1989', '麻倉木乃', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/61457.jpg', '3月24日', NULL, '京田尚子', NULL, 61457, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022599', 'AN1989', 'リリララ', 'リリララはアニメと漫画の両方に登場します。セミノア族の一員であるリリララは、パッチ族に対して怒りを抱いており、パッチ族が自分の先祖を虐殺したと信じています。     彼女は、現在の「シャーマンファイト」に参加しているシャーマンたちがパッチ村に到達するのを阻止しようと試み、パッチ族は実のところ殺人者であり、セミノア族が遭ったのと同じ運命が彼らにも降りかかると警告する。その後、朝倉ハオは、セミノア族を殺したのはパッチ族ではなく、自分だったことを明かす。 漫画版では、ハオがリリララを殺害する。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b20421-hu9rQKAiZQlg.png', '10月26日', NULL, '小山茉美', NULL, 20421, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022600', 'AN1989', 'ドル・バートン', '彼はハオの手下の中で最もタフなメンバーだが、最強ではない。かなり巨体で、フットボール選手でもあるシャーマンであり、X-Lawsを攻撃するが、彼らの大天使たちに阻止される。 ヨウがX-Lawsによる彼へのとどめを阻止すると、彼はその恩返しとして、パッチ村への残りの道案内をしてくれる。その後、ヨウのチームに敗れたアイスマンズを壊滅させようと再び現れるが、ホロホロが割って入る。 ホロホロの父親もふらりと現れ、ビルはホロホロを殺そうと向かうが、', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b20856-DCKnJoYa1noh.png', NULL, NULL, '貴弘藤原', NULL, 20856, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022601', 'AN1989', 'ペヨーテ・ディアス', 'フューリョク：3,000　ペヨーテ（英語版アニメではラミロ）は、漫画の第115話あたりで初登場するメキシコのシャーマンである。彼は自身の精霊であるカルロスとフアンを使って、BoZに憑依する。 彼は自身のマリアッチの精霊を、メキシコで死を象徴するスケルトンの人形と融合させる。レンの攻撃によって敗北するが、その後、レンとの再戦において彼を殺害することに成功する。彼の最後の登場は、かなり後のことであり、幻滅してハオを裏切り、仲間を殺害した際であった。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b17219-yPRSMGt3LaxU.png', NULL, NULL, '真殿光昭', NULL, 17219, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022602', 'AN1989', 'ラーキ・ディラック', '彼は「X-Laws」およびチーム「X-II」のメンバーであり、かつては米軍デルタフォースに所属していた。彼の守護霊は大天使ウリエルである。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b243194-RKJ7wGWw74w8.png', '10月13日', NULL, '高口公介', NULL, 243194, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
