INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022605', 'AN1989', 'ナマリ', 'ナマリは、シャーマンファイトを監督する「テン・パッチ・プリースト」の一人であり、ガンダーラ勢とチーム「ツチ組」の監督を務めるパッチ・オフィシアンである。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b289810-9v3pVg1JHq0S.jpg', NULL, NULL, '梶川翔平', NULL, 289810, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022606', 'AN1989', '麻倉幹久', '麻倉幹久は、漫画およびアニメシリーズ『シャーマンキング』の主人公・麻倉葉の父親である。漫画では、レッドセブやセイラムと共に「チーム・カバラーズ」に所属していた。彼にはタヌキとキツネの2体の精霊が宿っており、オーバーソルズは石を媒体として利用している。  「シャーマンファイト」大会における幹久の役割は、ヨウを見守ることである。彼はしばしば影に身を潜め、木の上からヨウの戦いを観察している姿が見られる。また、彼はヨウに教えを授ける責任も担っており、', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b20829-2sXUfG4xb6iQ.png', NULL, NULL, '堀内賢雄', NULL, 20829, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022607', 'AN1989', 'アイアン・メイデン・ジャンヌ', 'フランス出身の11歳の少女であり、それ自体が強力なシャーマンでもあるジャンヌは、「X-Laws」のリーダーである。「アイアン・メイデン」という称号は、死の淵に近い状態を維持することで力を高めるため、ほぼすべての時間をアイアン・メイデンの中で過ごしていることに由来する。 彼女は、自分の苦しみこそが世界に正義をもたらすと信じ、どうしても必要とされない限り、めったにそこから出ることはない。しかし、彼女のアイアンメイデンは押しつぶされ、おそらく修復不可能な状態になってしまった。彼女は赤い瞳と、極めて青白い肌で知られている。', 11, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b7137-6AIWqXeyoLd5.png', '3月2日', 'AB', '堀江由衣', NULL, 7137, 'SUPPORTING', 60) ON CONFLICT DO NOTHING;
