INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022610', 'AN1989', 'ポーフ・グリフイス', 'X-Lawsおよびチーム「X-II」の一員であるポルフは、他のX-Lawsのメンバーと同様、朝倉ハオの手によって何らかの形で苦しめられてきた。かつては米軍のデルタフォースに所属していた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b243193-lkDWWOpbbesw.png', NULL, NULL, '宮園拓夢', NULL, 243193, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
