INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022613', 'AN1989', 'カフラー・プリツ', 'カフレは「ナイルズ」チームの一員だ。アナテルは彼を史上最高の防腐処理師だと評価している。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b289807-RkjRrgar5eSU.jpg', NULL, NULL, '田邊幸輔', NULL, 289807, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022614', 'AN1989', 'モルフイン', 'リゼルグ・ダイゼルの家系で代々受け継がれてきた精霊。漫画ではリゼルグのメインの精霊だが、彼はより強力な精霊ゼルエルを求めて彼女を見捨てる。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/9147.jpg', NULL, NULL, NULL, NULL, 9147, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022615', 'AN1989', 'シルバ', '「オラクル・ベル」を製作するシャーマンの部族「パッチ族」の一員。この「オラクル・ベル」は、神々との通信手段として用いられる。 彼は、朝倉ヨウ、「ウォデンソード」リュウ、そしてクロムの死後はタオ・レンをも監督する、パッチの司祭である。 戦いが規則に従って行われているかを確認するために単に戦いを監督するだけのパッチの司祭たちとは異なり、シルバは、戦いが引き起こす大規模な死の連鎖を避けるために、パッチの司祭たちは戦いにさらに積極的に介入すべきだと考えている。   S', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b7145-uqeaVUShhlZ6.png', NULL, NULL, '緑川光', NULL, 7145, 'SUPPORTING', 33) ON CONFLICT DO NOTHING;
