INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022619', 'AN1989', '麻ノ葉', '麻ノ葉は、後に朝倉ハオとして知られることになる堂地朝ハの母親である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b289801-grEPpjlEsHtS.jpg', NULL, NULL, NULL, NULL, 289801, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022620', 'AN1990', 'アルベルト・ホーク', '彼は第三騎士団の団長である。その冷徹な物腰から、「氷の騎士」というあだ名で呼ばれている。小鳥遊聖に致命傷から救われたことをきっかけに、彼女の味方となった。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b188170-poMRW0FjHomE.png', NULL, NULL, '櫻井孝宏', NULL, 188170, 'MAIN', 257) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022621', 'AN1990', 'ヨハン・ヴァルデック', '彼は薬用植物研究所の所長であり、コント・バルデック氏の次男である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b188171-uCu8ZrHrF2eY.png', NULL, NULL, '江口拓也', NULL, 188171, 'MAIN', 54) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022622', 'AN1990', 'ユーリ・ドレヴェス', '彼は王立魔術師評議会の大魔術師である。彼の関心は、魔法や魔力に関する研究にのみ向けられている。外見は陽気で情熱的に見えるが、内面はまったく別人のようだ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b188172-6hy90e0EMw7d.png', NULL, NULL, '小林裕介', NULL, 188172, 'MAIN', 164) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022623', 'AN1990', '小鳥遊聖', '小鳥遊聖は、「聖者召喚の儀式」によって召喚された20代のOLである。 彼女の聖なる力は能力を50％向上させるが、その外見ゆえに当初は聖人として認定されなかった。研究中にうっかり騒ぎを起こしてしまったことで、一時は「聖人」として親しまれそうになったが、その実力を目の当たりにされた後、ついに正式に聖人として認められた。余暇には料理や化粧品作りを楽しむ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b188173-jITKX4tsmDDU.png', NULL, NULL, '石川由依', NULL, 188173, 'MAIN', 363) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022624', 'AN1990', 'ジュード', '彼はヨハン・ヴァルデックと同じ薬用植物研究所の研究員であり、小鳥遊聖の指導を担当している。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b188174-6WRL8JPlNnd3.png', NULL, NULL, '八代拓', NULL, 188174, 'MAIN', 79) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022625', 'AN1990', 'エリザベス・アシュレイ', '彼女はアシュリー侯爵の娘であり、第一王子の婚約者である。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b210993-xiyG4LuBIzE9.png', NULL, NULL, '上田麗奈', NULL, 210993, 'SUPPORTING', 52) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022626', 'AN1990', 'レオンハルト', 'レオンハルトはコリンナの孫であり、クラウスナー卿の領地内でミアズマやモンスターの脅威を排除する任務を負った傭兵部隊の隊長である。彼はその率直すぎる物言いのせいで、祖母から頻繁に叱られる。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b245649-mzelqtk8PyZz.png', NULL, NULL, '日野聡', NULL, 245649, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022627', 'AN1990', 'ジークフリート・スランタニア', '彼は王だ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b210997-RKAHiroc4QIA.jpg', NULL, NULL, '山野井仁', NULL, 210997, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022628', 'AN1990', 'コリンナ', 'クラウスナー領のポーション調合を担当する、非常に経験豊富な錬金術師。セイが「聖者の魔法」を解き放ち、使いこなせるようになるよう、かつての聖人が残した唯一の日記を彼女に見せて教える。また、孫のレオが口が悪く、気遣いに欠けることをよく叱る。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b245650-9epTVJOlLdWF.png', NULL, NULL, '小山茉美', NULL, 245650, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022629', 'AN1990', 'レイン・スランタニア', 'レインはスラントニアの第二王子であり、カイルの弟である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b210996-PWcg5gKkerFQ.jpg', NULL, NULL, '市川蒼', NULL, 210996, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
