INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022632', 'AN1990', 'ヴォルフ', '彼は騎士の一人だ。ある遠征で片腕を失ったが、セイがそれを治してくれた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b234772-ghenVh5v1fsg.png', NULL, NULL, '熊谷健太郎', NULL, 234772, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022633', 'AN1990', 'カイル・スランタニア', '彼は第一王子だ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b210998-e4Pf1Qj6ehph.png', NULL, NULL, '福山潤', NULL, 210998, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022634', 'AN1990', '御園愛良', '彼女もまた、聖女召喚の儀式によって召喚されたもう一人の少女だ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b210995-ceLm1FRlBVdG.png', NULL, NULL, '市ノ瀬加那', NULL, 210995, 'SUPPORTING', 34) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022635', 'AN1990', 'エアハルト・ホーク', '彼は副首席魔術師だ。また、アルバートの兄でもある。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b210994-mT9DQnxHpn7Y.png', NULL, NULL, '梅原裕一郎', NULL, 210994, 'SUPPORTING', 43) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022636', 'AN1990', 'Marie', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b238021-BSELCxCGNLTQ.png', NULL, NULL, '万沙子磯辺', NULL, 238021, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022637', 'AN1991', '源さくら', '没年：2008年4月7日　死因：アイドルのオーディションに向かう途中、ピックアップトラックと衝突して死亡　ゾンビになる前、サクラは特に目立ったところのないごく普通の少女だった。彼女は元気いっぱいの少女として描かれており、アイドルとして歌っているときはいつも情熱を燃やしていた。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b127540-H1wiC6lu34WT.jpg', '4月2日', NULL, '本渡楓', NULL, 127540, 'MAIN', 833) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022638', 'AN1991', '水野愛', '没：2008年8月4日　彼女は2000年代初頭、アイドルグループ「アイアン・フリル」に所属していた人気アイドルだった。    生前、アイは明るく前向きな性格だったが、ゾンビとなってからはやや懐疑的で疑り深い性格になった。しかし、徐々にグループのメンバーと打ち解けるにつれて、本来の自分らしさを取り戻しつつある。また、アイドルとしての経験を活かして他のメンバーを助けるなど、支えとなる一面も見せている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b127539-u9SPsvkHmgCf.png', '3月7日', NULL, '種田梨沙', NULL, 127539, 'MAIN', 546) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022639', 'AN1991', '二階堂サキ', '没：1997年8月30日　かつてはバイカー集団「ドラミ」の一員として九州全土を制覇したバイカーだった。 サキは強気で反骨精神あふれる性格で、サクラを「お利口さん」と呼び、度胸のない者には敬意を払わないと公言している。 しかし、公演が成功を収めた後は、サキはアイドルとしての活動を非常に真剣に受け止め、「フランチョチョ」のリーダーとなる。また、第6話でアイを慰める場面に見られるように、時折優しい一面も見せる。生前、彼女は愛犬「タマ」をとても可愛がっていた。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n127538-z0mYekgT8d5P.png', '5月15日', NULL, '田野アサミ', NULL, 127538, 'MAIN', 1268) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022640', 'AN1991', 'ゆうぎり', '没：1882年12月28日　ゆうぎりは明治時代の高級遊女だった。死から蘇った後、ゾンビアイドルグループ「フランチョチョ」のメンバーとなる。  ゆうぎりは、生きた時代や働いていた環境のせいか、どのような状況においても非常に冷静で、伝統的な振る舞いを保っている。それにもかかわらず、現代の日本社会における変化を冷静に受け入れ、適応しているようだ。誰かが落ち込んでいるのを見るたびに、彼女はその人を物理的に叩いて、その状態から抜け出させようとする。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b127651-ncX3HZo03BWA.png', '11月23日', NULL, '衣川里佳', NULL, 127651, 'MAIN', 573) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022641', 'AN1991', '紺野純子', '没：1983年12月9日　今野純子は、その人気によって1980年代の「アイドルブーム」を巻き起こしたアイドルだった。彼女は1983年、飛行機事故で亡くなった。「昭和の伝説的アイドル」と称されている。  純子は、穏やかで落ち着きがあり、少し内気な一面もあるが、大胆とは言えないまでも、どこか真面目な一面も持っているようだ。この真面目な一面は、屋敷から脱出しようとする時、サキやサクラと協力して温泉へ行く時、そしてアイドルに関する話題の際などに表れている。何か不穏な出来事が起きると、パニックに陥りやすいようだ。', 19, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b127541-6J7dwza3BDa0.jpg', '9月2日', NULL, '河瀬茉希', 155, 127541, 'MAIN', 759) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022642', 'AN1991', '巽幸太郎', '彼はアイドルグループ「フランチョチョ」のエネルギッシュなプロデューサーだ。異なる時代の少女たちをゾンビとして蘇らせ、自身のアイドルグループの一員にしたのは彼である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b127543-eiGF28B6adis.jpg', NULL, NULL, '宮野真守', NULL, 127543, 'MAIN', 1581) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022643', 'AN1991', '星川リリィ', 'リリーはよく笑顔を見せているほか、まだ若いせいか、かなり遊び心のある一面も見せています。また、亡くなる前の経験から、プロとしての側面も示しています。', 12, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b127652-DVP9Nobu7j8K.png', '10月6日', NULL, '田中美海', NULL, 127652, 'MAIN', 539) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022644', 'AN1991', '山田たえ', '過去が謎に包まれた少女で、「伝説の山田たえ」という称号のみが知られている。彼女だけは他の少女たちとは異なり、意識を完全には取り戻しておらず、依然として意識のないゾンビのような状態にある。 そのため、たえは予測不能で純粋な本能に駆られ、他のメンバーに噛み付いたり、群衆に飛びかかったりといった行動をとる。しかし、彼女にはある程度の自覚があるようで、少なくともメンバーの言葉をある程度理解でき、協力して行動に参加できるほどにはなっている。', 29, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n127650-sJrUSwE4taUC.png', NULL, NULL, '三石琴乃', NULL, 127650, 'MAIN', 879) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022645', 'AN1991', 'ロメロ', 'コタロウのペットであるゾンビ犬。おもちゃのポドル犬だと言われているが、人によってその大きさが常に変わっているようだ。ゾンビ犬であるロメロは、普通の犬には体に悪いような食べ物でも平気で平らげてしまう。大好物はイカだ。性別はオス。 *生きている犬には絶対に干しイカを与えないでください！  （出典：ゾンビランド・サガ ウィキア）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b127649-jjuA0P5aZRpM.jpg', '11月1日', NULL, '高戸靖広', NULL, 127649, 'SUPPORTING', 85) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022646', 'AN1991', '大古場新太', 'カメラマンの犬走とタッグを組んで活動するチーフレポーター。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b247002-ZICTNkG7erOE.jpg', NULL, NULL, '奈良徹', NULL, 247002, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022647', 'AN1991', '警察官A', '彼は、ゾンビが自分にとってどれほど脅威であるかを自覚している以上に、むしろ自分の方がゾンビにとって脅威となっているのだが、目につくゾンビを次々と殺そうとする彼の動機は、彼がごく普通の、概して人当たりの良い、怯えた警官に過ぎないことを考えれば、十分に理解できる。', 36, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b132105-jsWXfISGVEbK.jpg', '11月14日', 'A', '吉野裕行', 167, 132105, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022648', 'AN1991', '楪舞々', 'フランチョチョの熱狂的なファンの一人。マイマイは、通っている高校の2年3組に所属しているようだ。    （出典：ゾンビランド・サガ Wiki）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b226958-8y97y4rFKOAg.png', NULL, NULL, '花澤香菜', NULL, 226958, 'SUPPORTING', 33) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022649', 'AN1991', '大空ライト', '『Japanese Got Performance』でのパフォーマンスにおいて、星川リリィのライバルとなった天才子役。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b247003-3jsLt1PTxLRF.jpg', NULL, NULL, '阿部カノン', NULL, 247003, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
