INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022651', 'AN1991', '天吹麗子', 'かつて「ドラミ・バイカー・ギャング」に所属していた頃、サキの親友であり仲間だったが、現在は専業主婦であり、マリアの母親である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b150564-BxiXiUO2Fwax.jpg', NULL, NULL, '松下こみな', NULL, 150564, 'SUPPORTING', 17) ON CONFLICT DO NOTHING;
