INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022653', 'AN1991', '犬走', '彼はオコバ・アラタ氏の同僚であり、佐賀の地元テレビ局で働くジャーナリストだ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b247004-wx7BuCnicshT.jpg', NULL, NULL, '木村良平', NULL, 247004, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022654', 'AN1991', 'ホワイト竜', 'ホワイト・リュウは1990年代、佐賀で有名な歌手兼ラジオディレクターだった。彼のラジオ番組は、その雄弁な語り口で人気を博したが、時代がギャング全盛期となったことで、次第に人々の記憶から薄れていった。また、コルヘアスタイルも流行遅れとなってしまった。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b219540-6vYxA3Oa9IyP.png', NULL, NULL, '白竜', NULL, 219540, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
