INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022656', 'AN1991', '徐福', '彼は百崎喜一の養祖父であり、小太郎がたまたまつるんでいるバーテンダーでもある。また、「ゾンビランド・サーガ」プロジェクト全体の責任者でもある。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b247005-VRXDgRpgkq1j.jpg', NULL, NULL, '大塚芳忠', NULL, 247005, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
