INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022662', 'AN1991', '天吹万梨阿', 'レイコの娘であり、ドラミ・バイカー・ギャングの現在のリーダー。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b150563-JSMvq64JKmIg.jpg', NULL, NULL, '古賀葵', NULL, 150563, 'SUPPORTING', 26) ON CONFLICT DO NOTHING;
