INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022665', 'AN1992', 'ジョー', '町の片隅で活動するアンダーグラウンドのメガロボクサーで、本名は不明の「ジャンク・ドッグ」は、悪徳マネージャーの南部贋作のために金を稼ぐべく、試合を故意に落とすことを強いられている。しかし、彼にはほとんどのボクサーが欠いているもの――「真の闘志」があった。 彼は単に小銭を稼ぐためではなく、メガロボクサーとしての実力を証明するために戦うのだ。そこで、勇利から「メガロニア・トーナメント」に参加し、真のファイターであることを証明するために自分と戦ってほしいと挑まれた彼は、その機会を即座に掴んだ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/125369-uVnKfLJKTI4K.jpg', NULL, NULL, '細谷佳正', NULL, 125369, 'MAIN', 1332) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022666', 'AN1992', 'タツミ・レナード・アラガキ', '南部氏の元教え子。物語の始まりの数年前、徴兵され、兵士として従軍中に爆発に直撃され、両足を失い、顔の半分を火傷した。 帰還後、PTSDに悩まされ、自殺未遂に至った。また、新垣が死亡したと新垣が思い込んでジムを閉鎖していたことを知り、南部に見捨てられたと感じていた。物語の始まりの3年前に、メガロ・ボクシングに復帰する。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n130058-PLSf9fWQiPkn.jpg', NULL, NULL, '田村真', NULL, 130058, 'SUPPORTING', 41) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022667', 'AN1992', 'エジソン・リュウ', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b226032-XamEFUX3Jro5.jpg', NULL, NULL, '福西勝也', NULL, 226032, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022668', 'AN1992', 'ジミー', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b238197-7HBwe2f4YBDP.png', NULL, NULL, '佐々木省三', NULL, 238197, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022669', 'AN1992', '南部贋作', '南部贋作は、ジョーのボクシングのコーチ兼マネージャーである。彼は、アルコール依存症の常習的なギャンブラーとして知られている。かつて彼とジョーはアンダーグラウンドのボクシング界で活動しており、ジョーに八百長試合をさせて金を稼がせていた。 しかし、心の奥底ではジョーの実力を信じており、ドッグレースへの賭けで積み上げた多額の借金を返済した後、トーナメント優勝と賞金を狙うべく、ジョーをメガロニアに参戦させることを決めた。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n130056-IpE4ls2sH4uR.jpg', NULL, NULL, '斎藤志郎', NULL, 130056, 'SUPPORTING', 140) ON CONFLICT DO NOTHING;
