INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022673', 'AN1992', '勇利', '勇利は白都ゆき子のボディーガードであり、白都グループが主催する大規模なメガロボクシング大会「メガロラニア」の現王者である。 彼は、自分とユキコの両方を侮辱したアンダーグラウンドのファイター、ジャンク・ドッグ（ジョー）を追いかけ、アンダーグラウンドのリングで彼と対峙する。そこで容易く彼を打ち負かし、再び戦いたいならメガロニアまで這い上がってくるよう挑発した。 勇利は、独自の最先端プロトタイプ「統合型」ギアを装備しており、これは外科手術によって直接', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b127574-lxBOWzqmNRlY.png', NULL, NULL, '安元洋貴', NULL, 127574, 'SUPPORTING', 143) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022674', 'AN1992', '虻八', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b173538-KHAi86GekcDq.jpg', NULL, NULL, '佐々木睦', NULL, 173538, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022675', 'AN1992', '藤巻', 'ジャンク・ドッグとナンブのために八百長試合を仕組むマフィアのボス。ジャンク・ドッグが八百長を拒否したため、2人がメガロニアに入国できるよう偽造の市民IDを入手する手助けをし、賞金で借りを返してもらうことにした。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n130055-JuIZzD7BQAnR.jpg', NULL, NULL, '木下浩之', NULL, 130055, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
