INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022677', 'AN1992', 'サチオ', '貧しい「制限区域」出身の少年で、機械の扱いや修理に長けており、彼と仲間たちはその腕前を駆使して神々を盗み出し、それを麻薬の一種である「レッド・キャンディ」と交換している。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n130054-4d9nPwohxBO6.jpg', NULL, NULL, '村瀬迪与', NULL, 130054, 'SUPPORTING', 103) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022678', 'AN1992', 'オイチョ', 'オイチョはサチオの友人の一人で、虻八に弟子入りしているエンジニアであり、店の手伝いをしている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b173539-d2Ql9BLasMcm.jpg', NULL, NULL, '内藤有海', NULL, 173539, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022679', 'AN1992', '朝本・マルゲリット・ユナ', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b230549-QRUuqv1jfNpG.jpg', NULL, NULL, '樋口あかり', NULL, 230549, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022680', 'AN1992', 'チーフ', 'チーフは、「カサ」と呼ばれる移民のコミュニティに住むメガロボクサーだ。彼のキャリアは下位リングにとどまっている。その温厚な人柄から、彼はカサのグループにおいて一種のリーダー的存在となっている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b216685-hlRdXUO2N1As.jpg', NULL, NULL, '田中美央', NULL, 216685, 'SUPPORTING', 152) ON CONFLICT DO NOTHING;
