INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022682', 'AN1992', '吉村朋花', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b230548-k0FWAvpKmUJx.jpg', NULL, NULL, '村中知', NULL, 230548, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022683', 'AN1992', 'マーラ', 'マーラは、カーサの整備工場を経営し、ミオを一人で育てているたくましい女性だ。彼女はとても頼りになる存在で、チーフのギアの整備から日常生活のサポートに至るまで、あらゆる面で彼を手助けしている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b217862-SBLA3vnhUNfb.jpg', NULL, NULL, 'ニケライ ファラナーゼ', NULL, 217862, 'SUPPORTING', 26) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022684', 'AN1992', '白都樹生', 'ユキコの兄であり、人工知能を搭載した最先端のギア「エース」の開発者。このギアは相手の動きを読み取り、予測することで、完璧な対抗策や戦略を立案することができる。 ミキオは傲慢で自己中心的、そして自惚れが強く、ジョーのような「野良犬」は自分と同じリングに立つ資格すらないと信じている。ミキオはシラト・グループのトップの座を、妹に奪われてしまったため、彼女に対して恨みを抱いている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n130057-kKecCxKYQSQ9.jpg', NULL, NULL, '鈴木達央', NULL, 130057, 'SUPPORTING', 22) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022685', 'AN1992', 'ハキーム', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b233150-wihfHqvviK7P.jpg', NULL, NULL, 'ボルケーノ太田', NULL, 233150, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022686', 'AN1992', 'ミオ', 'ミオはマーラの唯一の息子だ。彼は悪い仲間とつるんでおり、そのせいでいつもトラブルに巻き込まれている。ジョーのバイクまで盗んでしまったほどだ。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b217863-Q02baY40BzvQ.jpg', NULL, NULL, '日野佑美', NULL, 217863, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022687', 'AN1992', '白都ゆき子', 'メガロニア・トーナメントを統括するシラト・グループの責任者。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n130053-WsCnfV4MloKa.jpg', NULL, NULL, '森なな子', NULL, 130053, 'SUPPORTING', 35) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022688', 'AN1992', '氷川', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b218586-T3ii6DSLQZGR.jpg', NULL, NULL, '魚建', NULL, 218586, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022689', 'AN1992', 'マック・ロサリオ', 'マックはもともと優れたメガロボクサーというわけではなかったが、家族を養うために警察官になった際、職務中に命にかかわる重傷を負ってしまった。しかし、サクマと最先端の医療技術のおかげで奇跡的な回復を遂げ、再びリングに立ち返ることができた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b225451-hr0XhCAw2s9Q.jpg', NULL, NULL, '宮内敦士', NULL, 225451, 'SUPPORTING', 27) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022690', 'AN1992', '田中', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b233151-5oh5IEIXePsS.jpg', NULL, NULL, '白石兼斗', NULL, 233151, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022691', 'AN1993', '麻中蓬', '彼は富士ヨキ高校の1年生で、両親の離婚や母親に新しい恋人ができたことに対処するため、コンビニでアルバイトを始めた。 彼はガウマに食べ物を差し出したことをきっかけに親しくなり、クラスメートの南夢芽や山中暦らと共に、ダイナゼノンの副操縦士の一人として巻き込まれていった。4人のパイロットのうち、ヨモギだけはスケジュールの都合で、操縦技術の訓練に多くの時間を割くことができなかった。', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b169409-qxaOR6fYkf1F.png', NULL, NULL, '榎木淳弥', NULL, 169409, 'MAIN', 265) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022692', 'AN1993', '南夢芽', '南夢芽は『SSSS.DYNAZENON』の主要キャラクターの一人である。彼女は、富士ヨキ高校でヨモギの同級生であり、心の悩みを抱えていたが、ダイナゼノンの4人の副操縦士の一人となった。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b169411-8gM6Cukk0KGP.jpg', NULL, NULL, '若山詩音', NULL, 169411, 'MAIN', 591) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022693', 'AN1993', 'ガウマ', 'ガウマは『SSSS.DYNAZENON』の主要な主人公の一人である。ヨモギが彼に食べ物を差し出したことをきっかけに親しくなった、謎めいた男だ。彼はダイナゼノンを駆使して、怪獣優生学者たちと戦っている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b169410-1OPVzoQRlDqk.png', NULL, NULL, '濱野大輝', NULL, 169410, 'MAIN', 210) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022694', 'AN1993', '飛鳥川ちせ', '飛鳥川ちせは『SSSS.DYNAZENON』の主要キャラクターの一人である。彼女は小夜美のいとこであり、小夜美を「先輩」と呼んでいる。 ダイナゼノンのパイロットではないものの、小夜美が参加していることから、ちせはよく彼らと行動を共にしており、かつてはヨモギが体調を崩した際に『ダイナソルジャー』で彼の代役を務めたこともある。', 12, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b169413-2MtfCpKf5mqe.png', NULL, NULL, '安済知佳', NULL, 169413, 'MAIN', 127) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022695', 'AN1993', '山中暦', 'コヨミは『SSSS.ダイナゼノン』の主人公の一人である。33歳のニートである彼は、ダイナゼノンと怪獣との戦いに巻き込まれ、ガウマ、麻中蓬、南夢芽と共に、このメカのパイロットの一人となる。  彼は飛鳥川ちせのいとこである。', 33, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b169412-BLVhlmwmyCgg.png', NULL, NULL, '梅原裕一郎', NULL, 169412, 'MAIN', 44) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022696', 'AN1993', 'なずみ', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b198600-65LdVVA3m3BD.png', NULL, NULL, '梶原岳人', NULL, 198600, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022697', 'AN1993', 'アンチ', '茜が作り出した、相手の能力を模倣できる知性を持つ怪獣。アンチは、人間形態でも怪獣形態でも、ハイパーエージェントに対して理不尽なほどの憎悪を抱いている。その憎悪は極めて強く、グリッドマンと自分の間に立ちはだかる怪獣であれば、たとえ仲間であっても攻撃してしまうほどである。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b127591-LdxQumxvtFP1.png', NULL, NULL, '鈴村健一', NULL, 127591, 'SUPPORTING', 142) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022698', 'AN1993', '淡木', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b198601-0tDWMjTH7fcq.png', NULL, NULL, '小笠原仁', NULL, 198601, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022699', 'AN1993', 'アノシラス２代目', '彼女は、どういうわけか世界の秘密を知っている謎めいた少女だ。アンチと同様、彼女は実は人間の姿をした怪獣である。しかし、他の怪獣とは異なり、彼女は新条アカネによって生み出されたわけではない。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130099-gxcxSj7KU1Ly.png', NULL, NULL, '高橋花林', NULL, 130099, 'SUPPORTING', 60) ON CONFLICT DO NOTHING;
