INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022702', 'AN1993', '南香乃', 'ユメの姉。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b230459-LRrxSDyzVjRQ.png', NULL, NULL, '佐伯伊織', NULL, 230459, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022703', 'AN1993', 'ムジナ', 'ムジナは『SSSS.DYNAZENON』の敵役の一人であり、「怪獣優生学者」の唯一の女性メンバーである。 彼女は、自ら認める通り、人生において目指すべき目標を持たない淡々とした女性であり、その姿勢は「怪獣優生学者」の仲間たちとの会話の中でも強調されており、そこで彼女は「彼らが決めたことなら何でもする」と語っている。 価値ある目標に対する意欲の欠如は、彼女とコヨミが交わした和やかな会話を通じて明らかになった共通点であり、そのことがきっかけで、彼女は一時的に生き続けることを考えた。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b198598-C8uylI9tcmYo.png', NULL, NULL, '諏訪彩花', NULL, 198598, 'SUPPORTING', 170) ON CONFLICT DO NOTHING;
