INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022710', 'AN1994', '瞳島眉美', '「美少年探偵団」の唯一の女性メンバー。真由美は美しい少女だが、クラブ活動中は男装をしている。生徒たちは、文字通り「星のような瞳」が美しいとよく言うが、彼女自身は「美しい」と言われるのが大嫌いだ。そのため、その星のような瞳が目立たないように、眼鏡をかけている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b150027-hC8Xpttx8H6Y.png', '10月10日', NULL, '坂本真綾', NULL, 150027, 'MAIN', 297) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022711', 'AN1994', '双頭院学', '「美少年探偵団」のリーダー。「美学者のマナブ」としても知られる。マユミは彼を「リーダー」と呼んでいる。  彼は非常に愚かで、自分では無学だと公言し、場の空気を読まずに陽気で傲慢な振る舞いをするが、常に美を追い求め、美学に反することは決してしない。命令ばかりして何もしないことが多いものの、グループからはリーダーとして認められている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b139671-IlFyF7qxa8Hp.jpg', NULL, NULL, '村瀬歩', NULL, 139671, 'MAIN', 211) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022712', 'AN1994', '足利飆太', 'ユビワ学園中学校1年A組。陸上部のエース。 ショートパンツのように見えるよう改造された制服を着ている。 彼がそのようなユニフォームを着て学校に入学して以来、それを見た女子生徒たちは皆、スカートの丈を短くするのをやめ、黒いストッキングを履くようになった。彼は整った顔立ちをしており、他の天使たちを指揮する大天使のようだとしてからかわれる。冬でも脚を露出することにこだわっている。彼は探偵部の体力担当メンバーである。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b158664-WCjQKvW7K9iY.jpg', NULL, NULL, '矢野奨吾', NULL, 158664, 'MAIN', 149) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022713', 'AN1994', '袋井満', 'ユビワ学園中学校2年A組。「学校に関わってはいけない生徒ランキング」のトップに立つ危険な人物だ。 学校の外では「ボスマン」として知られているが、料理の腕も抜群で、家族思いな一面も持っている。皮肉たっぷりの比喩を多用する癖がある。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b158665-2dUvxQKQ3m39.jpg', NULL, NULL, '増田俊樹', NULL, 158665, 'MAIN', 278) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022714', 'AN1994', '指輪創作', 'ユビワ学園中学校1年A組。ユビワ学園の親組織であるユビワ財団の後継者であり、事実上の会長である。 経済面でも芸術面でも才能に恵まれた神童であり、探偵クラブの美術チームに所属している。無表情で口数が少ないが、その本心を読み取れるのは学だけである。通常、各巻で2回しか話さない。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b158666-XCceNhKO9Eld.png', NULL, NULL, '佐藤元', NULL, 158666, 'MAIN', 190) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022715', 'AN1994', '咲口長広', 'ユビワ学園中学校3年A組。元生徒会長。「美少年探偵団」の副団長。小学1年生の婚約者がいるため、「ロリコン」と揶揄されているが、本人はそれを否定している。 彼は「僕はロリコンじゃない。ただ、両親が勝手に決めた婚約者がたまたま6歳なだけだ」と語っている。彼は、nの代表として演説を行って以来、3年連続で生徒会長を務めている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b158667-og0xDTvQG8ic.jpg', NULL, NULL, '坂泰斗', NULL, 158667, 'MAIN', 125) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022716', 'AN1994', '永久井こわ子', '同校の「伝説の教師」として知られるコワコは、かつて同校の美術教師を務めていたが、教職員との意見の相違から解雇された。ただし、もし解雇されたら、生徒全員を誘拐すると宣言していた。現在、彼女は同校には勤務していない。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b227372-GnASEFjTO0gF.jpg', NULL, NULL, '佐藤利奈', NULL, 227372, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022717', 'AN1994', '川池湖滝', 'ユビワ学園小学校1年A組の生徒であり、先口長弘の婚約者。着物を着て、物音一つ立てずに歩く美しい少女だが、その見た目とは裏腹に、口が鋭い。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b228997-FJ3HQrDdrhYB.png', NULL, NULL, '安済知佳', NULL, 228997, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022718', 'AN1994', '沃野禁止郎', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b231195-DvyMnXQygJPC.jpg', NULL, NULL, '鈴木崚汰', NULL, 231195, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022719', 'AN1994', '長縄和菜', '現学生会副会長であり、咲口長広の右腕的存在。迫る選挙に向け、教職員による業務増大の要望から学校をある程度守り抜くという長広の理念を継承するため、学生会長選に立候補している。  ワナは多くの人から「雪の女王」というあだ名で呼ばれているが、実際の性格はその名前が連想させるものとは正反対だ。彼女は優しく、明るく、並外れて人懐っこい。また、ワナは猫のスリッパを履いており、額に入った猫の写真も飾っていることから、彼女は', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b232974-a1opeFO2jm37.jpg', NULL, NULL, '黒沢ともよ', NULL, 232974, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022720', 'AN1994', '双頭院踊', 'マナブの兄であり、「美少年探偵団」の創設者。現在はユビワ高校の2年生。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b232975-n1JTbxSxO5Xc.jpg', NULL, NULL, '石田彰', NULL, 232975, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022721', 'AN1994', '札槻嘘', '美容専門学校2年生。生徒会会長。カリスマ性があり、野心家だ。「Reasonable Dobt」というカジノを経営している。民間の武器メーカーと関わりがあり、その製品についてレポートを執筆している。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b212923-XWlrP0EO6lwv.png', NULL, NULL, '鳥海浩輔', NULL, 212923, 'SUPPORTING', 29) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022722', 'AN1994', '麗', '違法な運び屋グループ「トゥエンティーズ」のリーダー。彼女は特に信心深いわけではないが、仲間を大切にする美しい女性だ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b212925-XmlMgkk3DDbx.jpg', NULL, NULL, '七海ひろき', NULL, 212925, 'SUPPORTING', 32) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022723', 'AN1995', '礼子', '礼子はスクーターオタクで、あらゆるメーカーやモデルのスクーターについて幅広い知識を持っています。  父親は市議会議員、母親は会社を経営しており、二人とも東京に住んでいる。そのため、礼子は北杜市の鵡川地区にある別荘で一人暮らしをしている。礼子は成績も優秀でスポーツも得意だが、それにもかかわらず、彼女の唯一の興味はカブスにあり、その熱狂的なファンとして非常に詳しい。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b133947-xpqayCHNhXGQ.png', NULL, NULL, '七瀬彩夏', NULL, 133947, 'MAIN', 189) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022724', 'AN1995', '小熊', '小熊は物静かな少女で、スーパーカブを購入したことをきっかけに、友達や自信、そして冒険のスリルを手に入れる。小熊は幼い頃に父親を亡くし、高校に入学した時には母親が家を出てしまった。他に親戚もおらず、一人暮らしをしている。 また、趣味も友達もおらず、学校ではほとんど目立たない存在だ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b133946-PuWmDuOGkb2W.png', '6月6日', NULL, '夜道雪', NULL, 133946, 'MAIN', 314) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022725', 'AN1995', '恵庭椎', 'シイは小熊や礼子と同じクラスだ。文化祭の際、先生の車が使えなかったため、移動に必要な機材の運搬で困っていた。小熊の希望で、小熊と礼子は自分たちの「カブ」を使って彼女を手伝った。 「カブス」に興味を持ったシイは、彼らとよく一緒に過ごすようになった。彼女は自宅でパン屋を営んでおり、礼子や小熊もよくそこを訪れている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b204443-1Hp6mwfiwUKN.png', NULL, NULL, '日岡なつみ', 140, 204443, 'MAIN', 115) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022726', 'AN1995', 'シノさん', '小熊にスーパーカブを安く譲ってくれたバイクショップの店主。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b217230-Eyr6cZiDnAVh.png', NULL, NULL, '魚建', NULL, 217230, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
