INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022757', 'AN1998', '双葉翔太郎', '青高校新入部の新入部員。 高校1年生。宮城県出身。中学3年の夏、偶然青高校男子新体操部の演技を見て、新体操の魅力に惹かれた。  青高校に入学し、新体操の世界に飛び込んだ。アマチュアではあるが、その率直な性格から、急速に成長していくことだろう。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b194263-keIfyeJu4L4n.png', NULL, NULL, '土屋神葉', NULL, 194263, 'MAIN', 182) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022758', 'AN1998', '美里良夜', '青高校新入部の新入部員。高校1年生。宮城県出身。常に冷静な態度を保つ穏やかな性格だが、他人に対して距離を置く一面もある。  男子新体操ジュニア大会で準優勝を果たした実力者であり、青高校新体操部の若きエースとして期待されている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b194264-UjfNQqK1StGq.png', NULL, NULL, '石川界人', NULL, 194264, 'MAIN', 301) ON CONFLICT DO NOTHING;
