INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022772', 'AN1998', '双葉亜由美', '翔太郎の妹。すでに中学2年生だが、今でも家族の中では末っ子扱いされている。兄とは仲が良く、母の手作り餃子が大好きだ。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b213747-JQAp4emFzZq4.png', NULL, NULL, '上田麗奈', NULL, 213747, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022773', 'AN1999', '王城正人', 'マサトはノキン高校のカバディ部の監督である。彼は、その細身の体格をカバーする「カウンター」を極め、日本トップクラスの実力を誇る。また、試合中にスイッチが入ると、まるで野獣のような姿を見せることもある。カバディ歴は10年以上になる。', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b177491-f4p6eebLoxAS.jpg', '1月1日', NULL, '岡本信彦', NULL, 177491, 'MAIN', 214) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022774', 'AN1999', '宵越竜哉', 'ヨイゴシはノキン高校の1年生で、かつてはサッカーのエース選手だったが、今はスポーツが嫌いだ。ある時、彼はカバディ部の入部を誘われた。当初、タツヤは自分に合うかどうか疑っていたが、練習を見学した後、入部を決意した。  吉越達也はかつてサッカーのエース選手だったが、もううんざりして、高校に入学するとライブストリーマーになり、あらゆるスポーツを敬遠していた。学校の様々なスポーツ部のメンバーが彼に入部を懇願したが、彼はいずれも断り続けていた。ある日のこと、', 16, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b177484-shxkJYOH9ayY.jpg', '8月7日', NULL, '内田雄馬', NULL, 177484, 'MAIN', 152) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022775', 'AN1999', '井浦慶', '「ノキョー・カバディクラブ」の副部長。優れた分析力を持つ頭脳派。 一見、穏やかなヤサの男性のように見えるが、裏の顔は狡猾で、ヨゴエをカバディ部に入部させるために、半ば脅しのような手段を講じる。カバディ歴は6年である。', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b177497-rgOtNwzxBPKm.jpg', '12月18日', NULL, '古川慎', NULL, 177497, 'MAIN', 67) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022776', 'AN1999', '水澄京平', '恭平はノキン高校の2年生だ。中学時代までは、喧嘩に巻き込まれるなど問題児だった。高校に入学してからは性格を改めたものの、伊浦はかつての「ヤン」だったという証拠を基に、カバディ部に入部することを決めた。カバディ歴は1年1ヶ月である。', 16, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b177493-1aRi7pewEmkT.jpg', '3月9日', NULL, '鈴木達央', NULL, 177493, 'MAIN', 30) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022777', 'AN1999', '伊達真司', 'シンジはノキン高校の2年生だ。かつては経験豊富な野球選手で投手だったが、怪我のために引退した。高校で何をしようかと悩んでいたところ、ミスマが彼をカバディ部へ誘った。 不器用ながらも恵まれた体格と筋力が彼の武器だ。カバディ歴は6ヶ月である。', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b177496-HDiNJMcMjG8r.jpg', '4月8日', NULL, '武内駿輔', NULL, 177496, 'MAIN', 27) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022778', 'AN1999', '畦道相馬', 'ソーマはノキン高校の1年生だ。両親の家が山奥にあったため、彼は毎日まるで筋力トレーニングのような生活を送っていた。その結果、その小柄な体格からは想像もつかないほどの力を身につけた。カバディを始めてから1ヶ月になる。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b177492-CcOEtGljvQ2D.jpg', '5月15日', NULL, '佐藤元', NULL, 177492, 'MAIN', 33) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022779', 'AN1999', '人見裕希', 'ユキはノキン高校の1年生だ。彼はセキと一緒にカバディ部を訪ねるが、その無表情な様子から、夕方になると女性と間違われてしまう。', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b177498-kKbGeb5Es5o8.png', '9月21日', NULL, '村瀬歩', NULL, 177498, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022780', 'AN1999', '右藤大元', '広本は埼玉光陽高校の2年生で、カバディ部の部長を務めている。一見地味な外見とは裏腹に、多才な才能で高い評価を得ている実力者だ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b213504-ZFdpkeiEupyI.png', NULL, NULL, '斉藤壮馬', NULL, 213504, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022781', 'AN1999', '高谷煉', 'レンはソワ高校の2年生だ。カバディ部のエースアタッカー（レイダー）である。その自由奔放な振る舞いに周囲を困らせているが、そのリーチ、スピード、そして並外れた攻撃持続時間は、チーム内でもトップクラスだ。 中学生の頃、水泳で全国大会を制した経験がある。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b213499-WVnp7vI6xdKz.png', '4月2日', NULL, '鈴村健一', NULL, 213499, 'SUPPORTING', 33) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022782', 'AN1999', '六弦歩', 'アユムは、関東地方有数の名門校である草和高校の3年生で、カバディ部の部長を務めている。彼は卓越した身体能力と技術を持つディフェンダーであり、中学生の頃から王城正人とは良き友人でありライバルでもある。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b213498-J3vTycfnVk8y.png', '7月23日', NULL, '安元洋貴', NULL, 213498, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022783', 'AN1999', '室屋大助', '大輔は、ソワ高校の2年生で、身長180cmのがっしりとした体格と、分厚い唇が特徴だ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b213502-M3XkoCxSSsK4.png', NULL, NULL, '柳田淳一', 180, 213502, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022784', 'AN1999', '栄倉祐', 'ユウは草和高校の2年生だ。物静かな性格で、ピンチの時でも冷静に対応できる。よく高谷と3年生たちに挟まれることが多い。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b213501-w8x4SoAKPgBy.png', NULL, NULL, '内田修一', NULL, 213501, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022785', 'AN1999', '関隆太', '竜太はノキン高校の1年生だ。同級生に誘われてカバディ部に入った。メガネをかけたぽっちゃり体型の彼だが、実は中学まで相撲をやっていた。コミュニケーション能力が高い。', 16, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b177499-PxBaMKFJhLo3.png', '6月18日', NULL, '駒田航', NULL, 177499, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022786', 'AN1999', '木崎新太郎', 'シンタロウは草和高校の3年生だ。趣味はヘアバンドを集めることで、試合中もよくそれを身につけている。3年生とはいえ、無防備な高谷を頻繁にからかう。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b213500-pSGv0jv6xAU2.png', '6月15日', NULL, '八代拓', NULL, 213500, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022787', 'AN1999', '伴伸賢', '信隆はノキン高校の1年生だ。小学生の頃からヨゴエに憧れており、彼女に近づきたいという思いからカバディ部に入部した。頭は丸く、顔立ちは悪いが、声は極めて小さい。', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b177494-IOqqkDiYlcAb.png', '9月7日', NULL, '神尾晋一郎', NULL, 177494, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022788', 'AN1999', '佐倉学', '学は埼玉光陽高校の2年生で、中学3年生の頃、大城雅人や井浦慶と同じクラスだった。当時、学は大城を特に尊敬しており、彼から様々な技を教わった。性格は少々気まぐれだが、恵まれた体格と身長に加え、底知れぬ才能の持ち主である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b213503-pahBTPOU5rw1.png', NULL, NULL, '花江夏樹', NULL, 213503, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022789', 'AN2000', '桜庭音操', '世間の騒音を遮るために常にヘッドホンを外さない、反社会的でグラフィティ好きの少年。彼は渋谷のスクランブル交差点の真ん中で目を覚まし、すぐに何かがおかしいと気づく……', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b12069-BXcq95f1oUc7.png', NULL, NULL, '内山昂輝', NULL, 12069, 'MAIN', 283) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022790', 'AN2000', '尾藤来夢', 'いつも笑顔を絶やさない、献身的で真面目な少女。ビートがどこへ行っても、彼女は後をついていく。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b19438-4RWOemdN5gQ4.png', NULL, NULL, '竹達彩奈', NULL, 19438, 'MAIN', 38) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022791', 'AN2000', '桐生義弥', '賢いが、どこか胡散臭い少年で、その知性は感嘆を誘うほどだが、同時に不安を掻き立てるほどでもある。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b14398-4D8ehpOLfba1.png', NULL, NULL, '木村良平', NULL, 14398, 'MAIN', 179) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022792', 'AN2000', '美咲四季', '常に最先端のファッションを取り入れることにこだわっているおしゃれな女の子。彼女は手作りの猫のぬいぐるみを、どこへ行くにも持ち歩いている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b12461-K4qXnlBgqoHa.png', '10月12日', NULL, '鉢嶺杏奈', NULL, 12461, 'MAIN', 150) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022793', 'AN2000', '尾藤大輔之丞', '熱血で頑固な10代の少年が、パートナーのライムを連れて突然現れる。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b20839-UOS72fhZuy3Z.png', NULL, NULL, '木村昴', NULL, 20839, 'MAIN', 70) ON CONFLICT DO NOTHING;
