INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022800', 'AN2000', '羽狛早苗 ', '羽狛早苗は、自らを「ダンディなカフェのオーナー」と称する『WildKat』の経営者である。彼はネクやその仲間たちにとってかけがえのない味方であり、プレイヤーたちの守護者としての役割を果たし、常にゲームが公正に行われ、全員がルールを守るよう見守っている。また、ジョシュアとは非常に親しい間柄である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/16343.jpg', '3月3日', 'A', '津田健次郎', NULL, 16343, 'SUPPORTING', 40) ON CONFLICT DO NOTHING;
