INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022809', 'AN2001', 'レティ', 'Gender: Male Species: Dragon  Letty (レティ, Reti) is the main character of Dragon Goes House-Hunting series. He is a weak, cowardly dragon disowned by his family. After being kicked out of his family''s home, he sets out on a journey in search of a dream home where even a weakling like him can live in peace and safety.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b169738-b0bOp8aUyr3R.png', NULL, NULL, '堀江瞬', NULL, 169738, 'MAIN', 43) ON CONFLICT DO NOTHING;
