INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022823', 'AN2002', 'ファリア', 'ファリアは、セブンナイトとしての使命に従って生きてきた。 彼女の最優先事項は、できる限り多くの命を救うことだったが、ネモと出会ってからは変化し、自分自身についても考え、気遣うようになった。幼い頃から訓練を受けてきたため、意志が強く、非常に有能な戦士である。戦闘以外ではかなり不器用な面もあるが、何事にも常に全力を尽くしている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b206835-HDhqEO372ffw.jpg', NULL, NULL, '山村響', NULL, 206835, 'MAIN', 22) ON CONFLICT DO NOTHING;
