INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022872', 'AN2004', '平原陽桜莉', '彼女は明るく優しい女の子で、頭はそれほど良くはないものの、それでも自分の立場をしっかりと守れる。ミオの妹であるヒオリは、頑固でありながらも意志が強く、一度心に決めたことは、それを成し遂げるために全力を尽くす。  また、ヒオリは本音を表現するのが苦手で、何度も感情を内に秘めてしまったことがある。幼い頃から知り合いで、とても仲の良い姉のミオを大切に思っている。ヒオリは、友人であるすべての人を深く気にかけており、その中には……', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b207903-ORw2BpjOUSSi.png', '4月15日', 'O', '石見舞菜香', 158, 207903, 'MAIN', 24) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022873', 'AN2004', '羽成瑠夏', '彼女は『BLUE REFLECTION RAY/澪/澪』の第二主人公である。ルカはかつて、人見知りが激しく、他人に迷惑をかけたくないという気持ちから、他人と関わったり自分の気持ちを表現したりすることを恐れ、ほとんど一人でいることを好む、静かで人付き合いが苦手な少女だった。   自ら命を絶った元同級生を助けられなかったことへの罪悪感から転校を決意し、月宮高校へ移った。そこで、新しいルームメイトであり、後に親友となる平原陽桜莉と出会った。彼女は心を開くことを決意し、', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b207904-JnKgtgokChV4.png', '8月16日', 'B', '千菅春香', 158, 207904, 'MAIN', 17) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022874', 'AN2004', '斎木有理', '『BLUE REFLECTION』にも登場する、超人的な知性を備えた少女。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b232952-rSp1xRXkTLEW.png', NULL, NULL, '佐倉綾音', 159, 232952, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
