INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022879', 'AN2004', '駒川詩', 'セント・イグネス高校の1年生。アロフは、自分のペースで物事を進めるのが好きだ。 痛みがあるからこそ、人生をより強烈に体験できると信じており、そのため常に精神的あるいは肉体的な苦痛を求めている。それを実現するために、彼女は嫌がらせとさえ思えるほど執拗に振る舞い、周囲の人々を挑発して、暴力や辛辣な言葉を浴びせさせるように仕向けている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b215835-ZjXWinwmyC4A.png', '1月25日', 'AB', '田辺留依', 157, 215835, 'SUPPORTING', 26) ON CONFLICT DO NOTHING;
