INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022934', 'AN2008', '明星かなた', '地球を代表するアスリートであり、ジャガイモ農家の娘。幼い頃から農作業に慣れ親しんできたため、並外れた身体能力を持っている。明るく陽気で、すぐに友達ができる。カナタは祖母から多くのスポーツの基礎を教わっており、そのことを理由に、祖母をいつまでも愛し、尊敬し続けている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b199901-u7xDwoYHjWO1.png', NULL, NULL, '諸星すみれ', NULL, 199901, 'MAIN', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022935', 'AN2008', 'エヴァ・ガレンシュタイン', 'フォン・エスクラヴォ植民地の代表。卓越した運動能力を持ち、数々の大会で優秀な成績を収めているが、いつも感情を表に出さないようだ。他の「コズミック・ビューティー」たちとは距離を置いており、その生い立ちや育ちについては全くの謎だが、カナタは彼女を知っているようだ。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b199900-8MQiei6LuHBl.png', NULL, NULL, '石川由依', NULL, 199900, 'MAIN', 1) ON CONFLICT DO NOTHING;
