INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022958', 'AN2010', '日向ゆめ', 'ユメは明るく、元気いっぱいの女の子です。ただ、ちょっと不器用でうっかり者なところもあり、時には手のかかる子になることもあります。', 12, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b161654-zaYBZq88aV7a.png', '8月16日', NULL, '村上奈津実', 152, 161654, 'MAIN', 41) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022959', 'AN2010', '月島まいら', 'マイラは、10代の少女たちに人気のファッション誌『プチ・ストロベリー』のジュニアモデルだ。また、日向ゆめの同級生でもある。関西弁を話し、「マイ・ラブ」と言う癖がある。', 12, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b161657-EIa7lrhWpDg6.png', '10月18日', NULL, '伊藤彩沙', 158, 161657, 'MAIN', 50) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022960', 'AN2010', 'すう', 'コトコのパートナー。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b161655-ZaLzn12lYrcT.png', '1月25日', NULL, '金元寿子', NULL, 161655, 'MAIN', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022961', 'AN2010', '今井ことこ', 'コトコは、人思いで賢い少女です。彼女は、人間とロボットが平和に共存できる社会を願っています。', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b161656-Nj6iWLqgRAD9.png', '3月12日', NULL, '幸村恵理', 165, 161656, 'MAIN', 12) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022962', 'AN2010', 'ねね', 'トキワのパートナー。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b181614-jtw80d11utMm.png', '3月29日', NULL, '高野麻里佳', NULL, 181614, 'MAIN', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022963', 'AN2010', '安西ときわ', 'トキワは冒険心旺盛でスポーツが得意なだけでなく、ピアノや天文学、生物学も得意だ。', 13, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b176984-1Jq9598cmDuH.jpg', '4月30日', NULL, 'ファイルーズあい', 155, 176984, 'MAIN', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022964', 'AN2010', '南川朝陽', 'アサヒはスポーツも成績も抜群の学生だが、自分の気持ち、特にユメに対する気持ちについては、なかなか打ち明けられない。', 12, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b161658-YIJK8Yonhzrl.png', '11月15日', NULL, '小林裕介', NULL, 161658, 'MAIN', 13) ON CONFLICT DO NOTHING;
