INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022968', 'AN2010', 'ちあ', '『<i>Mix</i>!』に初登場する、ピンクの赤ちゃん子猫のぬいぐるみ。誰にでも笑顔をもたらしてくれるほど元気いっぱいです。抱きしめられるのが大好きです。物語の後半で、彼女が「ミラクル・ドリーミー王国」の王女として生まれ、その心臓の中には「ドリーミー・ラベンダー・フラワー」の種が埋め込まれていることが明かされます。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b289623-QpTD46sA68a3.png', NULL, NULL, '市ノ瀬加那', NULL, 289623, 'MAIN', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022969', 'AN2010', 'アクムー', '彼女は『みゅーkledreamy Mix』の主な敵役です。希望や夢を悪夢に変えたいと願っています。面白いものが大好きです。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b324734-XzaKEF4Xx5Sy.png', NULL, NULL, '高橋美佳子', NULL, 324734, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
