INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022975', 'AN2011', 'ジバニャン', '「アカマル」は、彼がまだ生きていた頃、飼い主のエミから付けられた愛称だった。妖怪である彼は、自力での戦いが何度も失敗に終わった後、迫り来るトラックと戦うために人間に取り憑くことを余儀なくされる。 幸いにも、ネイサンとウィスパーに止められ、彼らと仲良くなった彼は、彼らの家に住み込むことにした。当初はいたずら好きで無鉄砲な一面を見せ、軽々しくルールを破り、ついにはほぼ退魔されそうになり、ネイサンに助けられる羽目になった。しかし、その直後に彼はすぐに過ちを償った。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b162152-12KGEgbSWcA3.jpg', NULL, NULL, '小桜エツコ', NULL, 162152, 'MAIN', 161) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022976', 'AN2011', '天野景太', NULL, 11, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b162151-CGmeAM3OxRle.png', NULL, NULL, '戸松遥', NULL, 162151, 'MAIN', 40) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022977', 'AN2011', 'コマさん', 'コマさんは、『妖怪ウォッチ4』に登場する、ランクD、火属性のレア妖怪で、「チャーミング族」および「お守り族」に属しています。『妖怪ウォッチ2』以前は、ノーマル妖怪でした。 コマさんは『妖怪ウォッチ』シリーズのサブマスコットであり、ジバニャンと一緒に、あるいは単独で登場する。シリーズ内で最も人気のある妖怪である。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b210075-YVM6VIrx1S0r.jpg', NULL, NULL, '遠藤綾', NULL, 210075, 'SUPPORTING', 103) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022978', 'AN2011', 'ウィスパー', 'ウィスパーは、『妖怪ウォッチ』シリーズの主要な脇役の一人です。また、ジバニャン、コマソン、コマジロらと並び、同シリーズのマスコットキャラクターの一人でもあります。彼は、天野圭太（別名ネイサン・アダムス）が自称する「妖怪執事」です。 アニメの英語吹き替え版など、一部のバージョンでは鈍感で皮肉屋な一面も見せるものの、彼は常に『妖怪ウォッチ』や妖怪そのものに関する貴重な知識を提供し、主人公の冒険を必ず支えている。  この', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b162153-9bR1iZGvwpNn.jpg', NULL, NULL, '関智一', NULL, 162153, 'SUPPORTING', 62) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022979', 'AN2011', '女の子', '第94話に登場。   *声優はホロライブのVTuber、犬上コロネが務めており、彼女に似ている。*', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b299816-D1kFjh2jcche.png', NULL, NULL, '戌神ころね', NULL, 299816, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
