INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH022995', 'AN2012', '速杉ハヤト', 'ハヤトは埼玉県在住の小学6年生で、「新幹線エボリューション研究所」の大宮支所に勤務している。何よりも新幹線を愛しており、新幹線運転士になることを夢見ている。責任感が強く、「新幹線を好きな人は、誰一人として悪い人などいない」と信じている。', 11, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b135387-KN0yyOebJX8r.png', '10月17日', 'A', '佐倉綾音', NULL, 135387, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
