INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023017', 'AN2014', '切札勝太', '切札勝太は、アニメおよび漫画シリーズ『デュエルマスターズ』の2代目主人公であり、初期シーズンの主人公である切札翔武の後を継いだ人物である。彼は『ヴィクトリー』および『ヴァーサス』編の主人公を務めた。また、初期のアニメおよび漫画シリーズに登場した翔武の弟でもある。 兄が最後の戦いで死亡したとみなされた後、当初はカードゲーム『デュエルマスターズ』を嫌っていたが、兄のようにデュエルマスターになるため、長いデュエルの旅を歩んできた。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b263015-wjEdLMDXc7m4.jpg', NULL, NULL, '小林由美子', NULL, 263015, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023018', 'AN2014', 'ハイド', 'ハイドは幼い頃から上級生であり、「社会のエリート」の一人として知られていた。試験や学業、課外活動において優れた成績を収めており、あらゆる面で完璧主義者である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b277072-OUhX4joj06Bn.jpg', NULL, NULL, '土岐隼一', NULL, 277072, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023019', 'AN2014', '黄昏ミミ', 'ショウブの仲間の一人。当初はうっかり屋で、デュエリストとしても不器用な印象だったが、後にジュニア・デュエリスト・センターの「フォア・テンプル・ガーディアン」の2番目の守護者であり、実力者であることが明らかになった。 ミミは武術にも長けており、非常に頭脳明晰で力強い。主に「自然文明」のデッキを使用するが、あらゆる文明の「シールドトリガー」も駆使する。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b12270-739FPpgkPe1z.png', '3月3日', NULL, NULL, NULL, 12270, 'SUPPORTING', 14) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023020', 'AN2014', 'キャップ', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b188285-CBAGsJQYrwJ8.png', NULL, NULL, '市川太一', NULL, 188285, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023021', 'AN2014', '白凰', '白凰は、知性あふれるデュエリストであり、連勝記録が長いことで知られている。彼は、相手のシールドが1～2枚残るまで手加減して相手を翻弄し、そこから本気を出し、たった1ターンで形勢を一変させるという癖がある。（出典：デュエルマスターズWiki）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b272703-0WqDLnMKq5IO.jpg', '12月25日', NULL, NULL, NULL, 272703, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023022', 'AN2014', 'ヒミコ', '彼女は、ジェンドルが率いる「ファイブ・ガトルズ」の一員である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b277069-LUckJVR3UfSp.jpg', NULL, NULL, '諏訪彩花', NULL, 277069, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023023', 'AN2014', 'ゼーロジュニア', 'ゼロ・ジュニアは、ゼロとプラネッタの息子であり、謎めいた「黒のデュエリスト」として知られている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b277070-hrIVKpfk0ahr.jpg', NULL, NULL, '森田成一', NULL, 277070, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023024', 'AN2014', '黒城凶死郎', '自らを「邪悪な天才」と称し、シリーズを通じてショウブのライバルの一人である。その奇抜な長髪と全身黒のレザー衣装を、他のキャラクターたちからからかわれることもある。彼は「ダークネス・シヴィライゼーション」デッキを使用している。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b12271-lKcMZnIQ5vVP.png', '4月13日', NULL, NULL, NULL, 12271, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023025', 'AN2014', 'ボルツ', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b188273-S3ndA5s79EQ2.png', NULL, NULL, '白石稔', NULL, 188273, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023026', 'AN2015', 'ゾロリ', '物語の主人公であり、変装の達人であるゾロリは、亡き母を喜ばせるために「いたずらの王」になることを目指し、果てしない旅を続けるキツネだ。 自称「いたずらの天才」である彼は、自分に利益がある場合のみ他人を助けるが、実は心根は優しく、最終的には個人的な得になることなく他人の問題を解決してしまうことが多い。 普段は、江戸時代の賭博師を思わせる三つ八の笠と縞模様のマントを身に着けているが、肝心な場面ではゾロ風の衣装に着替える。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b20897-s0gI7S8dvfbg.png', NULL, NULL, '山寺宏一', NULL, 20897, 'MAIN', 32) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023027', 'AN2015', 'イシシ', 'ノシシの兄であり、ゾロリの弟子。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b175718-uOhL7Jz2Wvra.png', NULL, NULL, '愛河里花子', NULL, 175718, 'MAIN', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023028', 'AN2015', 'ノシシ', 'イシシの兄であり、ゾロリの弟子。ほくろがあることで、双子の弟と見分けることができる。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b175719-csn4dJQ2SUzM.png', NULL, NULL, 'くまいもとこ', NULL, 175719, 'MAIN', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023029', 'AN2015', 'コブル', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b175721-t1tHg4mr2gcR.png', NULL, NULL, '永塚拓馬', NULL, 175721, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023030', 'AN2015', 'ブルル', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b175724-upsC56bD9MOZ.png', NULL, NULL, '斉藤次郎', NULL, 175724, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023031', 'AN2017', 'ロイ・ヴァレンタイン', '十大魔王の一人。カガリが全盛期だった頃、その強さは彼女に匹敵していた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b238224-IqxxguSlGEYd.jpg', NULL, NULL, '水中雅章', NULL, 238224, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023032', 'AN2017', 'ヤムザ', 'ヤムザはクレイマン軍の総司令官であり、クレイマンの「ファイブ・フィンガーズ」の「ミドル・フィンガー」だった。（出典：『スライムに転生したあの時』ファンダム）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b226058-UYy1PHvgXupB.jpg', NULL, NULL, '広瀬裕也', NULL, 226058, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023033', 'AN2017', 'ヴェルザード', '「ホワイト・アイス・ドラゴン」としても知られるヴェルザードは、真のドラゴンの中で2番目に年長であり、ギィ・クリムゾンのパートナーである。世俗的な事柄にはほとんど関心を示さないヴェルザードは、普段は「ホワイト・アイス宮殿」で過ごし、そのオーラを放つことでアイス大陸を凍りつかせ続けている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b215593-oIJkitP71gCQ.png', NULL, NULL, '井口裕香', NULL, 215593, 'SUPPORTING', 77) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023034', 'AN2017', 'レイン', '「ブルー・プリモルディアル」であり、同じくプリモルディアルであるギィ・クリムゾンの配下。レインにその名前をつけたのはガイだった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b198042-Ip4WOoodIDIL.jpg', NULL, NULL, '幸村恵理', NULL, 198042, 'SUPPORTING', 38) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023035', 'AN2018', 'ノエ・アルシヴィスト', '種族：ヴァンパイア　職業：学生　パートナー：ヴァニタス　ノエは紳士的なヴァンパイアである。彼の物語は、「先生」から一通の手紙を受け取ったことから始まった。その手紙には、「ヴァニタスの『ボック』がパリで発見されたという噂があるため、ノエには直ちにパリへ飛んできてほしい」と書かれていた。 その後、「師」はノエに対し、「ヴァニタスの本」の真の正体を突き止めるよう、明確に命じた。', 19, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89835-xnAJMex6Uq0U.png', '9月28日', NULL, '石川界人', 187, 89835, 'MAIN', 3902) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023036', 'AN2018', 'ヴァ二タス', '種族：人間　職業：医師　パートナー：ノエ・アルシヴィスト（現在）、ダンテ（元）　ヴァニタスは、あの悪名高い吸血鬼からその名と『ヴァニタスの書』を受け継いだ、ごく普通の人間である。  彼は物事をあまり真剣に受け止めず、ほとんどいつも満面の笑みを浮かべている。彼の計画はたいてい無謀なものなので、行動は思考よりも感情に左右されることが多い。また、いたずらっぽい雰囲気を漂わせている。', 18, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89590-K3RdKR4VnYM4.png', '2月7日', NULL, '花江夏樹', 176, 89590, 'MAIN', 5937) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023037', 'AN2018', 'ルキウス・オリフラム', '種族：吸血鬼　職業：大公　パートナー：ジャンヌ　ルカは、大公の称号を継ぐために生まれた貴族出身の吸血鬼である。彼は女王と親しい間柄だが、まだその役割を担うには若すぎるため、叔父のルースヴェン卿が彼に代わって職務を遂行している。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b153506-DC5iKSUyp1Sp.png', '7月31日', NULL, '下地紫野', NULL, 153506, 'SUPPORTING', 38) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023038', 'AN2018', 'アストルフォ・グラナトゥム', '種族：人間　職業：シャスールのパラディン　彼は15歳でシャスール史上最年少のパラディンとなった人間であり、「吸血鬼はすべて本質的に邪悪である」という偏見に囚われ、信仰の名の下に吸血鬼の根絶に生涯を捧げてきた。   アストルフォは戦闘において精神異常的な行動を示す。女性と間違えられたといった些細な不満を理由に、人間も吸血鬼も区別なく虐殺することを楽しんでいる。彼の信念は、チャ', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b145998-2aV7SZGyWXBc.png', NULL, NULL, '村瀬歩', NULL, 145998, 'SUPPORTING', 211) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023039', 'AN2018', '先生', 'マスターはド・サド家の貴族の一員であり――ドミニク・ド・サドの祖父にあたる――多くの人々から恐れられている。（出典：Pandora Hearts Wikia）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b230438-6Cj7opQNCiFH.jpg', NULL, NULL, '石田彰', NULL, 230438, 'SUPPORTING', 37) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023040', 'AN2018', 'ノックス', 'ノックスは、コント・パークス・オルロックのもとで、兄のマーネと共に彼の専属警護として活動している吸血鬼である。（出典：The Mochizuki Wiki）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b242840-UmpjDA6l05dT.png', NULL, NULL, '清都ありさ', NULL, 242840, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023041', 'AN2018', 'ジョルジュ', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b246646-8KhsoXiKOW6i.jpg', NULL, NULL, '綿貫竜之介', NULL, 246646, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023042', 'AN2018', 'モロー', 'ドクター・モローは、望月ジュンの『ヴァニタスの手記』に登場する人間である。かつては吸血鬼の研究を行うためシャスールに雇われていた狂気の科学者だったが、自らも吸血鬼になることに執着するようになった結果、シャスールから追放された。   （出典：Mochijun Wiki）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b250994-OS8LOk0wcp7B.jpg', NULL, NULL, '堂坂晃三', NULL, 250994, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023043', 'AN2018', 'ダンテ', '種族：ダンピール　職業：情報ブローカー　パートナー： 	ヨハン（現在）、リシェ（現在）、ヴァニタス（元）  ダンテは、保険ブローカー兼何でも屋として活動するダンピールである。彼はしばしばヴァニタスと組んで、情報を売ったり、呪いを宿した吸血鬼を追跡するために協力したりしている。  ダンテはヴァ二タスと接する際、かなり気楽な態度をとる傾向がある――とはいえ、雇い主でありパートナーであるヴァ二タスにはすぐに苛立ちを覚える――特に、ヴァ二タスに「ハゲ」と呼ばれると。二人はよく互いに皮肉を言い合っている。', 18, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155328-odVkNctgtTp0.jpg', NULL, NULL, '木内太郎', NULL, 155328, 'SUPPORTING', 81) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023044', 'AN2018', 'ネーニア', 'ネーニアは、望月ジュンの『ヴァニタスの手記』に登場する、神秘的で幽玄な存在である。シャルラタンの一員として、ネーニアは仲間たちと共に、吸血鬼の潜在意識に侵入し、彼らの真の名を歪めることで「マルノメン」を植え付ける活動を行っている。 現時点では、ネーニアが何者なのか、またその行動の動機は何かについては明らかになっていない。', NULL, 'なし', 'https://s4.anilist.co/file/anilistcdn/character/large/b155248-TIy6LhGqTb4W.jpg', NULL, NULL, '名塚佳織', NULL, 155248, 'SUPPORTING', 16) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023045', 'AN2018', 'マキナ侯', '自動化に強い関心を持つ「クリムゾン・モン」の吸血鬼であり、マキナ侯爵領の当主でもある。上院議員として、マキナは吸血鬼たちの重要な政務にしばしば関与している。（出典：望月ウィキ）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b242847-7i00kb5agrkQ.png', NULL, NULL, '上田燿司', NULL, 242847, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023046', 'AN2018', 'マリア', 'マリアは、望月ジュンの『ヴァニタスの手記』に登場する人間のキャラクターである。シャスールとして、マリアは「吸血鬼は総じて邪悪である」という偏見にさらされてきたため、自らの信仰の名の下に、吸血鬼を根絶することに人生を捧げてきた。 最近、マリアは、シャスール・パリ支部に新しく配属されたローラン・フォルティスの指揮下で活動することになった。（出典：望月淳ウィキ）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b246645-5ogTSNaXyCOX.jpg', NULL, NULL, '宮本侑芽', NULL, 246645, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023047', 'AN2018', '仮面の男', 'ネーニアやペスト医師と共に、ムッシュ・スパイダーはマキナ侯の仮面舞踏会に潜入し、ネーニアが「マルノメン・ディソナンス」を仕掛けた呪い担い手たちによって来賓たちの注意がそらされている隙に、オリフラム大公としてのルカを暗殺しようと企てた。 ムッシュ・スパイダーは、シャルラタンの他のメンバーと同様、自らをヴァンパイアに変身させる手段を求めて呪いを持つ者たちを誘拐し続けているモローと結託していることが知られている。モローの研究室が発見されると、ムッシュ・スパイダーは……', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b256488-70rnxyv3CJc9.png', NULL, NULL, '中島卓也', NULL, 256488, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023048', 'AN2018', 'Riche', '種族：ダンピール　職業：情報ブローカー　パートナー：ダンテ、ヨハン　リシェは、情報ブローカーとして活動するダンピールである。同じくダンピールであるダンテやヨハンとよくタッグを組み、主に「呪いを背負った吸血鬼」に関連する事件を担当している。  リシェは学識豊かで情熱的な女性であり、興味のある話題になるとつい熱く語り込んでしまう。また、自分の知識を語りすぎたり、話が脱線しがちな癖を自覚しているため、話を終えた後はすぐに謝る傾向がある。彼女は非常に……', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155327-GJ5jjDuiglEh.png', NULL, NULL, '久間梨穂', NULL, 155327, 'SUPPORTING', 14) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023049', 'AN2018', '蒼月の吸血鬼　"ヴァニタス"', '「ブルー・モンのヴァニタス」は吸血鬼である。伝説によれば、彼らはブルー・モンの下で生まれ、『ヴァニタスの書』と「マルノメン」という病の、表向きの生みの親とされる。 その目的は、吸血鬼たちの「真の名」を汚すことで彼らを滅ぼし、自らの出生ゆえに生涯にわたって受けた迫害への復讐を果たすことだった。この力は子孫へと受け継がれ、すべての吸血鬼の終焉をもたらすと予言されていた。（出典：望月淳ウィキ）', NULL, 'なし', 'https://s4.anilist.co/file/anilistcdn/character/large/b236204-j2oLxMGsmdxY.png', NULL, NULL, '藤原夏海', NULL, 236204, 'SUPPORTING', 96) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023050', 'AN2018', 'ヴェロニカ・ド・サド', '「クリムゾン・モン」のヴァンパイアであり、サド伯爵の次女、ドミニク・ド・サドの姉にあたる。彼女は「ビーストイア」――すなわちファウスティナ女王の執行者――として活動しており、これは彼女が「ワールド・フォーミュラ」を改変して氷を生み出す能力を持つことに起因している。 ビーストイアとしての在任中、ヴェロニカは同じくビーストイアであるマキナ侯と親密な関係になった。（出典：望月ウィキ）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b242848-ZrwK3icUxCJM.jpg', NULL, NULL, '日笠陽子', NULL, 242848, 'SUPPORTING', 55) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023051', 'AN2018', 'ミハイル', '種族：人間　年齢：不明　ミシャは明るい笑顔を浮かべており、とても親しみやすく、洞察力にも富んでいるように見えるが、どこか少し危険な印象も受ける。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b181061-hBbyje40Grml.png', NULL, NULL, '小松未可子', NULL, 181061, 'SUPPORTING', 92) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023052', 'AN2018', 'ジャンヌ', '種族：吸血鬼　職業：シュヴァリエ（現在）、ボロー（過去）　ルカのシュヴァリエを務める吸血鬼。  ジャンヌはルカを激しく守り抜き、彼のシュヴァリエとしての職務を遂行する際には厳格さと力強さを漂わせているが、特に嫌っているヴァニタスの前では、慌てふためく傾向がある。 かつてボローだった過去のため、自分に向けられる優しさに慣れておらず、その結果、優しさを受けるとすぐに動揺してしまう。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89836-xLr4mkxojjc3.png', '4月21日', NULL, '水瀬いのり', NULL, 89836, 'SUPPORTING', 2435) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023053', 'AN2018', 'アメリア・ルース', 'アメリア・ルースは、ノエが「ラ・バレイン」号に乗ってパリへ旅をした際に出会った女性である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b236210-pZ3EJCSJNmqG.png', NULL, NULL, '下屋則子', NULL, 236210, 'SUPPORTING', 19) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023054', 'AN2018', 'クロエ・ダプシェ', '種族：吸血鬼　パートナー：ジャン＝ジャック　彼女はアプシェール侯爵の城に住む吸血鬼であり、その存在は隠されており、侯爵家では「隠された吸血鬼」として知られている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b146014-lhZxoInTtvNc.jpg', NULL, NULL, '釘宮理恵', NULL, 146014, 'SUPPORTING', 546) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023055', 'AN2018', 'ドミニク・ド・サド', '種族：ヴァンパイア　職業：貴族、王室近衛兵　ノエの幼なじみであり、ロイスとヴェロニカの妹。 父はサド伯爵、祖父はノエの師匠である。 彼女は軽薄で、遊び心があり、エネルギッシュで、魅力的な若い令嬢だ。初登場時には機械を使ってバラの花びらを撒き散らすほど、風格と優雅さを兼ね備えた歩き方をする。しかし、身近な人々を傷つけると疑う相手に対しては、躊躇なく手を出す。', 20, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b139553-Ni2xZ2U8aPii.jpg', '6月1日', NULL, '茅野愛衣', NULL, 139553, 'SUPPORTING', 1515) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023056', 'AN2018', 'ルイ・ド・サド', '彼はクリムゾン・モンの吸血鬼である。ロイスはヴェロニカやドミニク・ド・サドらと同じく、ド・サド家の貴族として生まれたが、ある事情により、ド・サド伯爵は彼を祖父のもとへ永久に預けた。 祖父のもとで暮らすうちに、ロイスはノエ・アルシヴィストと出会い、二人は親しい友人となった。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b146017-Ne3YSTuBIAI7.png', NULL, NULL, '島袋美由利', NULL, 146017, 'SUPPORTING', 342) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023057', 'AN2018', 'ルスヴン', '種族：ヴァンパイア　パートナー：ジャンヌ（元）　ルースヴェン卿は、上院議員として女王に仕えるヴァンパイアの領主である。その地位ゆえに、ルースヴェン卿は人間とヴァンパイアの戦争以来、一貫して重要な地位を占めてきた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155326-IZqGLZVEVuWh.png', NULL, NULL, '森川智之', NULL, 155326, 'SUPPORTING', 78) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023058', 'AN2018', 'ムル', 'ノエの飼い猫。ムルはイライラしている様子以外、他の感情を一切見せないが、ノエのことをとても大切に思っているようだ。よく影に潜んで、ノエを見守っている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b146015-TTM14WCYx74X.jpg', NULL, NULL, '小牧未侑', NULL, 146015, 'SUPPORTING', 429) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023059', 'AN2018', 'パークス・オルロック', 'パークス・オルロックは、人間と吸血鬼の戦争を経て、女王によって吸血鬼の代表に任命された人物である。吸血鬼に関連する活動を監視し、人間界と吸血鬼界のバランスを維持することを任務としている。（出典：望月ウィキ）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b242839-nwq2Mg2hk9O6.png', NULL, NULL, '山本格', NULL, 242839, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023060', 'AN2018', 'ローラン・フォルティス', '種族：人間　職業：シャスール隊長　彼は人間であり、「第六のパラディン」として知られ、シャスールとしての功績により、緑色の宝石「ジャスパー」を授与されている。  ローランドは、自身の信念に対する狂信的な姿勢を強調するような振る舞いをしばしば見せ、周囲の状況や、自分の言動が他者からどう受け止められているかには無頓着に見える。それにもかかわらず、彼は実際には非常に鋭敏で、さりげなく状況を自分の意のままに操る。また、真面目で有能、そして手強い敵でもあり、あらゆる手段を厭わず', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b139554-kD2aBERnYQPA.png', '8月19日', NULL, '河西健吾', NULL, 139554, 'SUPPORTING', 451) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023061', 'AN2018', 'ミナ', 'ミナは、望月ジュンの『ヴァニタスの手記』に登場するクリムゾン・モンの吸血鬼である。ミナは、ド・サド邸の隣町に住む少女で、ノエ・アルシヴィストやロイス、ドミニク・ド・サドと親しい友人になった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b249442-iIm9gHbIJyO9.png', NULL, NULL, '小牧未侑', NULL, 249442, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023062', 'AN2018', 'Johann', '種族：ダンピール　職業：情報屋　パートナー：ダンテ、リッチ　ヨハンは、情報ブローカーとして活動するダンピールであり、ダンテとリッチの仲間である。  ヨハンは、往々にして生き生きとした表情を見せ、からかいや軽妙な口調で話すなど、派手な性格が特徴だ。身体的な親しみを示す傾向があり、話している時に相手に体を擦り寄せたり、腕を回したりすることがある。しかし、追い詰められれば、ヨハンは仲間を守るために手段を選ばない。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155329-iTKKoVhnjfdw.png', NULL, NULL, '遊佐浩二', NULL, 155329, 'SUPPORTING', 70) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023063', 'AN2018', 'マーネ', 'マーネは、コント・パークス・オルロックのもとで、妹のノックスと共に彼の専属警護として働いている吸血鬼である。（出典：The Mochizuki Wiki）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b242842-B2ebjuIckBhR.png', NULL, NULL, '栗田樹', NULL, 242842, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023064', 'AN2018', 'オリヴィエ', '種族：人間　職業：シャスールのパラディン　オリヴィエは、シャスールとしてのローランドの不適切な振る舞いに常に苛立ちを覚え、神経が高ぶっている。彼はローランドに対してすぐに怒りを露わにし、ローランドのわがままをなだめることができないことに常に苛立ちを感じている。', 27, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155325-U1McQSCdYHof.png', '11月3日', NULL, '前野智昭', NULL, 155325, 'SUPPORTING', 114) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023065', 'AN2019', 'トア', '彼女は冒険者であり、リノンの姉である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b221534-4tU1s6ndJup9.png', NULL, NULL, '久保ユリカ', NULL, 221534, 'SUPPORTING', 58) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023066', 'AN2019', '巴の分体', '「巴のオフショット」は、異空間「アソラ」の監視や情報収集を支援するために生み出された、巴の無名の断片である。彼女は巴によって生み出された最初の断片であり、コモエの前身にあたる。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b271887-9o5EL1XZpMnF.png', NULL, NULL, '佐倉綾音', NULL, 271887, 'SUPPORTING', 46) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023067', 'AN2019', 'ラニーナ', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b225164-XOGL1QLVUL1X.png', NULL, NULL, '北守さいか', NULL, 225164, 'SUPPORTING', 15) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023068', 'AN2019', '月読命', '月読命は、モン族を統べる神であり、深澄真をこの世からあの世へと送り届ける役目を担った。また、月読命は真に力の加護を与え、後に女神によって真が彼女の世界の「荒野」へと放り出された際も、彼を助けた。  月読命は謙虚な性格で、それが正しいことだと考える限り、自分が助けられると信じる人々を助ける。他者を助ける際には、常に最善の結果が得られるよう全力を尽くすのが常である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b195917-7WqZbIFheC5z.png', NULL, NULL, '前野智昭', NULL, 195917, 'SUPPORTING', 87) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023069', 'AN2019', 'ハザル', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b225166-cuxDcqytGf25.png', NULL, NULL, '新祐樹', NULL, 225166, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023070', 'AN2019', 'ルイザ', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b225165-WLFxZFQXbzoA.png', NULL, NULL, '鎌倉有那', NULL, 225165, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023071', 'AN2019', 'アドノウ', 'アドノウはフォレスト・オーガであり、村の長老であるニルギストリの息子である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b264574-1BjhQlT0Ws2H.png', NULL, NULL, '武内駿輔', NULL, 264574, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023072', 'AN2019', 'リノン', '彼女はトアの妹です。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b221531-pt0SgCn0J0W1.png', NULL, NULL, '二ノ宮愛子', NULL, 221531, 'SUPPORTING', 24) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023073', 'AN2019', 'リディ', 'リディはミスティオ・リザードの一員であり、同種の中で最強かつ最高の戦士と称されている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b264575-MQi35yO9IKuf.png', NULL, NULL, '虎島貴明', NULL, 264575, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023074', 'AN2020', 'カンナカムイ', 'ドラゴン界出身のトールの友人。自分の世界から追放され、小林の家に身を寄せることになった。ドラゴンの基準では非常に若く、小学生に相当する。物語の後半では、小林の姓を名乗り、小学校の3年生として通学している。 当初、彼女は小林がトールを説得して留まらせ、自分には元の世界へ戻ってほしいと望んでいるのだと誤解していた。カンナのルーツや部族の衣装は、北海道の先住民族の文化にインスピレーションを得ており、cl', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b120974-cZHsjS8DX9WW.png', NULL, NULL, '長縄まりあ', NULL, 120974, 'MAIN', 6323) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023075', 'AN2020', '小林', '小林はコンピュータープログラマーであり、会社員でもある。彼女は「トール」という名のドラゴンと暮らしている。小林は冷静な態度を保っているが、友人や同僚の間では、心優しく頼りになる人物として見られている。 冷静で現実的な彼女は、ドラゴンの友人たちと接する際、常に理性の源となっている。しかし、酔うと騒がしくなり、攻撃的になる傾向があり、特にメイドへの興味が際立つ。酔った勢いでトールにわがままを強いることも厭わない。', 25, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b120969-dHJBVb3lB8iN.png', '4月23日', NULL, '田村睦心', NULL, 120969, 'MAIN', 3034) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023076', 'AN2020', 'トール', '所属：カオス　親族：ダモクレス（父）　トールは、人間の少女に変身する能力を持つ雌のドラゴンである。小林に救われた後、彼女に恋心を抱き、メイドとして仕えることを決意した。  カオス・ドラゴンとして、トールは人間を憎むように育てられ、破壊のことしか考えない獰猛で危険な悪の勢力となるはずだった。しかし、小林と出会ったことで、すべてが変わった。今では、出会うすべての人間に対して明るく親切に接しているが、ただし、', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b120970-knjWLdlQIs1y.jpg', NULL, NULL, '桑原由気', NULL, 120970, 'MAIN', 5548) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023077', 'AN2020', 'イルル', 'イルルはカオス陣営に属するメスのドラゴンである。当初はトールを滅ぼすために小林の世界にやって来たが、その後、小林をトールから引き離そうとする。しかし、心変わりしてからは、小林のもとで3匹目のドラゴンとして暮らすようになった。彼女は思いやりのある性格で、子供たちが大好きだ。 その後、その性格が功を奏し、後継者を探していた老婆から、お菓子屋の経営を引き継ぐことになった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b133060-GXT0mBzJIOlT.jpg', NULL, NULL, '嶺内ともみ', NULL, 133060, 'MAIN', 979) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023078', 'AN2020', '真ヶ土翔太', '家族：真ヶ土氏（父）、真ヶ土沙織（母）　真ヶ土翔太は、現代社会に生きる魔法使いの家に生まれた少年である。彼は、悪魔を召喚しようとするほど、秘術に関する十分な知識を持っていることが示されている。 ルコアは翔太が作り出した召喚のポータルから現れ、彼と一緒に暮らし始める。翔太は小学5年生の男子で、髪も瞳も紫色をしている。前髪は眉毛をはるかに下回る長さだ。その外見は、どこか中性的な印象を与える。翔太は物静かで、', 10, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b120973-lNsOIwMrH8xo.png', NULL, NULL, '石原夏織', NULL, 120973, 'SUPPORTING', 289) ON CONFLICT DO NOTHING;
