INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023081', 'AN2020', '滝谷真', '小林の同僚で、当初トールからは小林の恋のライバルだと思われていたが、実際にはただ小林とメイドの話をするのが好きなオタクに過ぎない。小林は毎年、コミケの期間中、彼のブース設営を手伝っている。', 24, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b120976-qUDSgLQ61tGQ.png', '5月5日', NULL, '中村悠一', NULL, 120976, 'SUPPORTING', 278) ON CONFLICT DO NOTHING;
