INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023083', 'AN2020', 'クロエ', '彼女はアメリカ人で、カンナが小林と喧嘩をした際に、カンナと親しくなった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b247504-1UwtaxGpKcAh.png', NULL, NULL, '上坂すみれ', NULL, 247504, 'SUPPORTING', 48) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023084', 'AN2020', '才川ジョージー', 'Relatives: Riko Saikawa (younger sister), unnamed parents  Georgie Saikawa is the older sister of Riko Saikawa. Her real name is Nae Saikawa (才川苗). She likes to pretend to be a housemaid.  Georgie wears an orange polka-dot maid outfit with a white apron. She also has a white cap and has her red hair in twin-pigtails. Her stockings are black striped.  Georgie is a sweet and gentle lady. She always supports Riko and her family. She seems to know a lot about maids and has a huge passion for them. S', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b120978-rLBVr3LBNeul.jpg', '5月10日', NULL, '後藤邑子', NULL, 120978, 'SUPPORTING', 120) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023085', 'AN2020', 'ケツァルコアトル', '所属：傍観者派　「ルコア」という愛称で親しまれるケツァルコアトルは、かつての竜の女神であり、トールの旧友である。呪われた酒を飲み、スキャンダラスな不倫関係に陥ったことをきっかけに、その座から追放された。 「スペクテーション」派の一員として、彼女はドラゴンや神々に関わるいかなる出来事にも干渉しない。彼女は本作シリーズにおいて、群を抜いて最強のドラゴンである。ケツァルコアトルはのんびりとして気ままな性格で、笑顔を見せないことはめったにない。彼女は賢く、親切で、人を慈しむ心を持っており、', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b120975-oOyfRbMSpSpy.png', NULL, NULL, '髙橋ミナミ', NULL, 120975, 'SUPPORTING', 1799) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023086', 'AN2020', '会田タケト', '会田タケトは、イルルが最終的に就職することになった菓子店のオーナー、会田さんの孫です。当初はイルルを疑っていましたが、彼女の優しい一面を知ったことで、二人はやがて友人同士になります。 彼は、わざわざ手間をかけてでも手を差し伸べようとするなど、協力的で親切な人物として描かれている。', 16, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b236990-454yZjD0OPdp.jpg', NULL, NULL, '下野紘', NULL, 236990, 'SUPPORTING', 66) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023087', 'AN2020', 'エルマ', '所属：ハーモニー  エルマは、トールが所属する「カオス」の対立勢力である「ハーモニー」に属する雌のドラゴンである。彼女は、自分の世界に戻ることができないと悟った後、人間の偽名として「エルマ・ジョイ」という名を採用した。 エルマは、人間界で一人暮らしをしているメインキャストの中で唯一のドラゴンである。エルマは通常、短い黒髪、豊かな胸、青い瞳、そして長い螺旋状のユニコーンのような角（自由に隠すことができる）を持つ人間の女性の姿をとっている。アニメや『エルマのオフ』では', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b120977-x50lrAuIAsHE.png', NULL, NULL, '高田憂希', NULL, 120977, 'SUPPORTING', 1903) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023088', 'AN2020', 'クレメネ', 'ハーモニー派に属する謎めいたドラゴン。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b238297-pbrsgf2Es6KB.png', NULL, NULL, '杉田智和', NULL, 238297, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
