INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023091', 'AN2020', '女性教師', 'カンナとリコの先生。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b222745-QkYp6NiQDN8q.png', NULL, NULL, '後藤邑子', NULL, 222745, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023092', 'AN2020', 'ファフニール', 'トールの古くからの友人であり、人間に対して強い不信感を抱いている雄のドラゴンである。そのため、初期の登場シーンでは、トールの行動や理想の大半に疑問を呈していた。 その冷徹な態度や軽蔑的な心構えなど、名前の由来となった人物の特徴をいくらか受け継いでいる。人間の姿では、長い黒髪と赤い瞳を持つ、気品のある若者として現れる。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b120971-7XdpFZNKMBuM.png', NULL, NULL, '小野大輔', NULL, 120971, 'SUPPORTING', 1249) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023093', 'AN2020', '谷菜', '谷菜は小林の隣人の一人です。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b209896-rbrdDJWx1wYC.png', NULL, NULL, '高橋伸也', NULL, 209896, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
