INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023095', 'AN2020', '専務', 'ショウタの父親であり、小林の会社の代表取締役。彼は魔術師である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b248474-ZKQZMEc5ymIq.png', NULL, NULL, '家中宏', NULL, 248474, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023096', 'AN2020', '才川リコ', '親族：才川ジョージー（姉）　才川リコは、カンナの友人であり、小学校の同級生である。彼女とカンナが身体的に接触するたびに、至福のあまり顔面を真っ赤に染め、額がテカテカになるというお決まりのギャグがある。  一見すると、リコは威張り屋で意地悪そうに見えるが、時間が経つにつれて、カンナに対する態度からもわかるように、より優しい一面を見せている。また、小林のような人に対しては、当初小林をカンナの母親と勘違いしていたものの、非常に礼儀正しく振る舞う。彼女はカンナに片思いしており、', 9, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b120972-fEzG6QIFQnXp.png', '8月21日', NULL, '加藤英美里', NULL, 120972, 'SUPPORTING', 462) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023097', 'AN2020', '曽根', '曽根さんは、小林さんの近所に住んでいる一人です。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b209895-xD9clnjbBPbt.png', NULL, NULL, '高橋伸也', NULL, 209895, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023098', 'AN2020', '黒田', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b244895-PZQf01FHavlo.png', NULL, NULL, '河村梨恵', NULL, 244895, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023099', 'AN2020', 'ダモクレス', 'ダモクレスはトールの父であり、「死の皇帝」として知られ、本作に登場する最強のドラゴンの一人と見なされている。ダモクレスは冷酷で厳格であり、人間を憎み、彼らを劣った存在であり邪悪であると見なしている――この信念を、彼はトールにも植え付けようとした。 しかし、他のカオスドラゴンとは異なり、彼はドラゴンが地球の人間を殺すことを禁じる「不干渉の掟」を尊重している。とはいえ、怒りを露わにすると、小林を襲い、彼女を死の淵に追い込むと脅すこともある。それにもかかわらず、彼は娘を大切に思っている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b172721-syVtsR9ZICbq.png', NULL, NULL, '菅生隆之', NULL, 172721, 'SUPPORTING', 19) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023100', 'AN2021', 'リーシア・エルフリーデン', '種族：人間　リーシア・エルフリーデンは、『現実主義勇者の王国再建記』シリーズの女性主人公である。彼女はエルフリーデンの王女であり、前王アルベルト・エルフリーデンの娘であるほか、ソーマの仮の婚約者として、フレイドニアの初代正妃でもあった。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n133336-lB9x2ceRcDfp.jpg', NULL, NULL, '水瀬いのり', NULL, 133336, 'MAIN', 573) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023101', 'AN2021', '相馬一也', '相馬一也は、『i』『現実主義勇者の王国再建記』</i>シリーズの男性主人公である。彼は地球人であり、英雄として異世界に召喚されたが、前王アルベルト・エルフリーデン前王の的確な布告により、エルフリーデン王国の王となった。一也が王位を簒奪したと考える民衆の反乱を避けるため、王は娘を一也に嫁がせた。一也は他者に自己紹介する際、日本の姓の形式を用いて', 19, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n133333-53OfUScBG41p.png', NULL, NULL, '小林裕介', NULL, 133333, 'MAIN', 329) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023102', 'AN2021', 'アイーシャ・ウドガルド', '「神に守られた森」のダークエルフ族長の娘。武術大会で優勝した後、才能ある者たちの集いにおいて発見された5人のうちの1人。 ソーマがダークエルフたちに森を救う方法を教えた後、彼の護衛を務めるようになり、次第に彼に深く恋に落ちる。非常に意欲的で忠実なため、よく動物に例えられる。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n133334-PKS9Bt9CeQpL.jpg', NULL, NULL, '長谷川育美', NULL, 133334, 'MAIN', 282) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023103', 'AN2021', 'ゲオルグ・カーマイン', '種族：ライオン・ビーストマン   ゲオルグ・カーマインは、『現実主義勇者の王国再建記』シリーズの登場人物である。一週間戦争以前は、エルフリーデンの陸軍司令官であり公爵を務めていた。  （出典：現実主義勇者の王国再建記 Wiki）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n133341-NmGIzUwoTgiv.png', NULL, NULL, '楠大典', NULL, 133341, 'SUPPORTING', 29) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023104', 'AN2021', 'エリシャ・エルフリーデン', '種族：人間　エリシャ・エルフリーデンは、『現実主義勇者の王国再建記』シリーズの登場人物である。彼女は、エルフリーデン王国第12代王の死後に起きた王位継承危機において、エルフリーデン王家の最後の生存者として、同王国の正統な王位継承者であった。 彼女は後に「アルバート」と結婚し、彼に自身の姓を名乗らせるとともに、エルフリーデン王国第13代国王の座を譲った。  （出典：現実主義勇者の王国再建記 Wiki）', 30, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b133339-fbwbEqZaYGhX.png', NULL, NULL, '井上喜久子', NULL, 133339, 'SUPPORTING', 50) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023105', 'AN2021', '和也の祖父', '亡くなる前に孫に最期の言葉を残したカズヤの祖父', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b242046-Flkh0kryb1IK.png', NULL, NULL, '野瀬育二', NULL, 242046, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023106', 'AN2021', 'ユノ', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b262756-nNli1Yl0VOGe.png', NULL, NULL, '朝井彩加', NULL, 262756, 'SUPPORTING', 28) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023107', 'AN2021', 'エクセル・ウォルター', '彼女は、カルラ・バルガスとジュナ・ドーマの祖母であり、かつて空軍司令官を務めたカストール・バルガスの義母でもある。現在は国防軍の最高司令官を務めている。', 500, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b214660-HihQJwEjpxB9.png', NULL, NULL, '堀江由衣', NULL, 214660, 'SUPPORTING', 86) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023108', 'AN2021', 'アルベルト・エルフリーデン', 'アルバートはエルフリーデンの元国王であり、そのため最高機密に関する知識を多少持っている。アルバートは親切で思いやりのある人物だが、決断力に欠け、指導者としては弱々しい。彼は家族を愛し、国を深く思いやっているが、その不適切な指導と優柔不断さにより、エルフリーデン王国は衰退してしまった。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b237299-02DE0veVrZML.png', NULL, NULL, '麦人', NULL, 237299, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023109', 'AN2021', 'ハルバート・マグナ', 'ハルバートはグレイヴ・マグナの息子であり、カエデ・フォキシアの幼なじみである。当初、ハルバートは短気で世間知らずだったが、後に、英雄から王となった彼の統治手法や革新、とりわけ導入された新しい食料を評価するようになる。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b246567-Xp6oeIt87Gqb.png', NULL, NULL, '八代拓', NULL, 246567, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023110', 'AN2021', 'ジュナ・ドーマ', 'ジュナ・ドーマは、『現実主義勇者の王国再建記』シリーズの女性主人公の一人である。彼女はエクセル・ウォルターの孫娘である。', 19, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n133337-EPxGDgelQBlI.png', NULL, NULL, '上田麗奈', NULL, 133337, 'SUPPORTING', 314) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023111', 'AN2021', 'カストール・バルガス', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b214658-opBktRdm17a4.png', NULL, NULL, '福山潤', NULL, 214658, 'SUPPORTING', 16) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023112', 'AN2021', 'グレイヴ・マグナ', 'グレイヴ・マグナは、王国に忠誠を尽くす、厳格で規律正しい人物である。彼はハルバートの父親である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b246568-yPi4P2dXm8aG.png', NULL, NULL, '山本兼平 ', NULL, 246568, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023113', 'AN2021', 'ジャンヌ＝ユーフォリア', '年齢：約17歳　ジャンヌ＝ユーフォリアは、『現実主義勇者の王国再建記』シリーズに登場する常連キャラクターである。彼女はグラン・カオス帝国の皇太子であり、軍司令官であるほか、現皇后マリア・ユーフォリアの妹でもある。  （出典：現実主義勇者の王国再建記 Wiki）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n133340-KomdNl7C72cy.png', NULL, NULL, '石川由依', NULL, 133340, 'SUPPORTING', 73) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023114', 'AN2021', 'ギャツビー・コルベール', 'コルベールはかつてアミドニアの財務大臣を務め、現在はフリードニアの財務大臣である。彼は内気で、すぐに怯んでしまう性格と見られている。自信に欠ける面はあるものの、かなりの常識を備えている。 しかし、自国民のためであれば、戦士たちでさえ恐れるガイウスやゲオルグのような人物に対しても、臆することなく本音を述べる覚悟がある。ゲオルグも、初対面時に彼を「将来有望な若者」と称賛したほどだ。ロロア・アミドニアからは、信頼できる部下として見なされている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b246569-ghifkJ7t74xD.png', NULL, NULL, '山下誠一郎', NULL, 246569, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023115', 'AN2021', 'ハクヤ・クオンミン', 'ハクヤ・クオンミンは、『現実主義勇者の王国再建記』シリーズに登場する常連キャラクターである。現在はフレイドニア王国の首相を務めている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n133335-8UW3OkykJmFL.jpg', NULL, NULL, '興津和幸', NULL, 133335, 'SUPPORTING', 90) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023116', 'AN2021', 'マリア・ ユーフォリア', '彼女はジャンヌ＝ユーフォリアの姉である。現在はグラン・カオス帝国の女帝であり、同帝国で初めて即位した女性である。', 19, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b218413-2g3qJI1IYrkx.png', NULL, NULL, '金元寿子', NULL, 218413, 'SUPPORTING', 55) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023117', 'AN2021', 'ルドウィン・アークス', 'ルドウィンは、聡明でカリスマ性あふれる貴族である。傑出した騎士として、カズヤが彼と初めて出会った当時、王室近衛隊の隊長を務めていた。エルフリーデンの貴族でありながら、幼なじみを経済的に支えるため、質素な生活を送っている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b237301-FhZAWvyJNA9G.png', NULL, NULL, '古川慎', NULL, 237301, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023118', 'AN2021', 'ボーダン・ウドガルド', '「神に守られた森」のダークエルフの首領であり、ロブソール・ウドガルドの兄弟、そしてアイーシャ・ウドガルドの父である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b246570-AO3gofG9aYwE.png', NULL, NULL, '江越彬紀', NULL, 246570, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023119', 'AN2021', 'カルラ・バルガス', '彼女はカストール・バルガスの娘であり、エクセル・ウォルターの孫娘、そしてリーシア・エルフリーデンの友人である。かつてはバルガス公国空軍の副司令官を務めていたが、現在は相馬一也とリーシアの奴隷兼メイドとなっている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b214655-u0U3jZHFYGLC.png', NULL, NULL, '愛美', NULL, 214655, 'SUPPORTING', 90) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023120', 'AN2021', 'ロロア・アミドニア', '種族：人間　ロロア・アミドニアは、『現実主義勇者の王国再建記』シリーズの女性主人公の一人である。彼女はガイウス・アミドニアの娘であり、ユリウス・アミドニアの妹である。（出典：現実主義勇者の王国再建記 Wiki）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n133342-pJC7sUq7cmn3.png', NULL, NULL, '市道真央', NULL, 133342, 'SUPPORTING', 171) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023121', 'AN2021', '神官長', '相馬一也を召喚したアルベルト・エルフリーデンの配下の首席司祭。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b237302-WPdZDSQCX5V0.jpg', NULL, NULL, '前田弘喜', NULL, 237302, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023122', 'AN2021', 'セバスチャン・シルバディア', 'セバスチャンは、紳士服店「ザ・シルバー・ディア」の店主である。また、ロロア・アミドニアの親友でもある。ロロアと同様、セバスチャンも経済やビジネスに非常に長けている。さらに、情報収集の腕も非常に優れている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b246571-tE0AezoPSu0Y.png', NULL, NULL, '中野泰佑', NULL, 246571, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023123', 'AN2021', 'ポンチョ・パナコッタ', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b214656-14nUxWYEYR2v.png', NULL, NULL, '水中雅章', NULL, 214656, 'SUPPORTING', 32) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023124', 'AN2021', 'ユリウス・アミドニア', 'ユリウス・アミドニア（後にジュリアス・ラスタニアと改名）は、併合前のアミドニアの追放された非公式な統治者である。彼は故ガイウス・アミドニアの息子であり、ロロア・アミドニアの兄にあたる。 その後、彼はラスタニア王家に婿入りし、その姓を名乗るようになった。ユリウスは虚栄心が強く、自己中心的な人物であり、偉大さと征服への野望を抱いていた。 父ほど短気ではなかったものの、同じ理想を共有していた。しかし、国を統治する能力は著しく欠けており、彼は……', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b237297-cfQlKohfeKb7.png', NULL, NULL, '野島健児', NULL, 237297, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023125', 'AN2021', 'マルクス', '種族：ハーフエルフ　かつてエルフリーデン王国の首相を務めていたが、ハクヤ・クオンミンにその座を譲り、現在は元統治者であるアルベルト・エルフリーデンとエリシャ・エルフリーデンの侍従長を務めている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b237304-FpF8kUImT9Dp.png', NULL, NULL, '青山穣', NULL, 237304, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023126', 'AN2021', 'セリィナ', 'セリィナは、現在パルナム城の首席メイドであり、リシアの専属付き人である。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b247727-ybKiqqkAT8Cz.png', NULL, NULL, '貫井柚佳', NULL, 247727, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023127', 'AN2021', 'トモエ・イヌイ', '種族：ミスティックウルフ　トモエ・イヌイは、『現実主義勇者の王国再建記』シリーズのレギュラーキャラクターである。（出典：現実主義勇者の王国再建記 Wiki）', 10, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n133338-boVMSdhJ8qrG.png', NULL, NULL, '佳原萌枝', NULL, 133338, 'SUPPORTING', 133) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023128', 'AN2021', 'ガイウス・アミドニア', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b214657-ZZGBs00VS53a.png', NULL, NULL, '稲田徹', NULL, 214657, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023129', 'AN2021', 'カエデ・フォキシア', 'カエデは思いやりがあり、特にハルバートに対しては細やかな気遣いができる人物だ。ハルバートとは異なり、彼女は行動を起こす前に状況を冷静に見極めることができ、多くの場合、結果を事前に予測している。指揮官として、部下が万全の準備を整えられるよう、彼らには厳しい態度で接している。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b240243-StNWGsZtsKCM.png', NULL, NULL, '高野麻里佳', NULL, 240243, 'SUPPORTING', 38) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023130', 'AN2021', 'スール', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b253410-JrMfSQ9LrHrV.jpg', NULL, NULL, '小林千晃', NULL, 253410, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023131', 'AN2022', 'サガ・ハヤテ', 'サガ家の長男であり、ユバの旧知の仲である。王国の徴税官として働いている。ユバの家に一時滞在していた際、ルリに恋心を抱くようになった。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b244721-juDMnGerDJH3.png', NULL, NULL, '小林千晃', NULL, 244721, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023132', 'AN2022', 'ガルシア・フォンティーヌ', '彼は、ベルトラム王国の貴族社会における第三の勢力である王党派に属し、ベルトラム王立アカデミーの代理院長を務める、現フォンテーヌ公の前任者である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b223507-OxJuSaynH83v.png', NULL, NULL, '手塚ヒロミチ', NULL, 223507, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023133', 'AN2022', 'サガ・ゴウキ', '佐賀家の当主であり、コモモ、ハヤテ、そして他の2人の息子の父。カラスキ王国および近隣諸国において、最強の侍として称えられている。かつては、リオの両親であるアヤメとゼンの護衛兼同僚を務めていた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b218156-8AXwrZgaewRV.jpg', NULL, NULL, '大泊貴揮', NULL, 218156, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023134', 'AN2022', 'シン', 'サヨの兄であり、ルリの幼なじみ。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b244722-0KUhcGwWSrMa.png', NULL, NULL, '増田俊樹', NULL, 244722, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023135', 'AN2022', 'サガ・カヨコ', 'ゴキの妻であり、コモモ、ハヤテ、そして他の2人の息子の母。ゴキと同様、かつてはリオの母であるアヤメのボディーガードを務めており、リオの父であるゼンとも面識があった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b218155-w2If0ERP37Wi.jpg', NULL, NULL, '山本希望', NULL, 218155, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023136', 'AN2022', 'クリスティーナ・ベルトラム', 'ベルトラム王国の第一王女であり、王位継承順位第一位である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b197376-Pb1QQvOwix0w.png', NULL, NULL, '鈴代紗弓', NULL, 197376, 'SUPPORTING', 83) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023137', 'AN2022', 'ドリュアス', 'スピリット・フォーク・ビレッジのハイクラスな精霊。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b212154-GaVJxAU9MQeF.jpg', NULL, NULL, '小坂井祐莉絵', NULL, 212154, 'SUPPORTING', 45) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023138', 'AN2022', 'ルリ', 'ユバの孫娘。幼い頃に両親を亡くし、それ以来、ユバに一人で育てられてきた。 彼女は村の誰とでも親しく接しているが、サヨとシンだけは例外だ。彼らは幼い頃、ユバから共に精霊術を学んでいた時期に彼女と多くの時間を過ごし、同じ孤児同士としてよく一緒に遊んでいたからだ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b212325-9pVSWsMSxzGL.jpg', NULL, NULL, '小見川千明', NULL, 212325, 'SUPPORTING', 68) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023139', 'AN2022', 'カラスキ・シズク', '現在、カラスキ王国の女王であり、', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b221424-7Lts1tIIgZUd.png', NULL, NULL, '大地葉', NULL, 221424, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023140', 'AN2022', 'ユバ', '彼女の村の長であり、周辺の村々でも「人脈が最も広い人物」として知られる、村随一の薬剤師。両親が亡くなって以来、ルリの面倒を見てきたルリの祖母。ルリを除けば、他の親戚のほとんどはすでに他界している。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b212324-tG10I4C2RDif.jpg', NULL, NULL, '大原さやか', NULL, 212324, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023141', 'AN2022', 'ウズマ', '精霊の村の戦士長であり、戦闘指導者。リオに敗れた後、彼の友人であり弟子となった。リオが「ふさわしいライバル」と評した、村の戦士たちの中で唯一の存在である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b244726-KwWu0odTdXLf.png', NULL, NULL, '大地葉', NULL, 244726, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023142', 'AN2022', 'サガ・コモモ', 'ハヤテと、名前が明かされていない2人の息子に続いて、ゴキとカヨコの4人目の子供として生まれた。彼女は、王国で、ひょっとすると八雲一帯でも最強と謳われる父を慕って育ち、かつては「ゴキに勝てない男とは結婚しない」と公言していたが、リオが現れるまではそう思っていた。 それ以来、彼女は彼を憧れの眼差しで見つめ続けている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b212323-dtUuJ50VTe0q.jpg', NULL, NULL, '福緒唯', NULL, 212323, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023143', 'AN2022', 'アルフレッド・エマール', 'ベルトラム王国王室近衛隊の隊長。王国で最も強い者に与えられる「王の剣」の称号を持つ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b197378-dvkv8JAxDwAR.png', NULL, NULL, '浜田賢二', NULL, 197378, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023144', 'AN2022', 'カラスキ・ホムラ', '現在、カラスキ王国の王であり、', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b221423-TV3xUSdEmFZv.png', NULL, NULL, '手塚ヒロミチ', NULL, 221423, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023145', 'AN2022', 'ヴァネッサ・エマール', 'ヴァネッサ・エマールは、クリスティーナ王女の護衛を務める騎士であり、王室近衛兵でもある。彼女はアルフレッドの妹である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b223505-WizvfzQGPGtY.png', NULL, NULL, '河瀬茉希', NULL, 223505, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023146', 'AN2022', 'サヨ', 'ルリの幼なじみであり、シンの妹。幼い頃に両親を亡くしたが、近所の人々の助けを借りて、兄と共に何とか生活してきた。二人ともルリと同じくらい霊術の才能に恵まれており、ユバの指導のもと、ルリと共に修行を積んできた。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b212326-v9PS3TuKakb7.jpg', NULL, NULL, '久保ユリカ', NULL, 212326, 'SUPPORTING', 96) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023147', 'AN2023', '長良', '特徴：　長良は長い髪をしていて、他のクラスメートと同じ制服を着ている。長良は周囲の環境にうんざりしており、生きるのを諦めたい気持ちになっている。家族とのコミュニケーションに苦労しており、学校の生徒たちは彼に距離を置き、冷たい態度で彼を見つめている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b225128-7bIAkutDY0rk.png', NULL, NULL, '市川蒼', 170, 225128, 'MAIN', 810) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023148', 'AN2023', '希', '能力：　希は強い意志の持ち主で、どんなに困難な状況にあっても決して屈することはない。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b225129-URHeLyLOu3lP.png', NULL, NULL, '大西沙織', 165, 225129, 'MAIN', 530) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023149', 'AN2023', 'ラジダニ', '周囲の世界に魅了されたラジダニは、学生たちがなぜ、どのようにして道に迷ってしまったのかを、論理的かつ計算高く調査する。彼はほとんどの人と円滑に付き合え、調査結果を誰にでも率直に報告する。ラジダニは、本質的に合理的で科学的、そして決断力に富んでいる。  ラジダニは「ポケットコンピュータ」の能力を持ち、それを使ってプログラムを設計し、それを現実のものにすることができる。この能力を用いて、彼はこの世界の真実を解明するのに役立つ多くの便利な「ガジェットやツール」を作り出している。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b235446-MNs9DskivL2L.png', NULL, NULL, '後藤ヒロキ', NULL, 235446, 'MAIN', 523) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023150', 'AN2023', '瑞穂', '特徴： 高校3年生で、祖母の飼い猫である「とら」「げん」「さくら」の3匹を、いつもトートバッグに入れて持ち歩いている。瑞穂の性格は、テンポが速く、おてんばで、正直だ。周囲の人々とは積極的に関わろうとせず、孤立している。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b225130-uszblgnvpsgF.jpg', NULL, NULL, '悠木碧', 162, 225130, 'MAIN', 1312) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023151', 'AN2023', '朝風', '能力：重力を操る能力　漂流事件に巻き込まれた反抗的な少年。生徒会による統制に反対している。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b225131-qDAWwhXpYicX.png', NULL, NULL, '小林千晃', NULL, 225131, 'MAIN', 87) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023152', 'AN2023', '明星', '魅力的な顔立ちと大人びた性格の少年。行方不明事件の後、彼はすぐにグループのリーダーを指名して主導権を握ろうとする。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b235443-hrIHNp5KF0nP.png', NULL, NULL, '内藤有海', NULL, 235443, 'MAIN', 63) ON CONFLICT DO NOTHING;
