INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023171', 'AN2023', 'さくら', '瑞穂が飼っている3匹の猫のうちの1匹で、もともとは祖母が飼っていたものです。さくらはその3匹の中で一番小さい猫です。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b247601-i6KGpg735fXq.jpg', NULL, NULL, '津田匠子', NULL, 247601, 'SUPPORTING', 30) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023172', 'AN2024', '佐木咲', '佐木咲は向井直也の彼女である。彼女は、直也のもう一人の彼女である皆瀬渚とともに、『カノジョも彼女』シリーズのヒロインの一人である。  咲は、明るく元気な女の子だとされている。また、感情的で、純真で、物忘れが激しいところもある。スポーツが得意で、誰に対しても、特に少しやりすぎな行動をとる向井直也に対しては、率直に攻撃的になることもある。', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b162886-jHVw29KuITzO.png', '4月13日', NULL, '佐倉綾音', 161, 162886, 'MAIN', 833) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023173', 'AN2024', '水瀬渚', '水瀬なぎさは、向井直也の恋人である。彼女は『カノジョも彼女』シリーズの女性主人公の一人であり、直也のもう一人の恋人である佐木咲と並んで描かれている。なぎさは、落ち着きがあり、思いやりがあり、謙虚な少女として描かれている。特に特技はないようで、クラスメートの平均レベルを維持するために常に努力している。 思いやりのある性格であるにもかかわらず、向井直也との関係を維持するためなら、カンニングに至るような卑怯な手段にも手を染めることがある。渚には、ある能力が欠けていることが示されている。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b162885-8teW99MU3TSJ.png', '3月18日', NULL, '和氣あず未', 155, 162885, 'MAIN', 781) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023174', 'AN2024', '星崎理香', '星崎リカ（別名：ミリカ）は、MeTubeで人気のバーチャルコンテンツクリエイターであり、直也の好意を執拗に追い求めている。彼女は、佐木咲や直也と同じ高校に通う高校1年生である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b182020-Xc5ifcZlsIcV.png', '8月1日', NULL, '竹達彩奈', NULL, 182020, 'MAIN', 647) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023175', 'AN2024', '向井直也', '直也は、非常に率直で社交的な人物だと見なされている。その率直な性格は極めて顕著で、何の遠慮もない。大勢の人の前であろうと、彼女たちと二人きりの時であろうと、状況にかかわらず直也は常に率直である。 さらに、直也は少し自己中心的な面もあると言える。というのも、彼は最初の恋人である佐木咲に対し、彼女と二股をかけて、水瀬なぎさと付き合ってもいいかと公然と尋ねたからだ。二股という振る舞いにもかかわらず、直也は関係を維持するために最善を尽くそうとする。', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b162887-d4IfJSmpGnxr.jpg', '12月31日', NULL, '榎木淳弥', 170, 162887, 'MAIN', 212) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023176', 'AN2024', '桐生紫乃', 'シノは佐木咲の親友だ。二人は同じクラスで、同じ放課後の部活動にも所属している。シノは真面目で思いやりのある性格で、学業も優秀で、学校でトップの成績を収めている。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b195567-1uM7mDi0pFSk.png', '11月25日', NULL, '高橋李依', NULL, 195567, 'MAIN', 1068) ON CONFLICT DO NOTHING;
