INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023184', 'AN2026', '鹿苑寺貫之', '橋場恭也の親友。のんびりした性格だが、脚本を書くことに関しては天才だ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b197114-Tl922dOmNIbR.jpg', NULL, NULL, '石谷春貴', NULL, 197114, 'MAIN', 57) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023185', 'AN2026', '小暮奈々子', '彼女はシェア・ホース・キタヤマの入居者で、非常に才能のある歌手です。その見た目とは裏腹に、純真で思いやりのある人です。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b197115-FaeEgzV9q5If.jpg', NULL, NULL, '愛美', NULL, 197115, 'MAIN', 306) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023186', 'AN2026', '橋場恭也', 'このシリーズの主人公。ある不可解な出来事により、10年前にタイムスリップしてしまう。京也は極めて冷静な性格の持ち主だ。彼は「プラチナ世代」として知られる才能あふれる人々から大きな影響を受けている。', 28, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b197117-PhryspkJdlgH.jpg', '5月25日', NULL, '伊藤昌弘', NULL, 197117, 'MAIN', 146) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023187', 'AN2026', '志野亜貴', 'アキは気取らない母性あふれる性格で、思いやりのある人としても知られています。また、非常に才能豊かなアーティストでもあります。彼女は橋場恭也が指導する映画学科の2年生で、通称「シノアキ」として知られています。', 28, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b197116-IoslUPHFwn33.jpg', '4月19日', NULL, '古賀葵', NULL, 197116, 'MAIN', 783) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023188', 'AN2026', '河瀬川英子', '栄子は、競争心が強く、頑固で、大人びた若い女性であり、映画制作に対する情熱と才能には限界がない。また、少々気難しいところもあるが、姉であり教授でもある加納美早紀を尊敬している。   その一方で、他人の気持ちに寄り添うこともでき、同僚に求めるのと同じ高い基準を自分自身にも課している。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b209536-6tBQDdHQ1D8d.jpg', NULL, NULL, '東山奈央', NULL, 209536, 'MAIN', 465) ON CONFLICT DO NOTHING;
