INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023201', 'AN2027', '兎原跳吉', '彼はステージ上でウサギの衣装を着ている。彼はウラミチの八つ当たりを受ける対象であり、そのため、ウサハラは彼を恐れている。ウラミチを恐れているため、ウサハラはマスクをあまり外さないようにして、彼との視線を合わせないようにしている。 宇佐原は裏で浦道について悪口を言い、浦道の存在に気づくと恐怖で身動きが取れなくなってしまう。相方の熊谷みつおは、宇佐原が浦道をどう思っているかを頻繁に浦道に漏らしており、みつおがこれほど簡単に自分を裏切ることに、宇佐原は苛立ちを覚えている。それにもかかわらず、彼は', 28, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b148142-6sFCKKF3lIrr.png', '3月3日', 'O', '杉田智和', 182, 148142, 'MAIN', 357) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023202', 'AN2027', '多田野詩乃', '「ダガ・イケテル」と共に活動する歌唱講師の一人。彼女の名前は「ただの歌手」という意味の駄洒落になっている。  かつては落ち目のポップアイドルだったが、その後カバーシンガーを経て、現在はナイトクラブでジャズシンガーとして活動している。名門音楽学校を卒業したが、不運かタイミングの悪さか、キャリアは不安定なものになってしまった。コメディアンの彼氏とは6年間同棲しており、常に結婚の話ばかりしている。', 32, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b148144-khflgQ8YGvNY.png', '2月8日', 'A', '水樹奈々', 162, 148144, 'MAIN', 177) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023203', 'AN2027', '表田裏道', '彼は教育テレビ番組『ママと一緒に』で、エクササイズインストラクター（または体操の先生）として活躍している。彼の名前には「二面性」を暗示する意味が込められている。  彼は、多くの著名なアスリートを輩出していることで知られる日本体育大学のエリート選手の一人だった。仕事の合間に時間ができたら、筋肉をほぐす時間を楽しむ。そうすることで悩み事を忘れられるからだ。そうしないと、彼は「倒れてしまう」のだ。', 31, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b148145-Nv7IxFkYbarn.jpg', '12月21日', 'AB', '神谷浩史', 175, 148145, 'MAIN', 1433) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023204', 'AN2027', '熊谷みつ夫', '喫煙：やめた　飲酒：はい（酒に強く）　ステージ上ではクマのコスチュームを着ている。', 28, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b148143-yaExSHhHw3Dh.png', '6月13日', 'A', '中村悠一', 176, 148143, 'MAIN', 602) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023205', 'AN2027', '蛇賀池照', '喫煙：体が持たない　お酒：信じられないほど弱い　田野野宇多野と共に歌の講師を務めている一人。その名前は「でも僕はイケメン」という意味の駄洒落になっている。 美しい歌声と、女の子が抗えないルックスを持つ元ミュージカル俳優。低レベルな駄洒落が大好きで、言外の意味やほのめかしを察することができない。時計の読み方さえ分からない。フードに執着しており、常にフードのことばかり考えている。', 27, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b148141-QKQQb0GNftWM.png', '4月15日', 'O', '宮野真守', 184, 148141, 'MAIN', 635) ON CONFLICT DO NOTHING;
