INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023212', 'AN2027', '木角半兵衛', '彼はMHKの営業企画部に所属し、商品開発を担当している。かつてバンドのメンバーだった彼は、長い髪にたくさんのピアスをしている。一見、感情の起伏が激しいように見えるが、実は仕事に真剣に取り組んでいる。', 24, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b186198-utH8eTUESQL0.png', '1月11日', 'O', '木村良平', 178, 186198, 'SUPPORTING', 256) ON CONFLICT DO NOTHING;
