INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023217', 'AN2028', 'ジャヒー', 'ジャヒーはもともとダークレルムの副司令官でした。しかし、マナクリスタルが破壊された後、彼女は小さくて愛らしい少女になってしまいました！現在はウェイトレスのアルバイトをしています。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b124618-wsHo2rR91A9V.png', NULL, NULL, '大空直美', NULL, 124618, 'MAIN', 1334) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023218', 'AN2028', '涼', 'ジャヒーが住んでいるマンションの管理人。彼女の姉は、ジャヒーが働いているレストランのオーナーである。彼女は家賃を回収するためなら暴力も厭わず、姉とは異なり、いつでもジャヒーを路頭に放り出す覚悟がある。 しかし、大家は姉を恐れており、その弱みをジャヒーは時折利用している。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b133103-RvqNYl4F2akN.jpg', NULL, NULL, '日笠陽子', NULL, 133103, 'SUPPORTING', 138) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023219', 'AN2028', '魔王', '闇界の支配者であり、ジャヒーにとって唯一の上司であった人物。マナクリスタルの破壊に伴い消滅したが、後に神宮京子の手によって復活した。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b157951-8QZvFaVcHMHp.jpg', NULL, NULL, '岡咲美保', NULL, 157951, 'SUPPORTING', 95) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023220', 'AN2028', 'ちさ', 'ジャヒーが働いているレストランのオーナーです。彼女の姉は、ジャヒーが住んでいるアパートの大家さんです。彼女はジャヒーのことを気遣ってくれる優しい人です。ジャヒーが「そうじゃない」と言っても、ついジャヒーを「ハイちゃん」と呼んでしまう傾向があります。 ジャヒーが変身できることを知ったとき、彼女はジャヒーがさらに可愛く思えた。彼女はジャヒーを恐れることなく、むしろ彼女の境遇に共感している。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b133105-KIQgMplUFhoC.jpg', NULL, NULL, '茅野愛衣', NULL, 133105, 'SUPPORTING', 201) ON CONFLICT DO NOTHING;
