INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023222', 'AN2028', 'ドゥルジ', 'かつては闇の領域の住人だった。ジャヒーの忠実な使用人として、彼女は主人のためならどんなことでも喜んで行う。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b133104-cyO5IF7xaa2U.png', NULL, NULL, '花澤香菜', NULL, 133104, 'SUPPORTING', 220) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023223', 'AN2028', 'スー', '彼女は、神宮京子を魔法少女に変え、闇の世界からすべてのマナクリスタルを奪い取った、謎めいた光の存在である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b258831-glPHV3sWWefb.png', NULL, NULL, '鬼頭明里', NULL, 258831, 'SUPPORTING', 50) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023224', 'AN2028', '心', 'ジャヒーと同じ町に住む若い少女。ジャヒーと出会った際、彼女は「闇の領域」を復活させるためにマナクリスタルを探す手助けをすることに同意した。彼女とジャヒーはすぐに親友になった。ジャヒーは、自分を理解してくれる数少ない人物の一人として彼女を頼りにしている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n133106-o4MDUjB3x7Xa.jpg', NULL, NULL, '小倉唯', NULL, 133106, 'SUPPORTING', 54) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023225', 'AN2028', 'サルワ', 'かつてはダークレルムの精鋭だった。人間界へと送り込まれ、そこで今もジャヒーを倒そうと奮闘している。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b133107-fEBCGVHlOcGg.png', NULL, NULL, '小松未可子', NULL, 133107, 'SUPPORTING', 154) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023226', 'AN2028', '神宮きょうこ', 'ジャヒーの故郷の惑星を破壊した者。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b133102-mU3qfdTnRIff.jpg', NULL, NULL, '上坂すみれ', NULL, 133102, 'SUPPORTING', 119) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023227', 'AN2028', 'おじさん', '店長と親の叔父。海辺で焼きそば屋を営んでいる。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b254315-1fpIdBm6QzwS.png', NULL, NULL, '佐々木義人', NULL, 254315, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
