INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023231', 'AN2029', 'ヒューゴ', 'かつてスリだったヒューゴは、今では真っ当な道を歩み、サーカスでザインやカフと一緒に働いている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b329732-aoQsqjnB9MBu.png', NULL, NULL, '石上静香', NULL, 329732, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
