INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023234', 'AN2029', 'マクファーレン', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b244806-JEWBsKydP11M.png', NULL, NULL, '杉田智和', NULL, 244806, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023235', 'AN2030', 'カタリナ・クラエス', '魔法属性：土　『フォーチュン・ラバー』のメインヴィランだが、日本の学生だった前世の記憶を取り戻した後、性格が劇的に変化し、以前よりずっと親切で謙虚な人物になった。　ゲーム解説：典型的な悪役のヒロイン。 わがままで甘やかされて育ったお姫様タイプ。幼少期にジェラルド王子に傷を負わされたことをきっかけに、二人は婚約することになった。この傷跡を理由に、彼女は王子を自分のものだと考え、彼を自分に縛り付けようとした。さらに、彼女は', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b129137-jTXVGAICPfvX.png', '6月24日', NULL, '内田真礼', NULL, 129137, 'MAIN', 2116) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023236', 'AN2030', 'ジオルド・スティアート', '魔法属性：火　ジェラルドはこの国の第三王子であり、カタリーナの婚約者である捕獲対象だ。一見、典型的な金髪・青い目の王子様に見えるが、カタリーナは彼の内面は実は邪悪でサディスティックな王子だと考えていた。  しかし、ゲーム内のジェラルドは本来「カタリナには全く興味がなく、ほとんど彼女の元を訪れない」設定だったにもかかわらず、彼女が気づく前から、3日に1回は彼女の家にやって来ていた。さらに、彼はカタリナの収穫の手伝いまでしている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b129134-k5VKLftg6lk1.jpg', '8月20日', NULL, '蒼井翔太', NULL, 129134, 'MAIN', 316) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023237', 'AN2030', 'キース・クラエス', '魔法属性：土　キースは、その強力な魔法の力ゆえに7年前にクレス家に引き取られた捕獲対象である。亜麻色の髪と青い瞳を持つハンサムな少年だが、継母や義理の姉から疎まれていたため、孤独な幼少期を過ごし、そのせいでプレイボーイ的な性格になってしまった。 そして学校に入学すると、ヒロインによってその孤独は癒やされ、恋に落ちるはずだったが、それを防ぐためにカタリーナは彼をその状況から引き離し続けてきた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b129135-uqhFY8QlsNBe.png', '12月28日', NULL, '柿原徹也', NULL, 129135, 'MAIN', 331) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023238', 'AN2030', 'アラン・ステイア一 ト', '魔法属性：水　アランはこの国の第四王子であり、ジェラルドの双子の弟であると同時に、捕獲対象でもある。銀色の髪と青い瞳を持つ、野性味あふれる美形の王子だが、常にジェラルドと比較され、 そのため、常に劣等感に苛まれているはずで、本来なら兄を憎んでいる設定になるはずだったが、今のアランは劣等感など全く気にしていない様子で、ジェラルドを憎んでいるようにも見えなかった。カタリナ', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b129136-TD43peyVWvON.jpg', '8月20日', NULL, '鈴木達央', NULL, 129136, 'MAIN', 470) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023239', 'AN2030', 'ニコル・アスカルト', '魔法タイプ：風　乙女ゲーム『フォーチュン・ラバー』の4人目の攻略キャラクター。  彼は、無口で無表情な首相の息子であり、攻略対象の一人でもある。 黒髪に黒瞳、完璧な人形のような顔立ちで、その独特な雰囲気から男女問わず虜にしてしまう、悪魔的な魅力を持つ美少年だ。  ゲーム解説：首相の息子であるニコール・アスカロットは、アランとジェラルドの幼なじみ。ヒロインより1歳年上で、無口な先輩である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b129138-RPrD5nPakxZl.jpg', NULL, NULL, '松岡禎丞', NULL, 129138, 'MAIN', 374) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023240', 'AN2030', 'メアリ･ハント', '魔法属性：水　乙女ゲーム『フォーチュン・ラバー』に登場するハント侯爵の四女。気弱で頼りない性格で、本来はカタリナとは接点がないはずだった。メアリーはアランの婚約者であり、彼のルートにおけるライバルキャラクターでもある。 赤褐色の髪と人形のような瞳を持つ美女だ。ゲームの設定上、彼女はカタリナ・クラエスをあまり高く評価しておらず、アランと同様にカタリナとはほとんど接点がないはずだったが、今ではすでにカタリナの親友の一人となっている。（出典：Destruction Flag Otome）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b129139-o7zD077wZmC7.png', '11月4日', NULL, '岡咲美保', NULL, 129139, 'MAIN', 288) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023241', 'AN2030', 'ソフィア･アスカルト', '魔法属性：風　ソフィアは、ニコルの妹であり、ニコルの道を巡るライバルでもある。兄と同じくらい美しい彼女は、本来ならカタリーナと関わるべきではなかったが、今では彼女の仲間となり、メアリーと同様に、最も親しい友人の一人となっている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b129140-CRjj8EuYvLHu.png', '2月26日', NULL, '水瀬いのり', NULL, 129140, 'MAIN', 419) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023242', 'AN2030', 'マリアキャンベル', '魔法タイプ：光　マリア・キャンベルは、ゲーム『フォーチュン・ラバー』の主人公だった。マリアは一生懸命に働き、家事を積極的にこなし、決して文句を言ったりわがままを言ったりすることはなく、必死に勉強に励んだ。魔法学校に入学した際、自分が唯一の平民であることを知って、長年にわたる魔法学校への憧れはたちまち打ち砕かれた。 さらに、平民でありながら魔法の力を持っているという「厚かましさ」を理由に、いじめられることさえあった。  （出典：破壊フラグ乙女W', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b129141-UrYoTJeC9aNi.png', '9月10日', NULL, '早見沙織', NULL, 129141, 'MAIN', 332) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023243', 'AN2030', 'シリウス･ディーク', '魔法タイプ：風　マジック・アカデミーの生徒会長。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b129142-npkf9wsVZ88m.png', '1月21日', NULL, '増田俊樹', NULL, 129142, 'SUPPORTING', 128) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023244', 'AN2030', 'ジンジャー・タッカー', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b245097-NDcAtaBTYJA0.jpg', NULL, NULL, '高尾奏音', NULL, 245097, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023245', 'AN2030', 'アン・シェリー', 'アン・シェリーはカタリナ・クラエスの専属メイドであり、8歳の頃から彼女に仕えている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b162908-Nxj23ESWeY1i.png', '10月14日', NULL, '和氣あず未', NULL, 162908, 'SUPPORTING', 85) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023246', 'AN2030', 'フレイ・ランドール', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b245096-FoHUtUrOHUd6.jpg', NULL, NULL, '潘めぐみ', NULL, 245096, 'SUPPORTING', 18) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023247', 'AN2030', 'ソラ・スミス', '魔法タイプ：火／闇。ソラ・スミスは『フォーチュン・ラバーII～魔法省での恋～』の新たな捕獲ターゲットです。ソラはメインキャストの中で群を抜いて最強のキャラクターです。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b189314-Kusm0n6PFjpS.jpg', '9月25日', NULL, '鳥海浩輔', NULL, 189314, 'SUPPORTING', 108) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023248', 'AN2030', 'スザンナ・ランドール', 'スザンナ・ランドールはジェフリー・スティアート氏の婚約者である。二人は互いに好意を抱いていないものの、婚約者としての関係を維持してきた。セレナ・バークによれば、彼女は国内で最も知的な女性として称賛されているという。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b191067-uuEMpEZi8ePS.png', NULL, NULL, '上坂すみれ', NULL, 191067, 'SUPPORTING', 30) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023249', 'AN2030', 'サラ', '魔法の素質に恵まれた闇魔法使い。ディーク家による実験の対象となった子供たちは番号で分類されていたため、彼女には本名がない。サラは仮名である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b253682-Z4XzXN0vXlMH.png', NULL, NULL, '悠木碧', NULL, 253682, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023250', 'AN2030', 'イアン・スティアート', 'イアン・スチュアートは、『次の人生は悪役ヒロイン！　すべての道はドムへ通ず！』に登場する脇役です。彼はスチュアート兄弟の次男であり、王位継承の有力候補の一人です。また、ゲロルドとアランの兄でもあります。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b191071-fiGfyevA5VMR.png', NULL, NULL, '白井悠介', NULL, 191071, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023251', 'AN2030', 'ルイジ・クラエス', 'カタリーナの実の父であり、キースの養父。公爵であると同時に、クラーエス家の現当主でもある。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b175946-HnCEaLolGzSv.png', NULL, NULL, '横山拓人', NULL, 175946, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023252', 'AN2030', 'セリーナ・バーグ', 'セレナは、デューク・バーグの長女として生まれた。幼い頃からイアン王子と親交があり、年齢が近かったこと、そして魔法を使えることから、彼の婚約者に選ばれた。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b191068-rzWtjxyEDzVN.png', NULL, NULL, '小倉唯', NULL, 191068, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023253', 'AN2030', 'ミリディアナ・クラエス', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b176883-cY696tJhb6oy.png', NULL, NULL, '平松晶子', NULL, 176883, 'SUPPORTING', 32) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023254', 'AN2030', 'ジェフリー・スティアート', 'ジェフリー・スティアートは、スチュアート兄弟の長男であり、ソルシエ王国の初代皇太子である。彼はゲロルドとアランの兄にあたる。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b191074-buyWNqqUB6oE.png', NULL, NULL, '子安武人', NULL, 191074, 'SUPPORTING', 25) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023255', 'AN2030', '佐々木敦子', '「Aちゃん」の愛称で知られる佐々木敦子は、前世でカタリーナの親友だった。小学校時代、敦子はよくからかわれたり、無視されたり、持ち物を隠されたりしていた。周囲から仲間外れにされていたため、彼女は引きこもりがちになり、他人を恐れるようになった。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b191066-nKHwzcWTsqQn.jpg', NULL, NULL, '水瀬いのり', NULL, 191066, 'SUPPORTING', 36) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023256', 'AN2031', '二ノ宮キンジ', '二ノ宮キンジは、とてつもない自信に満ち溢れた若者だ。のんびりとしたニート生活を送れると思った矢先、彼は異世界へと引きずり込まれてしまった。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b179362-22aWYaIMpCxJ.png', NULL, NULL, '小西克幸', NULL, 179362, 'MAIN', 262) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023257', 'AN2031', 'ワニベ', 'ワニベは、キンジの「一攫千金」計画の一つに巻き込まれた爬虫類だ。今ではキンジの悪ふざけにすっかり巻き込まれている。たいていは手下として利用されてしまうだけの無力な男だが、彼にとってはそれでちょうどいいようだ。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b206200-UUdtg1Rew88n.png', NULL, NULL, '下野紘', NULL, 206200, 'MAIN', 46) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023258', 'AN2031', 'リム', 'リムは、しばしば小さな女の子の姿をとる獰猛なドラゴンだ。美味しい餌をくれるという約束と引き換えに、彼女はキンジを助ける。彼女は食欲が旺盛だ。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b206201-tBblWnboyUwu.png', NULL, NULL, '久野美咲', NULL, 206201, 'MAIN', 431) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023259', 'AN2031', 'ランガ', 'ランガは、女々しい男性魔法使いだ。彼は、現在の時代の先祖に正気を取り戻させるため、二ノ宮キンジに付き従って、めちゃくちゃになった未来からやって来た。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b215100-2w54reeIVQRM.png', NULL, NULL, '市道真央', NULL, 215100, 'MAIN', 85) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023260', 'AN2031', 'キノウ・シア', 'キノウ・シアは『迷宮ブラックカンパニー』の主要な主人公の一人である。彼女はダンジョンの第5フロアを攻略し、「賢者の石」を手に入れたことで知られる英雄である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b215101-44B9YLucJZiu.png', NULL, NULL, '戸田めぐみ', NULL, 215101, 'MAIN', 128) ON CONFLICT DO NOTHING;
