INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023284', 'AN2032', '白柳啓', '能力：相手が自分に「ある」と信じている能力を、その通りに発揮できる。 白柳アキラは、ゲームと金平糖が大好きな高校生だ。 退屈な日常にうんざりしていた彼は、自分に挑戦できる何かを見つけようと、数多くのゲームを試していた。 しかし、自らを「魅音」と名乗る謎の少女に突然戦場へと引きずり込まれたことで、状況は一変する。参加者たちは、「戸籍から抹消され、ある実験の対象となり、特定の能力を得た」と告げられる。そして彼らは、c', 16, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b149858-QR7s23PGa2Ab.png', '4月7日', NULL, '村瀬歩', NULL, 149858, 'MAIN', 313) ON CONFLICT DO NOTHING;
