INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023317', 'AN2033', 'フェナ ・ハウトマン', '主人公のフェナは、シャングリラと大英帝国から逃れてきた王女である。彼女は旅の仲間として「七人の侍」と呼ばれる侍や忍者の集団を募り、その隊長となる。色白の肌とプラチナ色の髪で知られており、そのため「ホワイト・マーギナル」というあだ名で呼ばれている。  トラウマ的な過去を抱えながらも、明るく楽観的な性格の持ち主だ。後に、ユキマルとその率いる侍・忍者のグループを仲間に引き入れ、フェナを助けるよう説得することで、その勇気と指導力を発揮することになる。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b232347-e1S2QVhahAws.jpg', NULL, NULL, '瀬戸麻沙美', NULL, 232347, 'MAIN', 242) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023318', 'AN2033', 'オットー', 'ホットマン家に仕えた年配の騎士で、若い頃はその素早い剣さばきから「オットー・ザ・ブリッツ」という威圧的なあだ名で知られていた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b232360-nz9x8keW7xlf.png', NULL, NULL, '平田広明', NULL, 232360, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023319', 'AN2033', 'コーディ', 'アベルの補佐を務める少年。日常生活から来客への対応まで、あらゆることを難なくこなす。西洋の人形のような丸みを帯びた顔立ちをしている。（出典：公式サイト、翻訳）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b248021-WoDOKBslUX5B.jpg', NULL, NULL, '八重畑由希音', NULL, 248021, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023320', 'AN2033', 'チン・シー', '「ランブル・ローズ」に所属する女性海賊。常に冷静で、オマリーの右腕であり、首席戦略家とも見なされている。物理攻撃に長けており、左目に大きな剣傷がある。（出典：公式サイト、翻訳）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b248925-QbWyF7BeFGRU.jpg', NULL, NULL, '金田愛', NULL, 248925, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023321', 'AN2033', 'シタン', 'シタンは、フェナの冒険に協力し、彼女に加わる七人の侍の一人である。彼は無愛想だが気さくで、仲間への強い思いやりを持つ人物として描かれている。また、仲間たちと共にフェナのパーティーに加わった際、シタンは仲間たちに対して忠誠心と献身的な姿勢を見せている。  当初、彼はフェナとその仲間たちを見捨てることを決意するが、説得されて彼らを裏切り、フェナの救出に協力することになる。彼は、草薙の剣を求めて日本から派遣された遠征隊の子孫としての民族意識よりも、友人たちへの忠誠を重んじている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b232348-oJmZ4HPM7AyI.jpg', NULL, NULL, '櫻井孝宏', NULL, 232348, 'SUPPORTING', 115) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023322', 'AN2033', '椿', 'グループの中で最年長かつ最も大人びたメンバーであり、みんなの奔放なエネルギーをうまくまとめ上げている。リーダーでもあるが、戦うときは短めの忍刀を使う。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b232361-Z8qToHX6mDKi.png', NULL, NULL, '大須賀純', NULL, 232361, 'SUPPORTING', 26) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023323', 'AN2033', 'グレース・オマリー', '海賊団「ランブル・ローズ」を率いる女性船長。神々しい美貌の持ち主で、意志が強く、競争心が旺盛で、野心家でもある。ある人物の依頼を受け、フェナを標的にしている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b248024-008AppzvoYlG.jpg', NULL, NULL, '深見梨加', NULL, 248024, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023324', 'AN2033', '船長', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b248929-pb8CB4aAZSi0.jpg', NULL, NULL, '中田譲治', NULL, 248929, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023325', 'AN2033', '炎呪', '楓の双子の兄。二人とも戦闘では槍と脇差を使う。二人とも人懐っこくていたずら好きだが、炎呪は弟よりも自分の方が頼りになると感じている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b232351-OCXHO0K7K66L.png', NULL, NULL, '佐藤元', NULL, 232351, 'SUPPORTING', 54) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023326', 'AN2033', 'アンジー', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b244370-lmvhl3tf7Y8b.jpg', NULL, NULL, '高宮彩織', NULL, 244370, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023327', 'AN2033', 'メアリ・リード', '「ランブル・ローズ」に所属する女性海賊。乗組員の中では改造の達人であり、トラブルメーカーでもある。体力トレーニングに長けており、明るく楽天的な性格だが、戦闘中は激しい気性を露わにする。（公式サイトより、翻訳）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b248922-P6mBouRqUYEk.jpg', NULL, NULL, '七瀬彩夏', NULL, 248922, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023328', 'AN2033', 'ヘレナ', 'ジャンヌ・ダルクの末裔であり、フェナ・ハウトマンの母でもある、気品あるフランス人女性。彼女はアベル・ブルーフィールドの幼なじみであり、かつての恋人でもある。   彼女は、イングランド王を誘惑し、新たな「ラ・プルセル」（新たな乙女の父は王でなければならないため）を産み出すという使命を帯びてイングランドへやってきた。 ヘレナの任務を助けるため、王の執事になりすましたフランツと共に、より安全な国（おそらくオランダ）へ逃亡した。しばらくして彼女は戻り、愛され、', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b250557-1nEfSGtobhm9.jpg', NULL, NULL, '坂本真綾', NULL, 250557, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023329', 'AN2033', 'まかば', 'この巨漢の少年は、ブラスナックルを使って至近距離での戦いを好む。戦っていないときは、心優しく、物腰が柔らかい。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b232353-joCL0K9yeCRX.png', NULL, NULL, '田中進太郎', NULL, 232353, 'SUPPORTING', 28) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023330', 'AN2033', 'マックスカイバーJr.', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b244368-vfqpTWHTQoAl.jpg', NULL, NULL, '津田健次郎', NULL, 244368, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023331', 'AN2033', 'アルビダ', '「ランブル・ローズ」に所属する女性海賊。非常にほっそりとした体つきで、謎めいた雰囲気を漂わせている。狡猾な手口や、相手を翻弄することに長けている。（出典：公式サイト、翻訳）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b248924-qpbgTrlqEGTI.jpg', NULL, NULL, '日野まり', NULL, 248924, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023332', 'AN2033', 'サルマン', 'かつて槍の腕前が凄まじかったことから「サルマン・ザ・オンスラウト」と呼ばれていた年配の騎士。彼はかつてホットマン家に仕えていたため、フェナが少女の頃から彼女を知っている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b232354-jcz39x8e6K01.png', NULL, NULL, '村治学', NULL, 232354, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023333', 'AN2033', 'アベル・ブルーフィールド', '独自の目的でフェナを追跡し、自身の船「ブルー・ジャイアント」で彼女を探し回っている謎めいた領主。その理由の一つは、フェナの亡き母ヘレナに恋をしたことであり、彼女の家族が持つ能力を知っているからだ。 彼はフェナを見つけるために「ランブル・ローズ」と手を結ぶが、約束された報酬が支払われなかったことを受け、オマリーが報復に出るまでその同盟は続いた。ランブル・ローズが攻撃を仕掛ける前に、アベルは部下に命じ、「ブルー・ジャイアント」に搭載された包囲戦用のウェリントン砲を敵船に向けて発射させた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b244369-qUpRQpnYbU0Q.jpg', NULL, NULL, '森川智之', NULL, 244369, 'SUPPORTING', 23) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023334', 'AN2033', 'シャーロッテ・ベリー', '「ランブル・ローズ」号に所属する女海賊。レイピアと三日月型の剣を武器とし、可愛らしい外見とは裏腹に、心は黒く邪悪だ。乗組員の中で誰よりもオマリーを慕っている。（出典：公式サイト）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b248919-4ZS9vHhAvJIP.jpg', NULL, NULL, '薮内満里奈', NULL, 248919, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023335', 'AN2033', '幽鬼丸', 'ユキマルは、「七人の侍」のリーダーであり、フェナの旅に協力し、共に戦う。ユキマルは内向的で、無口な性格だ。幼い頃から知り合いのフェナ・ハウトマンを、誰よりも大切に思っている。 また、仲間である侍忍者たちと行動を共にする際、戦闘中であってもリーダーシップを発揮する。  これまで笑顔を見せたことは一度もないが、フェナへの想いをからかわれると、耳を赤らめる。フェナを守ることが何よりも重要だと感じているが、彼は恐れることはない。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b232355-wUpfLzRaiYSp.png', NULL, NULL, '鈴木崚汰', NULL, 232355, 'SUPPORTING', 238) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023336', 'AN2033', '真田幸久', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b244371-IJh4KKoG3oKz.jpg', NULL, NULL, '大塚芳忠', NULL, 244371, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023337', 'AN2033', 'ハンナ・スネル', '「ランブル・ローズ」に所属する女性海賊。小柄だが、非常に腕の立つ狙撃手である。オマリーを尊敬しているため、眼帯をしている。（出典：公式サイト、翻訳）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b248920-y8JhnqOrQhJz.jpg', NULL, NULL, '河野ひより', NULL, 248920, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023338', 'AN2033', '香燐', '鍛冶屋の家庭で育った香燐は、自分のライフルのようなテクノロジーに夢中であり、戦闘ではそれを巧みに活用している。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b232356-o6tzOelE1CZv.png', NULL, NULL, '悠木碧', NULL, 232356, 'SUPPORTING', 86) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023339', 'AN2033', '村長', 'アリアの祖父。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b245933-NbebOgwlKVm5.jpg', NULL, NULL, '島田高虎', NULL, 245933, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023340', 'AN2033', 'アン・ボニー', '「ランブル・ローズ」号に所属する女性海賊。筋肉質な体格で、非常に力強い。戦闘スタイルは好戦的だが、信頼でき、仲間思いの乗組員である。（出典：公式サイト、翻訳）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b248923-wrPMgTJ9a2hI.jpg', NULL, NULL, '森谷彩子', NULL, 248923, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023341', 'AN2033', '楓', '炎呪の双子の弟。二人とも戦闘では槍と脇差を使う。二人とも人懐っこくていたずら好きだが、楓は自分の方が兄よりも男らしいと感じている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b232357-k649311To1r5.png', NULL, NULL, '逢坂良太', NULL, 232357, 'SUPPORTING', 51) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023342', 'AN2033', 'アリア', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b245932-QlQpuwS8OdYX.jpg', NULL, NULL, '石川由依', NULL, 245932, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023343', 'AN2033', 'アルテミシア', '「ランブル・ローズ」に所属する女性海賊。端正な顔立ちだが、プライドが高く、勝利への執念が強い。短剣を武器に、全力を尽くして戦う。（公式サイトより、翻訳）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b248921-doQgce2ZisWv.jpg', NULL, NULL, '茉莉邑薫', NULL, 248921, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023344', 'AN2034', '早乙女あてな', 'アテナは男の子たちから隔離された環境で育った。そのため、男の子のそばにいることさえ耐えられず、男の子に触れるとひどい鼻血が出てしまう。', 19, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b205447-zoZVjZpk77EG.png', '4月26日', 'B', '七瀬彩夏', NULL, 205447, 'MAIN', 329) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023345', 'AN2034', '南雲孝士', 'コシは年齢の割に非常に責任感が強く、大人びている。父親に見捨てられた後も、落ち込んだものの、仕事を探そうとした。寮の寮母として働き始めた際、寮生たちは自分より年上だったにもかかわらず、彼はためらうことなく彼女たちを叱った。 彼は、自分もまだ少年であり、性的な欲求もあるため、彼女たちに行動や服装にもっと気を付けるよう警告さえしようとする。誕生日の日、コシの家が全焼し、金銭的余裕がなかったため、父親は彼を見捨てて去ることを決めた。路上でさまよっていた彼は、', 12, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b205451-tNPnvSuDz37d.png', '3月10日', 'A', '山田美鈴', NULL, 205451, 'MAIN', 60) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023346', 'AN2034', '和知みねる', 'ミネルは、青館の「女神寮」に住む4年生だ。ミネルは有毒ガスを扱うのが大好きな研究者だが、そのせいで実験に失敗することが多い。', 22, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b205448-pFJZIu8Rk1iN.png', '9月30日', 'O', 'たかはし智秋', NULL, 205448, 'SUPPORTING', 154) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023347', 'AN2034', '八月朔日せれね', 'セリーンは謎めいていて、気さくで、おとなしい性格だ。普段は学校に行くとき以外は寮から出ないが、コシの助けもあって、なんとかみんなと一緒に旅行に行くことができた。彼女の部屋はゴミで溢れているが、彼女によれば、そのゴミが月の技術の研究に必要な「モンエネルギー」を吸収してくれるのだそうだ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b205449-IxKpqvXJ4vIk.png', '10月1日', NULL, '夜道雪', NULL, 205449, 'SUPPORTING', 245) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023348', 'AN2034', '戦咲きりや', 'キリヤは3人の兄たちと共に、武道場で育った。大学に入ってから初めて少女漫画を購入し、たちまちその魅力に夢中になった。 しかし、こうした恋愛物語を読んでいると、つい興奮しすぎてしまうことがよくある。その結果、武術の腕前を駆使して壁を壊してしまうこともある。また、寝相が悪く、寝返りを何度も打つ癖もある。学校では冷静沈着な性格であるため、他の生徒たちの模範となるよう、密かにプレッシャーを感じている。', 20, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b205450-vvb0JlS15V0v.png', '8月23日', 'A', '村井理沙子', NULL, 205450, 'SUPPORTING', 157) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023349', 'AN2034', 'フレイ', 'ファッション好きのフレイは、ドレスを作るのが大好きで、熱心なコスプレイヤーでもあります。彼女は恥ずかしがり屋で、明るい性格です。ただ、時には頑固で意地っ張りな一面も見せます（どんなことがあっても人にその衣装を着せようとする様子からもそれがうかがえます）。', 21, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b205452-Ia7ndDzTk6uN.png', '12月12日', 'B', '福山あさき', NULL, 205452, 'SUPPORTING', 223) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023350', 'AN2034', '香炉野すてあ', 'ステアは南雲孝士の幼なじみだ。彼女はコシに片思いをしていて、すぐに彼のことを心配してしまうが、平気なふりをしている。彼女は熱に敏感な体質で、触れられるのが嫌いだ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b205453-MusmupA85wu1.png', NULL, NULL, '南條ひかる', NULL, 205453, 'SUPPORTING', 138) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023351', 'AN2035', '宮沢風花', 'フカは元アイドルだ。彼女は夢を諦め、故郷へ帰る途中で沖縄へ向かった。そこで、ククルと出会った。フカは真面目で努力家だ。また、他人の気持ちにも敏感である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b204496-pt228Q8Acp9l.png', '5月17日', NULL, '逢田梨香子', NULL, 204496, 'MAIN', 321) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023352', 'AN2035', '海咲野くくる', 'ククルは、沖縄にある小さな「ガマガマ水族館」の館長を務める高校生だ。率直で明るい性格の持ち主である。誰よりも水族館に深い愛着を抱いているククルは、生き物に関することになると、厳しい言葉も厭わないプロとしての側面も持っている。ファッションには疎い。  ククルは、閉館の危機に瀕している「ガマガマ水族館」の再生に奮闘している。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b204495-kz9jYD5p7zgu.png', '7月7日', NULL, '伊藤美来', NULL, 204495, 'MAIN', 407) ON CONFLICT DO NOTHING;
