INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023357', 'AN2035', '米倉マリナ', 'マリーナは、まるで太陽のような元気いっぱいの女の子です！ベネズエラにルーツがあり、時々スペイン語を話します。誰とでも気兼ねなく話せる性格で、海の生き物たちと過ごす時間をとても楽しんでいます。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b249344-6s9jJ9d52w8T.png', NULL, NULL, '東山奈央', NULL, 249344, 'SUPPORTING', 21) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023358', 'AN2035', '三浦響子', 'ククルスの最初のプランを却下したものの、2つ目のプランに心を奪われてしまうウェディングプランナー。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b258189-mhG89a0YAgAc.jpg', NULL, NULL, '中原麻衣', NULL, 258189, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023359', 'AN2035', '照屋月美', '月見はククルの同級生で、小学校の頃から親友だ。彼女は、母親が経営するレストラン「カメ」を手伝う、優しい女の子だ。友達がよく店に集まってくるため、彼女のあだ名は「うどんちゃん」だ。 気さくで穏やかな性格だが、周囲のこともよく気遣うため、誰からも愛されている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b217015-ZYuTIy9TIN9P.png', NULL, NULL, '和氣あず未', NULL, 217015, 'SUPPORTING', 56) ON CONFLICT DO NOTHING;
