INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023362', 'AN2035', '城居 ルカ', '「ヨナ・プロ」に所属するアイドルで、宮沢フカが脱退する前は彼女と仲が良かった。彼女は常にフカを尊敬すべき先輩として慕っており、フカのためにアイドル活動に一生懸命取り組む原動力にもしていた。出典：MAL', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b306301-XAW37hunu2mF.png', NULL, NULL, '菊池紗矢香', NULL, 306301, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023363', 'AN2035', '久高夏凛', 'カリンは、地元の観光協会で働く公務員です。水族館の手伝いもする、頼りになるお姉さん的存在です。ククルたちにとっては「年上の友人」のような存在です。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b217016-eUrt1ZD0TYfs.png', NULL, NULL, 'Lynn', NULL, 217016, 'SUPPORTING', 34) ON CONFLICT DO NOTHING;
