INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023366', 'AN2035', '屋嘉間志空也', 'ガマガマ水族館のスタッフ。物言いは率直で、のんびりした印象だが、仕事には非常に真面目だ。同年代の女の子と話すのが苦手で、彼女たちとの目線を合わせないようにすることが多い。 水族館は人手不足のため、彼は長時間のシフトをこなしており、疲れ切っている。ククルの祖母が作る梅酒をとても気に入っている。（出典：Anime News Network）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b226106-p8Q3Kv0jYFB9.png', NULL, NULL, '阿座上洋平', NULL, 226106, 'SUPPORTING', 102) ON CONFLICT DO NOTHING;
