INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023369', 'AN2035', '仲村櫂', 'ククルの同級生であり、幼なじみ。漁師の父親を手伝い、日の出前に一緒に船に乗り出し、その日の漁獲物をミサキノ家に届けている。ククルの長年の親友であり、夏の間は「ガマガマ水族館」でボランティアとして働いている。  （出典：Anime News Network）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b226107-dnplJMFbwAyf.png', NULL, NULL, '土屋神葉', NULL, 226107, 'SUPPORTING', 86) ON CONFLICT DO NOTHING;
