INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023372', 'AN2035', 'おじい', 'ククルの祖父で、「ガマガマ水族館」の館長。夏休み期間中、水族館の重要な用事で各地を回る間、水族館の日常業務をククルに任せる。明るく優しい性格の持ち主である。  （出典：Anime News Network）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b226105-ztojNSrc5Epv.jpg', NULL, NULL, '家中宏', NULL, 226105, 'SUPPORTING', 15) ON CONFLICT DO NOTHING;
