INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023378', 'AN2036', '隼人', '種族：神／イダテン　隼人は、約80年前に凛によって「召喚」された新世代の一人であり、凛の下で修行を積んでいるイダテンの一人だが、極めて頭が悪く、自分自身が強くなることしか考えていない。 しかし、前世代への責任感から強くなった凛や、ただ殴られた結果として強くなったプロンテアとは異なり、彼は純粋に力を求めるイダテンとして、最強になる可能性を秘めている。彼はよく凛を侮辱し、彼を', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b207747-XwHFSfMV9dLu.png', '10月14日', NULL, '朴璐美', NULL, 207747, 'MAIN', 115) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023379', 'AN2036', 'イースリイ', '種族：神／イダテン　イスリーは、約100年前に自然発生した現象の結果として生まれたイダテンである。 彼はイダテン側の頭脳とも言える存在で、戦うことよりも研究を好むが、自然発生した存在であるため、「自分自身について知る」ための研究を始めた。  凛のもとで修行を試みたが、その訓練が過酷な拷問に等しいと感じ、始めてからわずか2～3ヶ月で辞めてしまった。彼は、過去の人類文明や遺跡について研究するのが好きだ。ある魔法の生物が現れた後、彼は', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b207746-KiREJWZRW7tS.png', '11月23日', NULL, '緒方恵美', NULL, 207746, 'MAIN', 103) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023380', 'AN2036', 'ポーラ', '種族：神／イダテン　ポーラは、凛の弟子であるプロンテアに「召喚」された後、約16年前に誕生した。彼女は戦うことよりも鳥たちと会話することを好み、音も立てずに動くのが得意だ。  鳥たちから、北の方で人間たちが集まっていると聞いたポーラが確認に行くと、人間たちが悪魔を復活させようとしていることが判明した。ポーラにはその悪魔の相手はできなかったが、隼人がそれを倒した。 イースリイは凛のもとで修行することを提案し、ポーラは同意したが、イースリイが凛の厳しさを大げさに言っているのだと思っていた。しかし、', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b207748-akbODM0j7wA9.png', NULL, NULL, '堀江由衣', NULL, 207748, 'MAIN', 85) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023381', 'AN2036', '凛', '種族：神／イダテン　凛は、800年前に悪魔族との戦いで唯一生き残った者である。 彼女はイダテンであり、隼人とプロンテアを「召喚」した張本人である。魔族を封印した封印の印を守りつつ、隼人らを鍛え上げてきた。 彼女の訓練は過酷を極め、隼人や仲間たちを死の淵まで追い込むこともある。普段は封印の近くにいるが、時には召喚スポットを探して世界中を高速で移動することもある。彼女は現在、現存する最強のイダテンであり、', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b207766-BIWrf2kHPQ6U.png', NULL, NULL, '岡村明美', NULL, 207766, 'MAIN', 217) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023382', 'AN2036', 'ピサラ', '種族：悪魔　ピサラはゾブル軍の将軍である。圧倒的な力で軍を率いているが、性的なこととなると純真で恥ずかしがり屋の乙女である。彼女は軍を率いて市民への略奪や強姦を行っていたが、オバミによって首都へ呼び戻された。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b226661-tQQguLeIO95C.png', NULL, NULL, '瀬戸麻沙美', NULL, 226661, 'SUPPORTING', 145) ON CONFLICT DO NOTHING;
