INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023385', 'AN2036', 'ブランディ', '種族：悪魔　ブランディはゾブル帝国の女王である。彼女はニッケルと並んで最強の一人である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b226665-6GSlvDw9WGcV.jpg', NULL, NULL, '本名陽子', NULL, 226665, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
