INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023387', 'AN2036', 'おおばみ博士', '種族：イダテン　帝国ゾブル軍開発局局長。その体は遠隔操作のロボットであり、その正体はゾブル側にとっても謎に包まれている。 自らを「魔王」と称し、ゾブル帝国を隠れ蓑にして悪魔の数を増やそうとしている。かつては「オバマ皇帝」としてゾブルを統治していたが、タケシタに帝位を譲り、死んだふりをして「オバミ」と名乗り、開発局に潜入した。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b207745-HEUwBLVIkXzY.png', NULL, NULL, 'チョー ', NULL, 207745, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023388', 'AN2036', 'ネプト', '種族：デーモン', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b226663-WO7HhtwTCZGE.jpg', NULL, NULL, '天田益男', NULL, 226663, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023389', 'AN2036', 'フェルランディア', '種族：デーモン', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b249209-JIHZf0BI5IXg.png', NULL, NULL, '小林ゆう', NULL, 249209, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023390', 'AN2036', 'みく', '種族：デーモン　みくは、ゾブルの軍隊によって繁殖用奴隷として集められた女性たちを調教する動物調教師である。彼女は並外れた洞察力と知恵を持つ大の変態だが、何よりも官能的な快楽を享受することを最優先している。彼女の瞳には、「知覚」という異常な力が宿っているようだ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b225914-8Etfloi3GFVU.png', NULL, NULL, '伊瀬茉莉也', NULL, 225914, 'SUPPORTING', 216) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023391', 'AN2036', 'タケシタ', '種族：悪魔　ゾブル帝国の皇帝。一見、ごく普通の老人のように見えるが、ゾブル帝国でトップ5に入る強者の一人である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b226659-2nHtE6SZHgoQ.png', NULL, NULL, '宮本充', NULL, 226659, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023392', 'AN2036', 'クライシ', '種族：デーモン', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b249210-1Gdwjv26IUpW.png', NULL, NULL, '木村良平', NULL, 249210, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023393', 'AN2036', 'プロンテア', '種族：神／イダテン　プロンテアは、約200年前に凛によって「召喚」されたイダテンである。凛による120年にわたる訓練の間、彼は一度も攻撃を当てることができなかったため、防御力を高めることができた。 その修行の結果、彼は凛に対してトラウマを抱くようになった。イスリーの依頼により、プロンテアはかつてイダテンが用いた魔法を再現するための修行を行っている。また、隼人の攻撃力を高めるための修行を行った結果、彼を凛と同じような怪物と見なすようになった。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b226660-faakJUIFdcyG.png', NULL, NULL, '石田彰', NULL, 226660, 'SUPPORTING', 57) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023394', 'AN2036', 'ギルティーナ', '種族：人間　ギルは、誰よりも誠実に神を信じ、絶えず祈りを捧げ続けている姉妹です。彼女はとても真面目で親切で、常に自分よりも他人のことを気にかけています。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b230346-yUtvwSJ4Rovx.png', NULL, NULL, '伊藤静', NULL, 230346, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
