INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023401', 'AN2037', 'サルトリーヌ・アルダレイク', 'サルトリーヌ・アルダレイク、通称サリーは、田舎にあるちっぽけな城での生活に飽きてしまい、冒険に出たいと願う、明るく陽気な王女です。   サリーは心優しく、冒険に飢えている。彼女はいつも友達を大切にし、人間と鬼が平和に共存するという目標の実現を切望している。ピーチの目を発動させると、鬼と戦う際のミコトとほぼ同じ姿になる。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b144683-qOUiweknRTBd.png', NULL, NULL, '白石晴香', NULL, 144683, 'MAIN', 165) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH023402', 'AN2037', 'キビツ・ミコト', '彼は、西の大陸にやって来て、遭遇する鬼をすべて倒そうとしている。彼は、一匹の犬と、ミリアという名の鬼を連れて旅をしている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b183792-KfjVH9BJic55.png', NULL, NULL, '東山奈央', NULL, 183792, 'MAIN', 126) ON CONFLICT DO NOTHING;
